import AppKit
import Combine
import Darwin
import SwiftUI
import Testing
@testable import Notchline

struct NotchlineTests {
    /// **The notch-less pill is one width in every connected state.**
    ///
    /// `230` whatever the status, however many rows are open, however many
    /// subagents are in flight, at any menu bar height and whatever the reading
    /// says. V1 answered to all four of those: the marks it drew, the word it
    /// was saying, the column each product had open and the digits in the
    /// timer. This form answers to none of them, because it is centred on the
    /// display and pinned to nothing — every point either end took would be
    /// taken from both edges at once, and the whole of its contents would
    /// travel with them (`compact-view-v2.md` §6.1).
    @Test @MainActor
    func theNotchlessPillIsOneWidthInEveryConnectedState() {
        var widths: Set<CGFloat> = []
        var heights: Set<CGFloat> = []
        let readings = [nil, "0:07", "1:23", "12:05", "10:00:00"] as [String?]
        for status in PanelMetrics.workingStatuses {
            for sessionCount in [0, 1, 9, 10, 99] {
                for trailingText in readings {
                    for barHeight in [CGFloat(46), 38, 24] {
                        let size = PanelMetrics.size(
                            geometry: .noNotch,
                            isExpanded: false,
                            statusReadoutText: status.displayName,
                            trailing: CompactTrailingReading(timerText: trailingText),
                            centerOcclusionWidth: 0,
                            compactHeight: barHeight,
                            status: status,
                            sessionCount: sessionCount
                        )
                        widths.insert(size.width)
                        heights.insert(size.height)
                    }
                }
            }
        }
        #expect(widths == [230])
        // Height still follows the menu bar; only width was ever loose.
        #expect(heights == [46, 38, 24])

        // `Disconnected` is the one state sized to itself: nothing can follow
        // it and there is no product behind it, so neither `8` of clearance
        // applies — each exists only where content stands on both sides of it.
        #expect(PanelMetrics.fixedCompactWidth(for: .disconnected) == 41)
        #expect(
            PanelMetrics.fixedCompactWidth(for: .disconnected) == ceil(
                PanelMetrics.expandedHorizontalPadding
                    + PanelMetrics.statusMatrixSize
                    + PanelMetrics.expandedHorizontalPadding
            )
        )
    }

    /// **The middle is a subtraction, and the only thing on the pill that
    /// moves.**
    ///
    /// The two ends are anchored — the leading group at `33.8` from the leading
    /// padding, the reading's last glyph `12 + 4` from the trailing edge — so
    /// everything the trailing group draws comes out of the name in the middle
    /// and out of nothing else. `9:59 → 10:00` adds its digit at the *leading*
    /// end of the reading and the seconds do not move.
    ///
    /// The figures are `compact-view-v2.md` §6.1's, to a thirtieth of a point:
    /// the board bills a digit at `6.6` and the drawn face measures `6.616`, so
    /// the leading group is `33.83` rather than `33.8` and the middle absorbs
    /// the difference. That is what a subtraction is for.
    @Test @MainActor
    func thePillsMiddleIsWhateverTheAnchoredEndsLeave() {
        func middle(_ text: String?) -> CGFloat {
            PanelMetrics.pillMiddleWidth(
                trailing: CompactTrailingReading(timerText: text)
            )
        }
        for (text, published) in [
            (nil, CGFloat(156.2)),
            ("1:23", 120.2),
            ("12:05", 112.2),
            ("1:00:00", 100.2),
            ("10:00:00", 92.2)
        ] as [(String?, CGFloat)] {
            #expect(abs(middle(text) - published) < 0.05)
        }
        // Every point the reading takes is a point the name gives up, exactly.
        #expect(
            middle(nil) - middle("1:23")
                == PanelMetrics.drawnCompactReadingWidth("1:23")
        )
        // And it never goes negative, however long a reading gets.
        #expect(middle("100:00:00") >= 0)
    }

    /// The collapsed widths in the design, to the point.
    ///
    /// `compact-view-v2.md` §5.2 and §6.3 fix them by measurement rather than
    /// by choice, so they are checkable here against the same fonts the app
    /// draws with. Golden numbers are usually the wrong assertion; here they
    /// are the contract — the doc names them, a board frame is drawn at them,
    /// and a change to padding or to the counts face is supposed to fail loudly
    /// rather than quietly move a bar that lives in the user's menu bar.
    ///
    /// **Four of the nine notched states share one width**, which is the point
    /// of the whole change: V1 grew by `49.26` for every product installed —
    /// `372` at two, `421` at three, `471` at four — on a surface whose
    /// container does not grow with it.
    @Test @MainActor
    func theFixedCompactWidthsAreTheOnesTheDesignMeasured() {
        func notched(
            sessionCount: Int,
            reading: String? = nil,
            drawsMark: Bool = true
        ) -> CGFloat {
            PanelMetrics.size(
                geometry: .notched,
                isExpanded: false,
                statusReadoutText: MonitorStatus.running.displayName,
                trailing: CompactTrailingReading(timerText: reading),
                centerOcclusionWidth: 200,
                compactHeight: 46,
                status: .running,
                sessionCount: sessionCount,
                drawsMark: drawsMark
            ).width
        }

        // Nothing connected: the cut-out and nothing else.
        #expect(notched(sessionCount: 0, drawsMark: false) == 200)
        // Connected with no rows: the mark alone, and no column to count with.
        #expect(notched(sessionCount: 0) == 237)
        // The state this surface spends most of its life in, and the three
        // beside it that share its width: rows and subagents change what the
        // numerals say and not what the bar measures.
        #expect(notched(sessionCount: 3, reading: "1:23") == 304)
        #expect(notched(sessionCount: 2, reading: "1:23") == 304)
        // A second digit is the only thing on the leading side that widens it.
        #expect(notched(sessionCount: 12, reading: "1:23") == 310)
        // And a longer reading, on the trailing side.
        #expect(notched(sessionCount: 3, reading: "12:05") == 312)

        // The pill, both of its two widths.
        #expect(PanelMetrics.fixedCompactWidth(for: .running) == 230)
        #expect(PanelMetrics.fixedCompactWidth(for: .disconnected) == 41)
    }

    /// **The counts column asks for no room the mark did not already have.**
    ///
    /// Two numerals stacked inside one matrix's `16.6`: the sessions cap-top on
    /// its top edge, the subagents baseline on its bottom. That is the test the
    /// session-dot column was built to pass and the reason a numeral set
    /// *beside* the matrix failed it — this column draws identically under a
    /// `46` pt menu bar and a `22` pt one, because it is anchored to the mark
    /// rather than to the bar.
    ///
    /// The board draws a `7.85` cap over a `3.03` gap over a `5.71` cap. The
    /// drawn face measures `7.750` and `5.637`, so the gap is `3.213`; the
    /// stack is stated by its two anchors rather than by the gap, which is what
    /// makes that a re-derivation rather than a discrepancy.
    @Test @MainActor
    func theCountsColumnStandsInsideTheMarksOwnHeight() {
        let matrix = PanelMetrics.statusMatrixSize
        let sessionsCap = PanelMetrics.countsSessionFont.capHeight
        let subagentsCap = PanelMetrics.countsSubagentFont.capHeight

        // With a subagent under it the sessions cap-top is on the matrix's top
        // edge, so the pair fills the mark's height exactly.
        let stacked = PanelMetrics.countsSessionBaseline(hasSubagents: true)
        #expect(abs(stacked + sessionsCap - matrix) < 0.001)
        #expect(PanelMetrics.countsSubagentBaseline == 0)
        // Neither cap leaves the mark's own band.
        #expect(stacked >= 0)
        #expect(subagentsCap <= matrix)
        // And they do not collide: the gap the two anchors leave is real.
        #expect(stacked - subagentsCap > 3)

        // Alone, the numeral is optically centred instead — the same leftover
        // above it as below — and the rise when the first subagent starts is
        // exactly that half.
        let alone = PanelMetrics.countsSessionBaseline(hasSubagents: false)
        #expect(abs(alone - (matrix - sessionsCap) / 2) < 0.001)
        #expect(abs((stacked - alone) - alone) < 0.001)
        // `4.425` at the drawn cap, where the board says `4.375` for a `7.85`
        // one. The rule is "centred"; the figure follows the face.
        #expect(abs(stacked - alone - 4.425) < 0.01)
    }

    /// **The column is billed for the digits it draws, and the numerals fit.**
    ///
    /// Every published width rests on a digit costing `6.6`. The face measures
    /// `6.616` — the board's figure to a hundredth — and the composition ceils
    /// once, so the totals stand. What must not happen is the reverse of that:
    /// a reservation a fraction *short* of the ink, which is the defect
    /// `figma-design.md` §4.6 was written about.
    @Test @MainActor
    func theCountsColumnIsBilledForWhatItDraws() {
        let digit = PanelMetrics.countsDigitWidth
        #expect(abs(digit - 6.6) < 0.05)
        // Tabular, so every digit is the same width and a `1` costs a `8`.
        for figure in 0 ... 9 {
            let width = (String(figure) as NSString)
                .size(withAttributes: [.font: PanelMetrics.countsSessionFont]).width
            #expect(abs(width - digit) < 0.001)
        }
        // The subagent numeral is narrower than the one above it, so it never
        // widens the column.
        let small = ("8" as NSString)
            .size(withAttributes: [.font: PanelMetrics.countsSubagentFont]).width
        #expect(small < digit)

        // Zero is never drawn: no rows, no column, and no gap either.
        #expect(PanelMetrics.countsColumnWidth(sessionCount: 0) == 0)
        #expect(PanelMetrics.countsSlotWidth(sessionCount: 0, reserved: false) == 0)
        #expect(
            PanelMetrics.drawnLeadingGroupWidth(sessionCount: 0)
                == PanelMetrics.statusMatrixSize
        )
        // One digit, then two, and nothing in between.
        #expect(PanelMetrics.countsColumnWidth(sessionCount: 1) == digit)
        #expect(PanelMetrics.countsColumnWidth(sessionCount: 9) == digit)
        #expect(PanelMetrics.countsColumnWidth(sessionCount: 10) == 2 * digit)
        #expect(PanelMetrics.countsColumnWidth(sessionCount: 99) == 2 * digit)
        #expect(
            PanelMetrics.countsColumnWidth(sessionCount: 12)
                == PanelMetrics.reservedCountsColumnWidth
        )
        // The pill holds two digits open whatever it is drawing, including
        // nothing, so a tenth session widens nothing and moves nothing.
        for sessionCount in [0, 1, 10, 99] {
            #expect(
                PanelMetrics.countsSlotWidth(sessionCount: sessionCount, reserved: true)
                    == PanelMetrics.aggregateCountsGap
                        + PanelMetrics.reservedCountsColumnWidth
            )
        }
    }

    /// **Nothing on the collapsed surface is per product any more.**
    ///
    /// The bar moves when the work changes and never because something was
    /// installed. V1 spent three channels per product — a matrix, a session-dot
    /// column and a subagent badge — and grew `49.26` for each one; this is the
    /// same measurement taken across product counts, where it now finds one
    /// number.
    @Test @MainActor
    func theCollapsedBarDoesNotAnswerToHowManyProductsAreInstalled() {
        func width(products: Int) -> CGFloat {
            PanelMetrics.size(
                geometry: .notched,
                isExpanded: false,
                statusReadoutText: MonitorStatus.running.displayName,
                trailing: CompactTrailingReading(timerText: "1:23"),
                centerOcclusionWidth: 200,
                compactHeight: 46,
                status: .running,
                matrixCount: products,
                sessionCount: 3
            ).width
        }
        #expect(Set((1 ... 5).map(width)) == [304])

        func pill(products: Int) -> CGFloat {
            PanelMetrics.size(
                geometry: .noNotch,
                isExpanded: false,
                statusReadoutText: MonitorStatus.running.displayName,
                trailing: CompactTrailingReading(timerText: "1:23"),
                centerOcclusionWidth: 0,
                compactHeight: 46,
                status: .running,
                matrixCount: products,
                sessionCount: 3
            ).width
        }
        #expect(Set((1 ... 5).map(pill)) == [230])
    }

    /// The collapsed surface reports on products, not on us.
    ///
    /// This is the invariant that replaced six thin states with two. The four
    /// retired ones stay in the enum because the expanded panel and Settings
    /// still say them, so the thing worth pinning is not that they are gone but
    /// that the *aggregate* can never return one — including from the seed the
    /// store starts with, which used to publish `Connecting`.
    @Test @MainActor
    func theCollapsedAggregateOnlyEverReachesTheSixReachableStatuses() {
        let retired: [MonitorStatus] = [
            .connecting, .setupRequired, .updateAgent, .unsupportedVersion
        ]
        for status in retired {
            #expect(!MonitorStatus.collapsedReachable.contains(status))
        }

        // Every availability, with and without presence, for one and two
        // products: the aggregate has to land inside the reachable set every time.
        let availabilities: [MonitorAvailability] = [
            .ready, .connecting, .setupRequired,
            .updateAgent, .unsupportedVersion, .disconnected
        ]
        for availability in availabilities {
            for presence in AgentPresence.allCases {
                let one = AgentSnapshot(
                    availability: availability,
                    sessions: [],
                    quota: .unavailable,
                    diagnostic: nil,
                    presence: presence
                )
                let merged = AgentSnapshotMerge.merge([one])
                #expect(MonitorStatus.collapsedReachable.contains(merged.status))
            }
        }

        #expect(
            MonitorStatus.collapsedReachable.contains(MonitorSnapshot.connecting.status)
        )
    }

    /// The retired states did not lose their words, only their place — and
    /// then their product names.
    ///
    /// Four of these used to be told which product they were about, so the
    /// panel could say `Codex disconnected`. None of them are any more: which
    /// product is unhealthy is Settings' job, where every product is listed
    /// with its own state beside it. The sentences stay pinned in their
    /// generic form because the expanded panel and the empty-list message
    /// still say them.
    @Test @MainActor
    func theRetiredThinStatesReadGenericallyWhereTheyStillAppear() {
        #expect(MonitorStatus.connecting.displayName == "Connecting")
        #expect(MonitorStatus.updateAgent.displayName == "Update required")
        #expect(MonitorStatus.unsupportedVersion.displayName == "Version unsupported")
        #expect(MonitorStatus.disconnected.displayName == "Disconnected")
        #expect(MonitorAvailability.disconnected.emptyListMessage == "Disconnected")
    }

    /// No label names a product, in any state.
    ///
    /// This is what let both widths stop folding over configured products.
    /// `Update Claude Code` was the widest compact label and it set the
    /// two-product pill width for a state Claude Code cannot reach (issue #29);
    /// `Claude Code version unsupported` was doing the same to the expanded
    /// panel, ~79pt of it, on every panel a Claude Code user ever opened. With
    /// no label naming a product, what widens either surface is a second matrix
    /// and the cut-out, and nothing else.
    @Test @MainActor
    func noStatusLabelNamesAProduct() {
        for status in MonitorStatus.allCases {
            for agent in AgentKind.allCases {
                #expect(!status.displayName.contains(agent.displayName))
            }
        }
    }


    /// The resting grey must be the darkest thing on the surface.
    ///
    /// The ordering is the whole reason `#151515` was picked: "an agent is
    /// connected" must never look dimmer than "nothing is connected", or the
    /// presence channel reads backwards. Asserted as relative luminance rather
    /// than as a hex string, because that is the property that has to hold.
    ///
    /// **Checked against the one theme ink**, now that there is only the one:
    /// "an agent is connected" must never look dimmer than "nothing is
    /// connected".
    @Test @MainActor
    func theRestingGreyIsDarkerThanTheThemeInk() {
        func luminance(_ ink: NotchPalette.MatrixInk) -> Double {
            func channel(_ value: Double) -> Double {
                value <= 0.03928
                    ? value / 12.92
                    : pow((value + 0.055) / 1.055, 2.4)
            }
            return 0.2126 * channel(ink.offRed)
                + 0.7152 * channel(ink.offGreen)
                + 0.0722 * channel(ink.offBlue)
        }

        let resting = luminance(NotchPalette.restingInk)
        #expect(resting <= luminance(NotchPalette.themeInk))
        // The theme ink can light. The resting mark cannot: with nothing
        // connected there is nothing that could be running.
        #expect(NotchPalette.themeInk.on != NotchPalette.themeInk.off)
        #expect(NotchPalette.restingInk.on == NotchPalette.restingInk.off)
    }

    /// The mark is drawn with row 0 at the top.
    ///
    /// **What this used to be, and why the claim outlived it.** The seam of the
    /// first-run legend's split matrix — Codex above, Claude Code below — was
    /// once the only asymmetric thing the matrix drew, so it was the only
    /// witness that the view's `isFlipped` was right. The four old patterns
    /// were all symmetric top to bottom (a checkerboard, a centre cell, and two
    /// uniform fields), and nothing would have caught the flip being wrong.
    ///
    /// The seam is gone with the two product inks it was cut from
    /// (`colour-v2.md` §11), and the legend now draws one mark in the theme
    /// ink — but three of the four patterns are asymmetric, so they are the
    /// witnesses instead: mirrored, the radar sweeps the wrong way, the
    /// advance's baseline row sits on top, and the lull crosses the wrong
    /// diagonal. This pins the property those three depend on, directly, so a
    /// flip that broke all three fails here first and says what it was.
    @Test @MainActor
    func theMarkIsDrawnWithRowZeroAtTheTop() {
        #expect(MatrixIndicatorView(frame: .zero).isFlipped)
    }

    /// The first-run specimens are the product, and they watch nothing.
    ///
    /// `OnboardingAnatomy` draws the bar and the panel by handing
    /// ``NotchOverlayView`` a store of its own, so what is asserted here is
    /// everything that store has to be for that drawing to be honest and safe:
    /// **inert** -- no services, so no socket is bound, no file of the user's
    /// is read and nothing on the notch answers to it; **two products**, since
    /// a specimen with one mark would teach the wrong bar; and **shut and open
    /// respectively**, which is the difference between the two figures.
    ///
    /// The width is the load-bearing one. The window pins the bar's trailing
    /// parts by measuring inwards from its right edge, which is only where the
    /// badges and the reading are if the specimen is the no-notch pill the
    /// product composes for this reading. `PanelMetrics.size` is asked the same
    /// question directly: if the pill's geometry ever stops matching, the pins
    /// are pointing at nothing and this fails rather than the drawing going
    /// quietly wrong.
    @Test @MainActor
    func theFirstRunSpecimensAreTheProductAndWatchNothing() throws {
        let shut = NotchSpecimen.shut
        let hovered = NotchSpecimen.hovered

        #expect(!shut.isWatching)
        #expect(!hovered.isWatching)
        #expect(!shut.isExpanded)
        #expect(hovered.isExpanded)

        // Both products, in the bar's own order, each with its own rows.
        #expect(shut.presenceMarks.count == 2)
        #expect(shut.connectedAgents == [.codex, .claudeCode])
        #expect(shut.geometry == .noNotch)
        #expect(shut.compactHeight == PanelMetrics.referenceCompactHeight)

        // A turn stopped on an approval is what the whole drawing is of, and
        // the approval is one the row could take here: `canBeAnswered` is what
        // decides between `Approve` and `Read`, so a specimen without it would
        // draw the reading form of the mark and teach the wrong half.
        #expect(shut.status == .approvalNeeded)
        let waiting = try #require(hovered.sessions.first)
        #expect(waiting.status == .approvalNeeded)
        #expect(waiting.request?.canBeAnswered == true)
        #expect(
            PanelMetrics.waitingMarkWord(
                for: waiting.status,
                canBeAnswered: waiting.request?.canBeAnswered == true
            ) == PanelMetrics.waitingMarkApproveWord
        )
        #expect(shut.aggregateSessionCount == shut.sessions.count)
        #expect(shut.compactTimerText != nil)

        // The pill the pins are measured against.
        let composed = PanelMetrics.size(
            geometry: .noNotch,
            isExpanded: false,
            statusReadoutText: shut.statusDisplayName,
            trailing: shut.compactTrailingReading,
            centerOcclusionWidth: 0,
            compactHeight: shut.compactHeight,
            status: shut.status,
            matrixCount: shut.presenceMarks.count,
            sessionCount: shut.aggregateSessionCount,
            drawsMark: shut.drawsCompactMarks
        )
        #expect(shut.currentPanelSize == composed)
        // The specimen has rows on both products, so the counts column is
        // drawn: the anatomy pins that step past the mark are measuring a
        // width that is actually there.
        #expect(shut.aggregateSessionCount > 0)
        #expect(shut.aggregateSubagentCount > 0)

        // The reading is drawn at exactly the width the pill is billed for, so
        // the trailing pins can be measured inwards from the edge: the slot is
        // the ink and its ground, plus the buried-finish dot and its `8` where
        // the specimen has one, and nothing held open behind either.
        let drawn = PanelMetrics.drawnCompactReadingWidth(shut.compactTimerText ?? "")
        let dot = shut.buriesAFinishedTurn ? PanelMetrics.buriedFinishSlotWidth : 0
        #expect(shut.compactDrawnTrailingReadingWidth == drawn + dot)

        // A finished turn sitting under a mark that is drawing something else,
        // which is what sets the buried-finish dot breathing. A drawn fact
        // with no text beside it, so the key is the only place it is explained
        // and this is the only place it is pinned.
        #expect(shut.buriesAFinishedTurn)

        // **The list is grouped, so a row's place is decided by its block.**
        // Three Codex rows and one of Claude Code's is the leading heading,
        // the cap, and the second heading -- the grouped viewport exactly --
        // which is what puts both headings on the figure with three rows
        // between them, and the fourth row under the rail rather than under
        // the fold with nothing to say it is there.
        #expect(hovered.groupsSessionsByProduct)
        let blocks = hovered.sessionGroups
        #expect(blocks.map(\.agent) == [.codex, .claudeCode])
        #expect(blocks.map(\.sessions.count) == [3, 1])
        #expect(
            hovered.sessionViewportHeight
                == PanelMetrics.groupHeadingsHeight(count: 2)
                    + PanelMetrics.sessionRowHeight * 3
        )
        // The first block is stopped on the approval the whole drawing is of,
        // so its count is drawn lit -- the one thing a heading says beyond its
        // own name.
        #expect(blocks.first?.wantsAttention == true)

        // A turn finished with subagents still working: one row drawing a
        // badge where a reading would be, which is the pin that names it, and
        // also why the aggregate mark is on radar rather than lull. **Second
        // inside the first block**, so it is one of the three rows the panel
        // lists; the pin is placed on that row's centre and would otherwise
        // name empty black.
        let badged = try #require(hovered.sessions.dropFirst().first)
        #expect(badged.agent == .codex)
        #expect(badged.showsSubagentBadge)
        #expect(MonitorAggregation.effectiveStatus(of: badged) == .running)

        // And no row draws a chip of its own while the list is grouped: the
        // heading above it has said which product it is, and the pin naming
        // the caption line says `Project` rather than `Product and project`.
        #expect(hovered.showsProductAttribution)

        // The panel's own footer, which the second page has the room to draw:
        // today's spend, and the control that opens one group per product --
        // Codex publishes one window, Claude Code three, each named the way its
        // own product names it. Pins 7 and 8 name a line and a control that
        // only exist if this fixture carries real quota.
        #expect(hovered.footerRules.count == 2)
        let claudeQuota = hovered.footerRules.first { $0.agent == .claudeCode }
        #expect(
            claudeQuota?.windows.map(\.label)
                == ["Current session", "All models", "Fable"]
        )
        #expect(
            hovered.footerRules.first { $0.agent == .codex }?
                .windows.map(\.label) == ["Weekly limit"]
        )
        #expect(hovered.showsQuotaFoldControl)
        #expect(hovered.footerToday.text == "519M today")
        // And the table starts shut, which is what the pins are placed against.
        #expect(!hovered.isQuotaExpanded)

        // One row has left the list, so the panel draws the Recent seam the
        // eighth pin names. It gets there by departing rather than by being
        // placed: the staged list holds it, the next one does not, and the
        // merge records the arrow.
        #expect(hovered.recentDepartures.count == 1)
        #expect(hovered.recentDepartures.first?.reason == .read)
        #expect(!hovered.isRecentExpanded)
        #expect(!hovered.sessions.contains { $0.id == hovered.recentDepartures[0].session.id })
    }

    /// No two pins on a figure stand on the same point, and every leader stops
    /// on the specimen's edge.
    ///
    /// **The one fault a specimen that cannot drift is still open to.** The
    /// drawings are the product's own views, so a part that changes shape
    /// changes here too; what does not follow the product is the *key*, and a
    /// pin whose part has gone does not disappear -- it stays at whatever
    /// coordinate its formula still evaluates to. Two of the collapsed bar's
    /// six ended up on one point that way, one naming a dot column the surface
    /// had stopped drawing and one naming a badge that had moved, and the
    /// figure drew a numeral on top of a numeral with nothing to say so.
    ///
    /// The second half is the rule `figma-design.md` §7.1 states and the
    /// drawing had quietly stopped keeping: **a leader stops at the specimen's
    /// edge.** Pin positions are in the panel's units and scale with it; a
    /// pin's badge is `13` pt whatever the scale; a leader written in the first
    /// and drawn against the second crossed about `5` pt onto the black either
    /// side. Every figure is checked rather than the two that had the fault,
    /// because the arithmetic is the same in all five.
    @Test @MainActor
    func theFirstRunPinsStandApartAndTheirLeadersStopAtTheEdge() {
        let figures: [(what: String, pins: [AnatomyPin], size: CGSize)] = [
            ("the collapsed bar", CollapsedBarAnatomy().pins, CollapsedBarAnatomy().specimenSize),
            ("the panel", ExpandedPanelAnatomy().pins, ExpandedPanelAnatomy().specimenSize),
            ("a permission", OpenCommandAnatomy().pins, OpenCommandAnatomy().specimenSize),
            ("a question", OpenQuestionAnatomy().pins, OpenQuestionAnatomy().specimenSize),
            ("multiple choice", OpenQuestionAnatomy(lesson: .multipleChoice).pins, OpenQuestionAnatomy(lesson: .multipleChoice).specimenSize),
            ("typed answer", OpenQuestionAnatomy(lesson: .typedAnswer).pins, OpenQuestionAnatomy(lesson: .typedAnswer).specimenSize),
            ("the queue", RecentQueueAnatomy().pins, RecentQueueAnatomy().specimenSize)
        ]

        for figure in figures {
            #expect(
                figure.pins.map(\.id) == Array(1...figure.pins.count),
                "the key on \(figure.what) is numbered from one, in order"
            )

            let points = figure.pins.map { CGPoint(x: $0.x, y: $0.y) }
            for (index, point) in points.enumerated() {
                for other in points[(index + 1)...] {
                    #expect(
                        abs(point.x - other.x) > AnatomyMetrics.pinSize
                            || abs(point.y - other.y) > AnatomyMetrics.pinSize,
                        "two pins on \(figure.what) stand on one point"
                    )
                }
            }

            let half = AnatomyMetrics.pinSize / 2
            for pin in figure.pins {
                let landing: CGFloat
                let edge: CGFloat
                switch pin.leader {
                case let .left(length):
                    landing = pin.x - half - length
                    edge = figure.size.width
                case let .right(length):
                    landing = pin.x + half + length
                    edge = 0
                case let .up(length):
                    landing = pin.y - half - length
                    edge = figure.size.height
                case let .down(length):
                    landing = pin.y + half + length
                    edge = 0
                case let .forkRight(stem, _, foot):
                    landing = pin.x + half + stem + foot
                    edge = 0
                }
                #expect(
                    abs(landing - edge) < 0.01,
                    "pin \(pin.id) on \(figure.what) stops short of its edge, or crosses it"
                )
            }
        }
    }

    /// **No two callouts in a column of the README card stand on one line.**
    ///
    /// The card's own version of the assertion above, and it was written after
    /// the fault it describes: a row's air came down by `8` and a block's
    /// heading gave up its `16`, which moved `One block per product` and
    /// `Project` to within `6` points of each other and drew one over the
    /// other. Nothing failed. The figure is opt-in — it renders only when
    /// `~/.notchline-anatomy-out` is set — so the only reader is whoever
    /// happens to look at the PNG, and the panel's geometry is exactly the
    /// thing that moves under it.
    ///
    /// A label is centred on `target.y + drop`, so a column is legible when
    /// consecutive labels are at least one line apart. `drop` is what buys
    /// that where two parts genuinely share a line, and this is the check that
    /// says when one is owed.
    ///
    /// **The leading and trailing columns only.** `.above` and `.below` crowd
    /// on the other axis — three of them share the collapsed bar's bottom edge
    /// by design — and `drop` steps those sideways rather than down, over
    /// labels whose widths this cannot know without laying them out.
    @Test @MainActor
    func theReadmeCalloutsStandApartInTheirColumns() {
        let now = Date()
        let compact = AnatomyFigureRenderer.store(
            isExpanded: false,
            buriedFinish: true,
            at: now,
            on: AnatomyFigureRenderer.compactDisplay
        )
        let expanded = AnatomyFigureRenderer.store(
            isExpanded: true,
            buriedFinish: true,
            at: now,
            on: AnatomyFigureRenderer.panelDisplay
        )
        expanded.stageSpecimenQueue(AnatomyFigureRenderer.departures(at: now))
        expanded.isRecentExpanded = true
        expanded.isQuotaExpanded = true

        // One line of the card's own label face, which is what two labels have
        // to clear each other by.
        let line = NSFont.systemFont(ofSize: 13).boundingRectForFont.height
        let card = ReadmeAnatomyCard(compact: compact, expanded: expanded)

        for (what, callouts) in [
            ("the panel", card.expandedCallouts),
            ("the collapsed bar", card.compactCallouts)
        ] {
            for side in [AnatomyCallout.Side.leading, .trailing] {
                let lines = callouts
                    .filter { $0.side == side }
                    .map { $0.target.y + $0.drop }
                    .sorted()
                for (above, below) in zip(lines, lines.dropFirst()) {
                    #expect(
                        below - above >= line,
                        """
                        two \(side) labels on \(what) stand \(below - above)                         apart, inside one \(line) pt line
                        """
                    )
                }
            }
        }
    }

    /// Page changes must not offer a different size to the content-sized
    /// Window scene. Exercise the real SwiftUI trees, including the tall page.
    @Test @MainActor
    func onboardingPagesKeepOneWindowSize() {
        let store = MonitorStore(preferences: nil)
        for page in OnboardingView.Page.allCases {
            let host = NSHostingView(rootView: OnboardingView(page: page).environmentObject(store))
            let expected = NSSize(width: 580, height: 840)
            host.setFrameSize(expected)
            host.layoutSubtreeIfNeeded()
            #expect(host.fittingSize == expected)
        }
    }

    /// The page-three pins belong in the middle of the card's padding,
    /// clear of both the card stroke and the plate, at their actual badge size.
    @Test @MainActor
    func openedSpecimenPinsSitInTheMiddleOfTheCardMargins() {
        let figures: [(pins: [AnatomyPin], size: CGSize)] = [
            (OpenCommandAnatomy().pins, OpenCommandAnatomy().specimenSize),
            (OpenQuestionAnatomy().pins, OpenQuestionAnatomy().specimenSize),
            (RecentQueueAnatomy().pins, RecentQueueAnatomy().specimenSize)
        ]
        for figure in figures {
            let inset = (OnboardingLayout.cardWidth - figure.size.width) / 2
            for pin in figure.pins where pin.x < 0 || pin.x > figure.size.width {
                let centre = inset + pin.x
                let distance = pin.x < 0 ? centre : OnboardingLayout.cardWidth - centre
                #expect(abs(distance - inset / 2) < 0.01)
                #expect(distance - AnatomyMetrics.pinSize / 2 >= 14)
            }
        }
    }

    @Test @MainActor
    func tutorialDraftStagingCannotChangeAWatchingStoresAnswer() async {
        let (store, service, row) = answeringStore(request: questionSet(count: 1), status: .inputNeeded)
        store.toggleOpenRow(row)
        #expect(await eventually { store.isAffirmativeArmed })
        store.answerDraftChanged(to: "My actual answer")
        store.stageSpecimenAnswer(selectedOptions: [0], draft: "Tutorial words")
        #expect(store.answerDraft == "My actual answer")
