    /// A secondary click on a finished row takes that row off the list, and
    /// leaves the session it belongs to alone.
    ///
    /// The dismissed set is keyed by Turn, so the same thread's next Turn is a
    /// new row and lists as usual. This is the only route rows have out of the
    /// list at the user's asking; the `Clear the session list` button that
    /// dismissed all of them at once is gone.
    @Test @MainActor
    func dismissingAFinishedRowHidesThatTurnButAllowsTheNext() {
        let finished = MonitoredSession(
            threadID: "thread",
            turnID: "turn-1",
            projectName: "Chats",
            title: "Finished turn",
            preview: nil,
            status: .completed,
            startedAt: Date()
        )
        let store = MonitorStore(
            initialSnapshot: AgentSnapshot(
                availability: .ready,
                sessions: [finished],
                quota: .unavailable,
                diagnostic: nil
            )
        )

        #expect(store.dismiss(finished))
        #expect(store.sessions.isEmpty)

        // Still reported upstream, and still not shown.
        store.applyForTesting(
            AgentSnapshot(
                availability: .ready,
                sessions: [finished],
                quota: .unavailable,
                diagnostic: nil
            )
        )
        #expect(store.sessions.isEmpty)

        let nextTurn = MonitoredSession(
            threadID: "thread",
            turnID: "turn-2",
            projectName: "Chats",
            title: "Next turn",
            preview: nil,
            status: .running,
            startedAt: Date()
        )
        store.applyForTesting(
            AgentSnapshot(
                availability: .ready,
                sessions: [finished, nextTurn],
                quota: .unavailable,
                diagnostic: nil
            )
        )
        #expect(store.sessions.map(\.id) == [nextTurn.id])
    }

    /// Quitting Codex Desktop does not undo a dismissal.
    ///
    /// The moment Desktop goes, the provider publishes an empty session list --
    /// and the Hook reducer behind it still holds that finished Turn, so the
    /// first hook event after the relaunch republishes exactly the row the user
    /// waved away. Reading "absent from this snapshot" as "gone for good" put
    /// that row back on the notch (CR-Fable-004); the product being closed is
    /// not evidence about any Turn.
    ///
    /// The other product being perfectly healthy throughout is the second half
    /// of it: dismissals are forgotten on their own product's word, never on
    /// its neighbour's.
    @Test @MainActor
    func aDismissalSurvivesItsProductQuitting() {
        let finished = MonitoredSession(
            threadID: "thread",
            turnID: "turn-1",
            projectName: "Chats",
            title: "Finished turn",
            preview: nil,
            status: .completed,
            startedAt: Date()
        )
        let store = MonitorStore(
            initialSnapshot: AgentSnapshot(
                availability: .ready,
                sessions: [finished],
                quota: .unavailable,
                diagnostic: nil
            )
        )

        #expect(store.dismiss(finished))
        #expect(store.sessions.isEmpty)

        // Desktop quits: presence is kernel truth, so it says closed at once,
        // and the row list empties with it.
        store.applyForTesting(
            AgentSnapshot(
                availability: .ready,
                sessions: [],
                quota: .unavailable,
                diagnostic: nil,
                presence: .closed
            )
        )
        // Claude Code is up and has nothing to show. It is not a witness to
        // what Codex has dismissed.
        store.applyForTesting(
            AgentSnapshot(
                agent: .claudeCode,
                availability: .ready,
                sessions: [],
                quota: .unavailable,
                diagnostic: nil
            )
        )

        // Relaunched, and the reducer republishes the same Turn.
        store.applyForTesting(
            AgentSnapshot(
                availability: .ready,
                sessions: [finished],
                quota: .unavailable,
                diagnostic: nil
            )
        )
        #expect(store.sessions.isEmpty)
    }

    /// A disconnect long enough to publish does not undo a dismissal either.
    ///
    /// Past the stability grace the product publishes `.disconnected` with
    /// nothing in it. Nothing about that says the Turn ended -- it says we
    /// stopped being able to ask -- and the row comes back with the connection.
    @Test @MainActor
    func aDismissalSurvivesASustainedDisconnect() {
        let baseDate = Date(timeIntervalSince1970: 2_000)
        let finished = MonitoredSession(
            threadID: "thread",
            turnID: "turn-1",
            projectName: "Chats",
            title: "Finished turn",
            preview: nil,
            status: .completed,
            startedAt: baseDate
        )
        let ready = AgentSnapshot(
            availability: .ready,
            sessions: [finished],
            quota: .unavailable,
            diagnostic: nil
        )
        let disconnected = AgentSnapshot(
            availability: .disconnected,
            sessions: [],
            quota: .unavailable,
            diagnostic: "transport unavailable"
        )
        let store = MonitorStore(initialSnapshot: ready)

        #expect(store.dismiss(finished))

        store.applyForTesting(disconnected, observedAt: baseDate)
        store.applyForTesting(
            disconnected,
            observedAt: baseDate.addingTimeInterval(3)
        )
        #expect(store.availability == .disconnected)

        store.applyForTesting(
            ready,
            observedAt: baseDate.addingTimeInterval(4)
        )
        #expect(store.sessions.isEmpty)
    }

    /// Claude Code withholding its rows does not undo a dismissal.
    ///
    /// With no window open that product publishes an empty list while staying
    /// perfectly ready -- its rows are withheld, not discarded
    /// (`tech-design.md` §15.1). A dismissal read off that list would be
    /// forgotten every time the user closed the terminal.
    @Test @MainActor
    func aDismissalSurvivesClaudeCodeWithholdingItsRows() {
        let finished = MonitoredSession(
            agent: .claudeCode,
            threadID: "session",
            turnID: "turn-1",
            projectName: "Chats",
            title: "Finished turn",
            preview: nil,
            status: .completed,
            startedAt: Date()
        )
        let listed = AgentSnapshot(
            agent: .claudeCode,
            availability: .ready,
            sessions: [finished],
            quota: .unavailable,
            diagnostic: nil
        )
        let store = MonitorStore(initialSnapshot: listed)

        #expect(store.dismiss(finished))

        store.applyForTesting(
            AgentSnapshot(
                agent: .claudeCode,
                availability: .ready,
                sessions: [],
                quota: .unavailable,
                diagnostic: nil,
                presence: .closed
            )
        )
        store.applyForTesting(listed)
        #expect(store.sessions.isEmpty)
    }

    /// A dismissal is forgotten once its own product, in view, stops listing
    /// the Turn.
    ///
    /// This is what keeps the set bounded, and it is the only evidence that
    /// does: the product is open, it is answering, and the Turn is not among
    /// what it named. Anything it says after that is a new statement about a
    /// row the user has not dismissed.
    @Test @MainActor
    func aDismissalIsForgottenOnceItsProductSaysTheTurnIsGone() {
        let finished = MonitoredSession(
            threadID: "thread",
            turnID: "turn-1",
            projectName: "Chats",
            title: "Finished turn",
            preview: nil,
            status: .completed,
            startedAt: Date()
        )
        let listed = AgentSnapshot(
            availability: .ready,
            sessions: [finished],
            quota: .unavailable,
            diagnostic: nil
        )
        let store = MonitorStore(initialSnapshot: listed)

        #expect(store.dismiss(finished))

        store.applyForTesting(
            AgentSnapshot(
                availability: .ready,
                sessions: [],
                quota: .unavailable,
                diagnostic: nil
            )
        )
        store.applyForTesting(listed)
        #expect(store.sessions.map(\.id) == [finished.id])
    }

    /// A row in any state can be dismissed, and it used to be finished ones
    /// only.
    ///
    /// The restriction read well -- a running Turn has not told the user
    /// anything yet, so a stray click threw away a notice they could not get
    /// back -- and it was protecting the wrong thing. A Turn stuck open is
    /// never Completed, so the one gesture that removes a row was missing in
    /// exactly the state a user needs it in, and quitting the app was the only
    /// way out. See ``MonitorStore/dismiss(_:)``.
    @Test @MainActor
    func aRowInAnyStateCanBeDismissed() {
        for status in [SessionStatus.running, .inputNeeded, .approvalNeeded] {
            let live = MonitoredSession(
                threadID: "thread-\(status)",
                turnID: "turn",
                projectName: "Chats",
                title: "Live turn",
                preview: nil,
                status: status,
                startedAt: Date()
            )
            let store = MonitorStore(
                initialSnapshot: AgentSnapshot(
                    availability: .ready,
                    sessions: [live],
                    quota: .unavailable,
                    diagnostic: nil
                )
            )

            #expect(store.dismiss(live))
            #expect(store.sessions.isEmpty)
            // And it is the Turn that was dismissed, not the thread: the same
            // thread's next Turn is a row again.
            let next = MonitoredSession(
                threadID: live.threadID,
                turnID: "turn-2",
                projectName: "Chats",
                title: "Live turn",
                preview: nil,
                status: status,
                startedAt: Date()
            )
            store.applyForTesting(
                AgentSnapshot(
                    availability: .ready,
                    sessions: [next],
                    quota: .unavailable,
                    diagnostic: nil
                )
            )
            #expect(store.sessions.map(\.id) == [next.id])
        }
    }

    /// A dismissed row stops counting the moment it stops showing.
    ///
    /// The summary status and the product marks are both derived from the rows
    /// on the list, so a dismissal that only edited the array would leave the
    /// notch reporting a finished Turn nobody can see and the product's mark
    /// lit for it.
    @Test @MainActor
    func dismissingARowStopsItCountingTowardsTheSummary() {
        let finished = MonitoredSession(
            agent: .claudeCode,
            threadID: "session",
            turnID: "turn",
            projectName: "Chats",
            title: "Finished turn",
            preview: nil,
            status: .completed,
            startedAt: Date()
        )
        let store = MonitorStore(
            initialSnapshot: AgentSnapshot(
                agent: .claudeCode,
                availability: .ready,
                sessions: [finished],
                quota: .unavailable,
                diagnostic: nil
            )
        )

        #expect(store.status == .completed)
        #expect(store.presenceMarks.map(\.status) == [.completed])

        #expect(store.dismiss(finished))

        #expect(store.status == .connected)
        #expect(store.presenceMarks.map(\.status) == [.connected])
    }

    /// Dismissing the same row twice changes nothing the second time.
    ///
    /// A secondary press is easy to repeat, and the row is gone from the panel
    /// by then anyway -- what this pins is that the second call reports it did
    /// nothing rather than reporting a fresh dismissal.
    @Test @MainActor
    func dismissingARowTwiceIsNotASecondDismissal() {
        let finished = MonitoredSession(
            threadID: "thread",
            turnID: "turn",
            projectName: "Chats",
            title: "Finished turn",
            preview: nil,
            status: .completed,
            startedAt: Date()
        )
        let store = MonitorStore(
            initialSnapshot: AgentSnapshot(
                availability: .ready,
                sessions: [finished],
                quota: .unavailable,
                diagnostic: nil
            )
        )

        #expect(store.dismiss(finished))
        #expect(!store.dismiss(finished))
        #expect(store.sessions.isEmpty)
    }

    /// The row's catcher takes the secondary press and nothing else.
    ///
    /// It covers the whole row, so every event it claims is one the button
    /// underneath never sees. Claiming a primary press would silently cost the
    /// list its navigation -- clicking a finished row would dismiss it instead
    /// of opening it -- and claiming a movement would do it for hover too.
    @Test @MainActor
    func theSecondaryClickCatcherClaimsOnlyTheSecondaryPress() {
        let claimed: [NSEvent.EventType] = [.rightMouseDown, .rightMouseUp]
        let passedThrough: [NSEvent.EventType] = [
            .leftMouseDown,
            .leftMouseUp,
            .leftMouseDragged,
            .mouseMoved,
            .mouseEntered,
            .mouseExited,
            .otherMouseDown,
            .scrollWheel,
            .keyDown
        ]

        for eventType in claimed {
            #expect(SecondaryClickView.claims(eventType))
        }
        for eventType in passedThrough {
            #expect(!SecondaryClickView.claims(eventType))
        }
        // AppKit also asks about geometry with no event in flight at all.
        #expect(!SecondaryClickView.claims(nil))
        #expect(SecondaryClickView().hitTest(.zero) == nil)
    }

    /// SwiftUI puts the catcher over the whole row, and the press it takes
    /// calls through.
    ///
    /// ``theSecondaryClickCatcherClaimsOnlyTheSecondaryPress()`` pins what the
    /// view answers when AppKit asks. This pins the other half: that there is a
    /// real view for AppKit to ask, covering the area the row occupies rather
    /// than collapsed to nothing by the overlay. Dispatching a synthetic mouse
    /// event to check the two halves together was tried and rejected -- it
    /// takes the test host down with it, which fails a dozen unrelated tests
    /// running beside it.
    @Test @MainActor
    func theSecondaryClickCatcherCoversTheRowAndCallsThrough() {
        final class Count { var value = 0 }
        let pressed = Count()
        let rowSize = CGSize(width: 120, height: PanelMetrics.sessionRowHeight)

        let hosting = NSHostingView(
            rootView: Color.clear
                .frame(width: rowSize.width, height: rowSize.height)
                .overlay { SecondaryClickCatcher { pressed.value += 1 } }
        )
        hosting.frame = NSRect(origin: .zero, size: rowSize)
        hosting.layoutSubtreeIfNeeded()

        func catchers(in view: NSView) -> [SecondaryClickView] {
            (view as? SecondaryClickView).map { [$0] } ?? view.subviews.flatMap(catchers(in:))
        }
        let catcher = catchers(in: hosting).first
        #expect(catcher != nil)
        #expect(catcher?.frame.size == rowSize)

        catcher?.rightMouseDown(
            with: NSEvent.mouseEvent(
                with: .rightMouseDown,
                location: .zero,
                modifierFlags: [],
                timestamp: 0,
                windowNumber: 0,
                context: nil,
                eventNumber: 0,
                clickCount: 1,
                pressure: 1
            )!
        )
        #expect(pressed.value == 1)
    }

    /// The body's catcher takes the wheel and nothing else, and only where
    /// there is somewhere to go.
    ///
    /// The same pair as ``theSecondaryClickCatcherClaimsOnlyTheSecondaryPress()``
    /// and for the same reason: this view is drawn **over** the request body, so
    /// every event it claims is one the lines and the options underneath never
    /// see. Widen it and an option stops taking its click; narrow it and the
    /// body stops scrolling. ``claimsTheWheel`` is the second half — a request
    /// that fits claims nothing, so the wheel reaches the list it is drawn in
    /// rather than being swallowed over the one row that has nothing to move.
    @Test @MainActor
    func theWheelCatcherClaimsOnlyTheWheelAndOnlyWithTravel() {
        let view = WheelCatcherView()
        let passedThrough: [NSEvent.EventType] = [
            .leftMouseDown,
            .leftMouseUp,
            .leftMouseDragged,
            .rightMouseDown,
            .mouseMoved,
            .mouseEntered,
            .mouseExited,
            .cursorUpdate,
            .keyDown
        ]

        view.claimsTheWheel = true
        #expect(view.claims(.scrollWheel))
        for eventType in passedThrough {
            #expect(!view.claims(eventType))
        }
        // AppKit also asks about geometry with no event in flight at all.
        #expect(!view.claims(nil))

        // A body that fits gives the wheel back too.
        view.claimsTheWheel = false
        #expect(!view.claims(.scrollWheel))
        #expect(view.hitTest(.zero) == nil)
    }

    /// SwiftUI puts the catcher over the body, at the body's own size.
    ///
    /// **This is the half that was wrong**, and the half no assertion about
    /// ``WheelCatcherView/claims(_:)`` could have caught: the catcher was
    /// declared as a `.background`, behind lines that are themselves
    /// hit-testable, so AppKit's hit test never reached it and not one wheel
    /// event over an open request was ever delivered to it
    /// (`system-architecture.md` §6). Ordering inside SwiftUI's own hit test is
    /// still not something this suite can assert; what it can assert is that
    /// there is a real view of the right size for AppKit to ask about, and that
    /// it declines everything but the wheel.
    @Test @MainActor
    func theWheelCatcherCoversTheBodyItScrolls() {
        let bodySize = CGSize(width: 200, height: PanelMetrics.requestBodyMaximumHeight)

        let hosting = NSHostingView(
            rootView: Color.clear
                .frame(width: bodySize.width, height: bodySize.height)
                .overlay { WheelCatcher(claimsTheWheel: true) { _ in } }
        )
        hosting.frame = NSRect(origin: .zero, size: bodySize)
        hosting.layoutSubtreeIfNeeded()

        func catchers(in view: NSView) -> [WheelCatcherView] {
            (view as? WheelCatcherView).map { [$0] } ?? view.subviews.flatMap(catchers(in:))
        }
        let catcher = catchers(in: hosting).first
        #expect(catcher != nil)
        #expect(catcher?.frame.size == bodySize)
        #expect(catcher?.claimsTheWheel == true)
        // No event is in flight in a test, so the whole hierarchy answers as it
        // does for geometry: the catcher stands aside.
        #expect(catcher?.hitTest(.zero) == nil)
    }

    /// The window server still lets this process set a cursor while another
    /// application is the active one.
    ///
    /// **This is an assertion about macOS, and it is here on purpose.** Every
    /// control on a closed row promises a click with a pointing hand, and
    /// `NSCursor.set()` is refused outside the active application -- see
    /// ``BackgroundCursor`` for the measurement. The permission that lifts that
    /// is asked for through a property no public header declares, so the day a
    /// release stops offering it, nothing breaks, throws or logs: the hand
    /// simply stops appearing, on the one surface nobody runs a test against.
    /// This failing is that signal.
    ///
    /// It asserts the agreement rather than the cursor, because a test host has
    /// no pointer to read one from -- the hand itself is verified by driving the
    /// Release app and screenshotting the pointer.
    @Test @MainActor
    func theWindowServerLetsAnInactiveApplicationSetTheCursor() {
        #expect(BackgroundCursor.isAllowed)
    }

    /// Both mechanisms the hand needs, and neither is the other's fallback.
    ///
    /// `.mouseEnteredAndExited` is what carries it on a closed row, where no
    /// cursor pass runs at all; `.cursorUpdate` is what wins it on an open one,
    /// where the panel is key and the request body's scroll view owns the
    /// rectangle under the pointer and would otherwise hand back an arrow.
    /// Drop either and one of the two surfaces silently loses its pointer.
    @Test @MainActor
    func thePointingHandTracksForBothTheCrossingAndTheCursorPass() {
        let view = PointingHandView()
        view.frame = NSRect(x: 0, y: 0, width: 76, height: 24)
        view.updateTrackingAreas()

        // One area, replaced rather than stacked on every layout pass.
        #expect(view.trackingAreas.count == 1)
        let options = view.trackingAreas.first?.options
        #expect(options?.contains(.mouseEnteredAndExited) == true)
        #expect(options?.contains(.cursorUpdate) == true)
        // Delivered to a panel that is neither key nor in the active app, and
        // kept in step with the row as the list scrolls under it.
        #expect(options?.contains(.activeAlways) == true)
        #expect(options?.contains(.inVisibleRect) == true)
        // It says what the pointer looks like and never takes the click; the
        // chip underneath is the target.
        #expect(view.hitTest(.zero) == nil)
    }

    /// Recheck must report what is true now, not what was true before.
    ///
    /// It used to call a refresh that returned immediately whenever an
    /// automatic one happened to be in flight, so the button finished at once
    /// and handed back the status it already had (CR-008).
    @Test @MainActor
    func recheckWaitsForASnapshotThatAccountsForItOwnRequest() async throws {
        let service = GatedMonitoringStub()
        await service.setHoldsSnapshots(true)
        await service.setStatus(.reviewRequired)

        let store = MonitorStore(
            services: [service],
            initialSnapshot: AgentSnapshot(
                availability: .connecting,
                sessions: [],
                quota: .unavailable,
                diagnostic: nil,
                setupStatus: .notInstalled
            )
        )

        // Wait until the automatic refresh is genuinely in flight and stuck.
        for _ in 0 ..< 200 where await service.snapshotCount() < 1 {
            try await Task.sleep(nanoseconds: 5_000_000)
        }
        #expect(await service.snapshotCount() == 1)

        // The world changes while that refresh is parked.
        await service.setStatus(.active)

        // The user presses Recheck now.
        let recheck = Task { await store.recheckIntegrationAndWait() }
        try await Task.sleep(nanoseconds: 50_000_000)

        await service.setHoldsSnapshots(false)
        await service.releaseHeldSnapshots()

        let reported = await recheck.value
        #expect(
            reported == .active,
            "Recheck reported \(reported); it returned before a fresh read"
        )
        #expect(await service.snapshotCount() >= 2)
        store.stopMonitoring()
    }

    /// A watcher signal arriving mid-refresh must still produce a refresh.
    @Test @MainActor
    func aChangeSignalDuringARefreshIsServedRatherThanDropped() async throws {
        let service = GatedMonitoringStub()
        await service.setHoldsSnapshots(true)

        let store = MonitorStore(
            services: [service],
            initialSnapshot: AgentSnapshot(
                availability: .connecting,
                sessions: [],
                quota: .unavailable,
                diagnostic: nil,
                setupStatus: .notInstalled
            )
        )
        for _ in 0 ..< 200 where await service.snapshotCount() < 1 {
            try await Task.sleep(nanoseconds: 5_000_000)
        }

        // Three signals land while the first read is stuck. They collapse into
        // one follow-up -- coalesced, but not lost.
        store.refreshNow()
        store.refreshNow()
        store.refreshNow()

        await service.setHoldsSnapshots(false)
        await service.releaseHeldSnapshots()

        for _ in 0 ..< 200 where await service.snapshotCount() < 2 {
            try await Task.sleep(nanoseconds: 5_000_000)
        }
        #expect(
            await service.snapshotCount() >= 2,
            "a signal that arrived during a refresh was dropped"
        )
        store.stopMonitoring()
    }

    /// Flipping the switch faster than the work completes must still end where
    /// the user left it, and must not run two changes at once.
    @Test @MainActor
    func rapidIntegrationTogglesConvergeOnTheLastRequestedState() async throws {
        let service = GatedMonitoringStub()
        await service.setStatus(.notInstalled)
        let store = MonitorStore(
            services: [service],
            initialSnapshot: AgentSnapshot(
                availability: .setupRequired,
                sessions: [],
                quota: .unavailable,
                diagnostic: nil,
                setupStatus: .notInstalled
            )
        )

        store.setIntegrationEnabled(true)
        store.setIntegrationEnabled(false)
        let settled = await store.setIntegrationEnabledAndWait(true)

        #expect(settled)
        #expect(store.integrationSwitchIsOn, "the last flip must decide")
        #expect(store.hookSetupStatus.isIntegrationEnabled)
        #expect(await service.installCount() >= 1)
        #expect(
            await service.observedOverlappingIntegrationChange == false,
            "install and remove overlapped"
        )
        store.stopMonitoring()
    }

    /// And the same in the other direction, ending off.
    @Test @MainActor
    func rapidIntegrationTogglesConvergeWhenTheLastRequestIsOff() async throws {
        let service = GatedMonitoringStub()
        await service.setStatus(.notInstalled)
        let store = MonitorStore(
            services: [service],
            initialSnapshot: AgentSnapshot(
                availability: .setupRequired,
                sessions: [],
                quota: .unavailable,
                diagnostic: nil,
                setupStatus: .notInstalled
            )
        )

        store.setIntegrationEnabled(true)
        let settled = await store.setIntegrationEnabledAndWait(false)

        #expect(settled)
        #expect(!store.integrationSwitchIsOn)
        #expect(!store.hookSetupStatus.isIntegrationEnabled)
        #expect(
            await service.observedOverlappingIntegrationChange == false,
            "install and remove overlapped"
        )
        store.stopMonitoring()
    }

    @Test @MainActor
    func integrationMasterSwitchInstallsAndRemovesTheManagedSet() async {
        let service = IntegrationMonitoringStub()
        let store = MonitorStore(
            services: [service],
            initialSnapshot: AgentSnapshot(
                availability: .setupRequired,
                sessions: [],
                quota: .unavailable,
                diagnostic: nil
            )
        )

        let installed = await store.installIntegrationHooksAndWait()

        #expect(installed)
        #expect(store.integrationSwitchIsOn)
        #expect(store.hookSetupStatus == .reviewRequired)
        #expect(await service.installCount() == 1)

        let removed = await store.removeIntegrationAndWait()

        #expect(removed)
