    /// Each product's switch is its own, and turning one off leaves the other
    /// product exactly where it was.
    ///
    /// The switch state used to be a single pair of booleans belonging to
    /// Codex, because Codex had the only switch (ADR 0010). ADR 0016 gave
    /// Claude Code one too, and the failure that shape would have produced is
    /// the one worth pinning: switching Claude Code off would have cleared the
    /// merged session list, taking Codex's live rows off the notch with it.
    @Test @MainActor
    func eachProductsIntegrationSwitchMovesOnlyItsOwnProduct() async {
        let codex = IntegrationMonitoringStub(
            agent: .codex,
            rows: [makeSession(agent: .codex, threadID: "codex-1", status: .running)]
        )
        let claude = IntegrationMonitoringStub(
            agent: .claudeCode,
            rows: [makeSession(agent: .claudeCode, threadID: "cc-1", status: .running)]
        )
        let store = MonitorStore(services: [codex, claude])

        #expect(await store.setIntegrationEnabledAndWait(true, for: .codex))
        #expect(await store.setIntegrationEnabledAndWait(true, for: .claudeCode))
        #expect(store.integrationSwitchIsOn(for: .codex))
        #expect(store.integrationSwitchIsOn(for: .claudeCode))
        await store.refreshAndWaitForTesting()
        #expect(store.sessions.count == 2)

        #expect(await store.setIntegrationEnabledAndWait(false, for: .claudeCode))

        #expect(!store.integrationSwitchIsOn(for: .claudeCode))
        #expect(store.setupStatus(for: .claudeCode) == .notInstalled)
        // Untouched: its switch, its registration, and its row.
        #expect(store.integrationSwitchIsOn(for: .codex))
        #expect(store.setupStatus(for: .codex) == .reviewRequired)
        #expect(store.sessions.map(\.threadID) == ["codex-1"])
        #expect(await claude.removeCount() == 1)
        #expect(await codex.removeCount() == 0)

        store.stopMonitoring()
    }

    @Test
    func statusDomainsSeparateSystemAndSessionStates() {
        // The session states are the contract; the system states are not
        // counted here, because a raw count only says a number changed and
        // never which half of the domain it changed in.
        #expect(SessionStatus.allCases == [
            .running,
            .inputNeeded,
            .approvalNeeded,
            .completed
        ])
        // No system state may leak into the session vocabulary, and vice versa.
        let sessionStatuses = Set(SessionStatus.allCases.map(\.monitorStatus))
        #expect(
            sessionStatuses == [.running, .inputNeeded, .approvalNeeded, .completed]
        )
        #expect(
            Set(MonitorStatus.allCases).subtracting(sessionStatuses)
                == [
                    .connected,
                    .setupRequired,
                    .connecting,
                    .updateAgent,
                    .unsupportedVersion,
                    .disconnected
                ]
        )

        // No state names a product, system or shared. A system state is still
        // about one product's health, but saying which one is Settings' job.
        #expect(MonitorStatus.setupRequired.displayName == "Set up integration")
        #expect(MonitorStatus.inputNeeded.displayName == "Input needed")
        #expect(MonitorStatus.approvalNeeded.displayName == "Approval needed")
        #expect(MonitorStatus.connecting.displayName == "Connecting")
        #expect(MonitorStatus.unsupportedVersion.displayName == "Version unsupported")
        #expect(MonitorStatus.disconnected.displayName == "Disconnected")
    }

    @Test
    func sessionStatusMachineAllowsOnlyTheDesignedTransitions() {
        #expect(SessionStatus.running.transitioned(on: .inputNeeded) == .inputNeeded)
        #expect(SessionStatus.inputNeeded.transitioned(on: .inputNeeded) == .inputNeeded)
        #expect(SessionStatus.inputNeeded.transitioned(on: .running) == .running)
        #expect(SessionStatus.running.transitioned(on: .approvalNeeded) == .approvalNeeded)
        #expect(SessionStatus.approvalNeeded.transitioned(on: .approvalNeeded) == .approvalNeeded)
        #expect(SessionStatus.approvalNeeded.transitioned(on: .running) == .running)

        // The two waits are not symmetric, and the asymmetry is the design.
        //
        // Approval gives way to input, because a denied approval is the one
        // wait no product ever closes: the question that follows it is the
        // only evidence the human answered, and the row has to name the answer
        // now owed. Input does not give way to approval -- an input wait is
        // always closed by its own `PostToolUse`, so it is never stale, and
        // Input outranks Approval when both are somehow outstanding (PRD §6.2).
        #expect(SessionStatus.approvalNeeded.transitioned(on: .inputNeeded) == .inputNeeded)
        #expect(SessionStatus.inputNeeded.transitioned(on: .approvalNeeded) == .inputNeeded)

        for status in SessionStatus.allCases {
            #expect(status.transitioned(on: .completed) == .completed)
        }
        #expect(SessionStatus.completed.transitioned(on: .running) == .completed)
        #expect(SessionStatus.completed.transitioned(on: .inputNeeded) == .completed)
        #expect(SessionStatus.completed.transitioned(on: .approvalNeeded) == .completed)
    }

