    @Test @MainActor
    func inputNeededWinsAggregatePriority() {
        let now = Date()
        let running = MonitoredSession(
            threadID: "running",
            turnID: "turn-running",
            projectName: "Chats",
            title: "Running",
            preview: nil,
            status: .running,
            startedAt: now
        )
        let input = MonitoredSession(
            threadID: "input",
            turnID: "turn-input",
            projectName: "Project",
            title: "Input",
            preview: nil,
            status: .inputNeeded,
            startedAt: now
        )

        #expect(
            AgentSnapshotMerge.merge([
                makeAgentSnapshot(.codex, sessions: [running, input])
            ]).status == .inputNeeded
        )

        // Priority is a property of the merged list, not of either product's.
        // A Codex turn that is merely running must not outrank a Claude Code
        // turn that is waiting on the user just because Codex leads the order.
        let claudeInput = MonitoredSession(
            agent: .claudeCode,
            threadID: "cc",
            turnID: "turn",
            projectName: "notchline",
            title: "Input",
            preview: nil,
            status: .inputNeeded,
            startedAt: input.startedAt
        )
        #expect(
            AgentSnapshotMerge.merge([
                makeAgentSnapshot(.codex, sessions: [running]),
                makeAgentSnapshot(.claudeCode, sessions: [claudeInput])
            ]).status == .inputNeeded
        )
    }

    /// Approval outranks input across rows, and input outranks approval within
    /// one. Both rules exist, and they are not the same rule.
    ///
    /// **Across rows** the question is which of two waits is worth showing when
    /// only one can be: an input wait is answered whenever the user gets to it,
    /// an approval wait is a decision the agent cannot proceed past. Since the
    /// mark started drawing the two with different patterns, this order also
    /// decides which pattern a bar holding both runs, so the summary sentence
    /// and the mark beside it cannot disagree.
    ///
    /// **Within one row** the question is which of two readings is still true.
    /// A refused approval is never closed by either product, so a question that
    /// arrived after one is the more current fact about that thread and input
    /// keeps winning there. Flipping the table without noticing the difference
    /// would put a mark back on a dialog the user has already answered.
    @Test @MainActor
    func approvalOutranksInputAcrossRowsButNotWithinOne() {
        let now = Date()
        func session(
            _ agent: AgentKind,
            _ id: String,
            _ status: SessionStatus,
            awaitingApproval: Int = 0
        ) -> MonitoredSession {
            MonitoredSession(
                agent: agent,
                threadID: id,
                turnID: "turn-\(id)",
                projectName: "notchline",
                title: id,
                preview: nil,
                status: status,
                startedAt: now,
                subagentsAwaitingApprovalCount: awaitingApproval
            )
        }

        // Two rows, one of each, on one product and then across two.
        let input = session(.codex, "input", .inputNeeded)
        let approval = session(.codex, "approval", .approvalNeeded)
        #expect(
            AgentSnapshotMerge.merge([
                makeAgentSnapshot(.codex, sessions: [input, approval])
            ]).status == .approvalNeeded
        )
        let claudeApproval = session(.claudeCode, "cc", .approvalNeeded)
        #expect(
            AgentSnapshotMerge.merge([
                makeAgentSnapshot(.codex, sessions: [input]),
                makeAgentSnapshot(.claudeCode, sessions: [claudeApproval])
            ]).status == .approvalNeeded
        )

        // And the list sorts by the same table, so the row the notch is
        // reporting is the row at the top of the list.
        #expect(MonitorAggregation.rowOrder(approval, input))
        #expect(!MonitorAggregation.rowOrder(input, approval))

        // One row that is both: its own turn is asking a question while a
        // subagent sits on a dialog. The question came second, so it wins.
        let asking = session(.claudeCode, "both", .inputNeeded, awaitingApproval: 1)
        #expect(asking.subagentsAwaitingApproval)
        #expect(MonitorAggregation.effectiveStatus(of: asking) == .inputNeeded)
        // The same row without the question reports the dialog, as it must --
        // otherwise the exception above would be swallowing the flag whole.
        let notAsking = session(.claudeCode, "both", .running, awaitingApproval: 1)
        #expect(MonitorAggregation.effectiveStatus(of: notAsking) == .approvalNeeded)
    }

    @Test @MainActor
    func rateLimitParserConvertsUsedToRemaining() {
        let response = JSONValue.object([
            "rateLimits": .object([
                "primary": .object([
                    "usedPercent": .number(36),
                    "resetsAt": .number(2_000)
                ])
            ])
        ])

        let quota = CodexSnapshotParser.quota(from: response)

        #expect(quota.remainingPercent == 64)
        #expect(quota.resetsAt == Date(timeIntervalSince1970: 2_000))
    }

    /// Codex reports two windows and names neither, so the name is the only
    /// thing it does publish about one: the window's own duration.
    ///
    /// `account/rateLimits/read` gives `limitName` — null for the account's own
    /// limit — and a `windowDurationMins` per window. `300` is the 5-hour limit
    /// and `10080` the weekly one, which is how the same account sees them in
    /// Codex. `secondary` is null on most accounts and was never read at all;
    /// where it is there, it is a window, and a window is a line.
    @Test @MainActor
    func codexWindowsAreNamedByTheDurationTheProductPublishes() {
        let both = CodexSnapshotParser.quota(from: .object([
            "rateLimits": .object([
                "limitName": .null,
                "primary": .object([
                    "usedPercent": .number(40),
                    "windowDurationMins": .number(300),
                    "resetsAt": .number(2_000)
                ]),
                "secondary": .object([
                    "usedPercent": .number(12),
                    "windowDurationMins": .number(10_080),
                    "resetsAt": .number(9_000)
                ])
            ])
        ]))
        #expect(both.windows.map(\.label) == ["5h limit", "Weekly limit"])
        #expect(both.windows.map(\.remainingPercent) == [60, 88])
        // `primary` stays first, so every surface that draws one rule reads
        // exactly what it read before the second window existed.
        #expect(both.remainingPercent == 60)
        #expect(both.resetsAt == Date(timeIntervalSince1970: 2_000))

        // The shape this account actually has: one weekly window, no second.
        let one = CodexSnapshotParser.quota(from: .object([
            "rateLimits": .object([
                "primary": .object([
                    "usedPercent": .number(0),
                    "windowDurationMins": .number(10_080),
                    "resetsAt": .number(2_000)
                ]),
                "secondary": .null
            ])
        ]))
        #expect(one.windows.map(\.label) == ["Weekly limit"])

        // Durations neither constant covers are written out from the minutes
        // rather than guessed at, and a window with no duration keeps the
        // empty label the single unlabelled rule always had.
        #expect(CodexSnapshotParser.windowLabel(minutes: 60) == "1h limit")
        #expect(CodexSnapshotParser.windowLabel(minutes: 2_880) == "2d limit")
        #expect(CodexSnapshotParser.windowLabel(minutes: 90) == "90m limit")
        #expect(CodexSnapshotParser.windowLabel(minutes: nil) == "")

        // A response with no readable window at all is unavailable, not zero.
        #expect(
            CodexSnapshotParser.quota(from: .object([
                "rateLimits": .object(["primary": .object([:])])
            ])).remainingPercent == nil
        )
    }

    @Test
    func accountUsageParserSelectsTheLocalTodayBucket() throws {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = try #require(TimeZone(secondsFromGMT: 0))
        let now = try #require(calendar.date(from: DateComponents(
            year: 2026,
            month: 8,
            day: 13,
            hour: 12
        )))
        let response = JSONValue.object([
            "dailyUsageBuckets": .array([
                .object([
                    "startDate": .string("2026-08-12"),
                    "tokens": .number(9_999)
                ]),
                .object([
                    "startDate": .string("2026-08-13"),
                    "tokens": .number(13_400)
