        }

        let repository = HookEventRepository(paths: paths)
        var clock = 9_200.0
        func emit(_ event: [String: Any]) throws {
            clock += 1
            var payload = event
            payload["received_at"] = clock
            payload["session_id"] = "thread-reviewed"
            payload["turn_id"] = payload["turn_id"] ?? "turn-real"
            try JSONSerialization.data(withJSONObject: payload).deliver(to: repository)
        }

        try emit(["hook_event_name": "UserPromptSubmit", "prompt": "the user's own prompt"])
        try emit([
            "hook_event_name": "PreToolUse",
            "tool_name": "Bash",
            "tool_use_id": "exec-reviewed"
        ])
        try emit([
            "hook_event_name": "PostToolUse",
            "tool_name": "Bash",
            "tool_use_id": "exec-reviewed"
        ])
        try emit(["hook_event_name": "Stop", "last_assistant_message": "Done."])
        let finished = await repository.drainDeliveredEvents().turns.first
        #expect(finished?.status == .completed)
        let realStart = try #require(finished?.startedAt)

        // The reviewer's first prompt, arriving late: a turn this thread has
        // never seen, on a thread that has finished.
        try emit([
            "hook_event_name": "UserPromptSubmit",
            "turn_id": "turn-reviewer",
            "prompt": "The following is the Codex agent history whose request action you are assessing."
        ])
        let held = await repository.drainDeliveredEvents().turns.first
        #expect(held?.turnID == "turn-real")
        #expect(held?.status == .completed)
        #expect(held?.startedAt == realStart)
        #expect(held?.promptPreview == "the user's own prompt")
        #expect(held?.assistantPreview == "Done.")

        // The thread's own record still names the finished turn, and a record
        // may only redeem what is held: nothing moves.
        let unmoved = await repository.adoptTurnsOnRecord([
            TurnOnRecord(threadID: "thread-reviewed", turnID: "turn-real")
        ]).turns.first
        #expect(unmoved?.turnID == "turn-real")
        #expect(unmoved?.status == .completed)

        // Nor does the reviewer's own check, should it run one.
        try emit([
            "hook_event_name": "PreToolUse",
            "turn_id": "turn-reviewer",
            "tool_name": "Bash",
            "tool_use_id": "exec-reviewer"
        ])
        #expect(await repository.drainDeliveredEvents().turns.first?.turnID == "turn-real")

        // The user's own next turn is held in the same way, and its record is
        // what gives it the row -- with its own start and its own text.
        try emit(["hook_event_name": "UserPromptSubmit", "turn_id": "turn-next", "prompt": "next"])
        let nextStart = Date(timeIntervalSince1970: clock)
        #expect(await repository.drainDeliveredEvents().turns.first?.turnID == "turn-real")
        let next = await repository.adoptTurnsOnRecord([
            TurnOnRecord(threadID: "thread-reviewed", turnID: "turn-next")
        ]).turns.first
        #expect(next?.turnID == "turn-next")
        #expect(next?.status == .running)
        #expect(next?.promptPreview == "next")
        #expect(next?.startedAt == nextStart)

        // And a reviewer's turn refused once stays refused, whatever the
        // thread has done since.
        try emit(["hook_event_name": "Stop", "turn_id": "turn-reviewer"])
        #expect(await repository.drainDeliveredEvents().turns.first?.turnID == "turn-next")
        #expect(await repository.drainDeliveredEvents().turns.first?.status == .running)
    }

    /// Claude Code's next prompt after `Stop` still opens its turn at once.
    ///
    /// The hold on a finished thread is Codex's, because the caller is and the
    /// record is: nothing runs under a Claude Code thread's identity without
    /// saying so, and there is no rollout to redeem a hold from -- a held
    /// prompt there is redeemed by its own first event, and a prompt after
    /// `Stop` has no reason to wait for one.
    @Test
    func claudeCodeOpensTheNextTurnAtOnceAfterStop() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let repository = HookEventRepository(
            paths: paths,
            vocabulary: ClaudeCodeHookVocabulary()
        )
        var clock = 9_300.0
        func emit(_ event: [String: Any]) throws {
            clock += 1
            var payload = event
            payload["received_at"] = clock
            payload["session_id"] = "session-finished"
            payload["prompt_id"] = payload["prompt_id"] ?? "turn-first"
            try JSONSerialization.data(withJSONObject: payload).deliver(to: repository)
        }

        try emit(["hook_event_name": "UserPromptSubmit", "prompt": "the first prompt"])
        try emit(["hook_event_name": "Stop", "last_assistant_message": "Done."])
        #expect(await repository.drainDeliveredEvents().turns.first?.status == .completed)

        try emit(["hook_event_name": "UserPromptSubmit", "prompt_id": "turn-second", "prompt": "second"])
        let next = await repository.drainDeliveredEvents().turns.first
        #expect(next?.turnID == "turn-second")
        #expect(next?.status == .running)
        #expect(next?.promptPreview == "second")
    }

    /// Holding a prompt wakes the sweep that can redeem it.
    ///
    /// A held prompt changes nothing a row draws, and the sweep that reads the
    /// thread's record listens on the same edge the rows do. Without the hold
    /// being a term of that edge, the user's own next turn on a finished
    /// Codex thread waited for the next event, or the interval, to be given
    /// its row -- and the record it needs is on disk before the hook.
    @Test
    func aHeldPromptWakesTheSweepThatCanRedeemIt() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let repository = HookEventRepository(paths: paths)
        var clock = 9_400.0
        func emit(_ event: [String: Any]) throws {
            clock += 1
            var payload = event
            payload["received_at"] = clock
            payload["session_id"] = "thread-finished"
            payload["turn_id"] = payload["turn_id"] ?? "turn-first"
            try JSONSerialization.data(withJSONObject: payload).deliver(to: repository)
        }

        try emit(["hook_event_name": "UserPromptSubmit", "prompt": "the first prompt"])
        try emit(["hook_event_name": "Stop", "last_assistant_message": "Done."])
        #expect(await repository.drainDeliveredEvents().turns.first?.status == .completed)

        let prompt = try JSONSerialization.data(withJSONObject: [
            "received_at": clock + 1,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-finished",
            "turn_id": "turn-next",
            "prompt": "next"
        ] as [String: Any])
        let woke = await receivesChange(repository.changeEvents()) {
            prompt.deliver(to: repository)
        }
        #expect(woke, "a held prompt must wake the sweep that reads the record")
        let held = await repository.observedState().turns.first
        #expect(held?.turnID == "turn-first")
        #expect(held?.heldTurnStart?.turnID == "turn-next")
    }

    @Test @MainActor
    func permissionRequestAloneDoesNotPublishApprovalNeeded() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()
        let timestamp = Date().timeIntervalSince1970
        let prompt = try JSONSerialization.data(withJSONObject: [
            "received_at": timestamp,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ])
        prompt.deliver(to: repository)

        let listedThread = JSONValue.object([
            "id": .string("thread-1"),
            "ephemeral": .bool(false),
            "threadSource": .string("user"),
            "status": .object([
                "type": .string("active"),
                "activeFlags": .array([])
            ])
        ])
        let client = CodexAppServerStub(
            listedThreads: [listedThread],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        // The row waits for the App Server to confirm the thread, so it lands
        // on the fetch after the read rather than on the one that scheduled it.
        let initial = await snapshotWithSessions(from: service)
        #expect(initial.sessions.first?.status == .running)
        await waitForThreadListRequests(
            client,
            atLeast: 1,
            completed: true
        )
        // Neither background App Server read may sit on the Hook -> UI path.
        await client.setThreadListDelayNanoseconds(2_000_000_000)
        await client.setThreadReadDelayNanoseconds(2_000_000_000)

        let approval = try JSONSerialization.data(withJSONObject: [
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "PermissionRequest",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ])
        approval.deliver(to: repository)
        let startedAt = Date()
        let approvalSnapshot = await service.fetchSnapshot()
        let elapsed = Date().timeIntervalSince(startedAt)

        let input = try JSONSerialization.data(withJSONObject: [
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "PreToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "request_user_input",
            "tool_use_id": "tool-1"
        ])
        input.deliver(to: repository)
        let inputSnapshot = await service.fetchSnapshot()
        let threadListRequests = await client.requestCount(method: "thread/list")
        await service.disconnect()

        #expect(approvalSnapshot.sessions.first?.status == .running)
        #expect(inputSnapshot.sessions.first?.status == .inputNeeded)
        #expect(elapsed < 1.5)
        // Hook activity on an already-listed thread no longer re-paginates the
        // whole unarchived set; only the cheap per-thread read follows it.
        #expect(threadListRequests == 1)
    }

    /// The reported bug, end to end.
    ///
    /// A Bash call is announced and then asked about, which is the only shape
    /// Codex has for an ordinary-tool approval. On a thread Desktop reviews
    /// automatically the row must stay Running for the whole decision; on a
    /// thread the person reviews, the same two events must still reach
    /// Approval needed.
    @Test @MainActor
    func automaticallyReviewedThreadNeverPublishesApprovalNeeded() async throws {
        func rowStatus(reviewer: String) async throws -> SessionStatus? {
            let paths = makeTemporaryHookPaths()
            defer {
                try? FileManager.default.removeItem(
                    at: paths.supportDirectory.deletingLastPathComponent()
                )
            }
            let root = FileManager.default.temporaryDirectory
                .appendingPathComponent(UUID().uuidString, isDirectory: true)
            defer { try? FileManager.default.removeItem(at: root) }
            try FileManager.default.createDirectory(
                at: root,
                withIntermediateDirectories: true
            )
            let stateFile = root
                .appendingPathComponent(".codex-global-state.json")
            try JSONSerialization.data(withJSONObject: [
                "electron-persisted-atom-state": [
                    "heartbeat-thread-permissions-by-id": [
                        "thread-1": ["approvalsReviewer": reviewer]
                    ]
                ]
            ]).write(to: stateFile, options: .atomic)

            let installer = CodexHookRegistrar(paths: paths)
            let repository = HookEventRepository(paths: paths)
            try await installer.install()
            let timestamp = Date().timeIntervalSince1970
            // The reviewer was set some time before this Turn, but the file
            // carrying it is rewritten whole about half a second into every
            // Turn Desktop hosts -- sending clears the composer, and the draft
            // is a persisted atom. That write is the one the map is read from,
            // and the pin will not take an answer from any other.
            try FileManager.default.setAttributes(
                [.modificationDate: Date(timeIntervalSince1970: timestamp + 0.5)],
                ofItemAtPath: stateFile.path
            )
            for event in [
                [
                    "received_at": timestamp,
                    "hook_event_name": "UserPromptSubmit",
                    "session_id": "thread-1",
                    "turn_id": "turn-1"
                ],
                [
                    "received_at": timestamp + 1,
                    "hook_event_name": "PreToolUse",
                    "session_id": "thread-1",
                    "turn_id": "turn-1",
                    "tool_name": "Bash",
                    "tool_use_id": "exec-1"
                ],
                [
                    "received_at": timestamp + 2,
                    "hook_event_name": "PermissionRequest",
                    "session_id": "thread-1",
                    "turn_id": "turn-1",
                    "tool_name": "Bash"
                ]
            ] {
                try JSONSerialization.data(withJSONObject: event)
                    .deliver(to: repository)
            }

            let client = CodexAppServerStub(
                listedThreads: [
                    .object([
                        "id": .string("thread-1"),
                        "ephemeral": .bool(false),
                        "threadSource": .string("user")
                    ])
                ],
                loadedListResults: []
            )
            let service = LiveCodexMonitorService(
                client: client,
                hookEvents: repository,
                hookRegistrar: installer,
                approvalRouting: CodexDesktopApprovalRoutingRepository(
                    stateFileURL: stateFile
                ),
                desktopProcessIdentifierProvider: { 4_242 }
            )
            let snapshot = await snapshotWithSessions(from: service)
            await service.disconnect()
            return snapshot.sessions.first?.status
        }

        #expect(try await rowStatus(reviewer: "auto_review") == .running)
        #expect(try await rowStatus(reviewer: "user") == .approvalNeeded)
    }

    /// The routing answer belongs to the Turn, not to the thread's setting as
    /// it stands when the row is drawn.
    @Test @MainActor
    func approvalRoutingPinKeepsTheAnswerTheTurnStartedUnder() {
        var pin = TurnApprovalRoutingPin()
        let turnStart = Date(timeIntervalSince1970: 1_000)
        let firstTurn = TurnApprovalRoutingPin.TurnIdentity(
            threadID: "thread-1",
            turnID: "turn-1"
        )
        let personReviews = desktopRouting(
            automatic: [], forTurnStartedAt: turnStart
        )
        let codexReviews = desktopRouting(
            automatic: ["thread-1"], forTurnStartedAt: turnStart
        )
        // Desktop rewrites the map the instant the reviewer changes, so a
        // switch made five minutes into the turn carries that instant.
        let codexReviewsFromTheSwitch = desktopRouting(
            automatic: ["thread-1"],
            forTurnStartedAt: turnStart,
            writtenAfter: 300
        )
        let personReviewsFromTheSwitch = desktopRouting(
            automatic: [], forTurnStartedAt: turnStart, writtenAfter: 300
        )

        let atTurnStart = pin.approvalsReachTheUser(
            forTurn: firstTurn,
            startedAt: turnStart,
            in: personReviews
        )
        // Desktop records the switch mid-turn. The turn in flight keeps the
        // reviewer it started with, so the row must too.
        let afterTheSwitch = pin.approvalsReachTheUser(
            forTurn: firstTurn,
            startedAt: turnStart,
            in: codexReviewsFromTheSwitch
        )
        #expect(atTurnStart)
        #expect(afterTheSwitch)

        // Symmetric: a thread switched the other way mid-turn is still being
        // reviewed automatically until this turn ends.
        var reversed = TurnApprovalRoutingPin()
        let reversedAtTurnStart = reversed.approvalsReachTheUser(
            forTurn: firstTurn,
            startedAt: turnStart,
            in: codexReviews
        )
        let reversedAfterTheSwitch = reversed.approvalsReachTheUser(
            forTurn: firstTurn,
            startedAt: turnStart,
            in: personReviewsFromTheSwitch
        )
        #expect(!reversedAtTurnStart)
        #expect(!reversedAfterTheSwitch)

        // The next turn on the same thread asks again, and gets the answer
        // that is now true.
        let secondTurnStart = turnStart.addingTimeInterval(600)
        let secondTurn = TurnApprovalRoutingPin.TurnIdentity(
            threadID: "thread-1",
            turnID: "turn-2"
        )
        let nextTurnAnswer = pin.approvalsReachTheUser(
            forTurn: secondTurn,
            startedAt: secondTurnStart,
            in: desktopRouting(
                automatic: ["thread-1"], forTurnStartedAt: secondTurnStart
            )
        )
        #expect(!nextTurnAnswer)

        // And a turn the reducer no longer holds is forgotten, so the same
        // identity coming back is a fresh question rather than a stale answer.
        pin.retain(turns: [secondTurn])
        let forgottenTurnAnswer = pin.approvalsReachTheUser(
            forTurn: firstTurn,
            startedAt: turnStart,
            in: personReviews
        )
        let retainedTurnAnswer = pin.approvalsReachTheUser(
            forTurn: secondTurn,
            startedAt: secondTurnStart,
            in: desktopRouting(
                automatic: [], forTurnStartedAt: secondTurnStart
            )
        )
        #expect(forgottenTurnAnswer)
        #expect(!retainedTurnAnswer)
    }

    /// The reviewer the running Turn was handed, out of the Turn's own record.
    ///
    /// Every timestamp below is relative to the Turn's start because that is
    /// the relationship the reader depends on: Codex writes `turn_context` at
    /// the head of the Turn, ~65 ms before the `UserPromptSubmit` that becomes
    /// `startedAt` (measured 2026-08-25, CLI `0.149.0-alpha.4.3`).
    @Test @MainActor
    func rolloutTurnReviewerReadsTheReviewerTheRunningTurnWasHanded() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )

        let stampFormatter = ISO8601DateFormatter()
        stampFormatter.formatOptions = [
            .withInternetDateTime,
            .withFractionalSeconds
        ]
        let turnStartedAt = Date()
        func line(_ object: [String: Any]) throws -> String {
            let data = try JSONSerialization.data(withJSONObject: object)
            return String(decoding: data, as: UTF8.self)
        }
        func turnContext(
            reviewer: String?,
            offsetFromTurnStart: TimeInterval,
            turnID: String? = nil
        ) throws -> String {
            var payload: [String: Any] = ["approval_policy": "on-request"]
            if let reviewer {
                payload["approvals_reviewer"] = reviewer
            }
            if let turnID {
                payload["turn_id"] = turnID
            }
            return try line([
                "timestamp": stampFormatter.string(
                    from: turnStartedAt.addingTimeInterval(offsetFromTurnStart)
                ),
                "type": "turn_context",
                "payload": payload
            ])
        }
        func writeRollout(_ lines: [String]) throws -> String {
            let file = root.appendingPathComponent("\(UUID().uuidString).jsonl")
            try Data(lines.joined(separator: "\n").appending("\n").utf8)
                .write(to: file, options: .atomic)
            return file.path
        }
        // Anything but a `turn_context`, and deliberately carrying the word:
        // the prefilter is an optimisation, and the decode is what decides.
        let noise = try line([
            "timestamp": stampFormatter.string(from: turnStartedAt),
            "type": "response_item",
            "payload": ["type": "message", "text": "about the turn_context"]
        ])

        let reader = CodexRolloutTurnReviewerReader()
        func read(_ path: String, asTurn turnID: String = "turn-1") async -> Bool? {
            await reader.approvalsReachTheUser(
                forTurn: turnID,
                startedAt: turnStartedAt,
                inRolloutAt: path
            )
        }

        let automatic = try writeRollout([
            noise,
            try turnContext(reviewer: "auto_review", offsetFromTurnStart: -0.065),
            noise
        ])
        #expect(await read(automatic) == false)

        let person = try writeRollout([
            try turnContext(reviewer: "user", offsetFromTurnStart: -0.065),
            noise
        ])
        #expect(await read(person) == true)

        // A reviewer a later Codex invents proves nothing, so it must not
        // silence the state.
        let unrecognised = try writeRollout([
            try turnContext(reviewer: "team_lead", offsetFromTurnStart: -0.065)
        ])
        #expect(await read(unrecognised) == true)

        // The newest record wins over the one the Turn before it wrote.
        let switched = try writeRollout([
            try turnContext(reviewer: "user", offsetFromTurnStart: -600),
            noise,
            try turnContext(reviewer: "auto_review", offsetFromTurnStart: -0.065)
        ])
        #expect(await read(switched) == false)

        // **The reading that must not be made.** Only the previous Turn's
        // record is on disk, and answering with it is the whole failure this
        // reader exists to end -- so it says nothing and leaves the map to
        // answer.
        let staleOnly = try writeRollout([
            try turnContext(reviewer: "user", offsetFromTurnStart: -600),
            noise
        ])
        #expect(await read(staleOnly) == nil)

        // **Where the record names its Turn, that is the test.** The window
        // above is a proxy for this question, and the rollout a resumed Turn
        // leaves behind is where the proxy breaks: interrupt, edit, send, and
        // the previous file's last record can be seconds rather than minutes
        // old while naming the Turn the user interrupted.
        let interruptedTurnsRecord = try writeRollout([
            try turnContext(
                reviewer: "user",
                offsetFromTurnStart: -1,
                turnID: "turn-0"
            )
        ])
        #expect(await read(interruptedTurnsRecord) == nil)

        // And it settles the answer the other way too: this Turn's own record
        // answers however late the reading is, where the window would have
        // refused it.
        let ownRecordReadLate = try writeRollout([
            try turnContext(
                reviewer: "auto_review",
                offsetFromTurnStart: -600,
                turnID: "turn-1"
            )
        ])
        #expect(await read(ownRecordReadLate) == false)

        let silent = try writeRollout([noise, noise])
        #expect(await read(silent) == nil)

        let reviewerless = try writeRollout([
            try turnContext(reviewer: nil, offsetFromTurnStart: -0.065)
        ])
        #expect(await read(reviewerless) == nil)

        #expect(await read(root.appendingPathComponent("absent.jsonl").path) == nil)

        // A rollout whose head is megabytes away is read from its tail, and the
        // seek that gets there lands mid-record.
        let padding = try line([
            "timestamp": stampFormatter.string(from: turnStartedAt),
            "type": "response_item",
            "payload": [
                "type": "message",
                "text": String(repeating: "p", count: 8_192)
            ]
        ])
        let paddedLines = Array(repeating: padding, count: 400)
        let deepInAFile = try writeRollout(
            paddedLines
                + [try turnContext(
                    reviewer: "auto_review",
                    offsetFromTurnStart: -0.065
                )]
        )
        #expect(await read(deepInAFile) == false)

        // And a record already pushed past the tail window is one this reader
        // declines to claim anything about.
        let pastTheWindow = try writeRollout(
            [try turnContext(reviewer: "auto_review", offsetFromTurnStart: -0.065)]
                + paddedLines
        )
        #expect(await read(pastTheWindow) == nil)
    }

    /// Which Turn a thread's rollout says the thread is on.
    ///
    /// The second question the same reader answers from the same tail, and the
    /// one that settles a held prompt: a nested agent's turns are written to a
    /// rollout of its own, so a thread's record names the reviewer's turn
    /// never and its own turn always. Newest wins, because at any instant the
    /// last `turn_context` a rollout holds is the Turn that thread is on.
    @Test @MainActor
    func rolloutReaderNamesTheTurnTheThreadsOwnRecordIsOn() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )

        let stampFormatter = ISO8601DateFormatter()
        stampFormatter.formatOptions = [
            .withInternetDateTime,
            .withFractionalSeconds
        ]
        func line(_ object: [String: Any]) throws -> String {
            let data = try JSONSerialization.data(withJSONObject: object)
            return String(decoding: data, as: UTF8.self)
        }
        func turnContext(_ turnID: String?) throws -> String {
            var payload: [String: Any] = ["cwd": "/tmp"]
            if let turnID { payload["turn_id"] = turnID }
            return try line([
                "timestamp": stampFormatter.string(from: Date()),
                "type": "turn_context",
                "payload": payload
            ])
        }
        // Carries the word and is not the record: the prefilter is an
        // optimisation and the decode is what decides.
        let noise = try line([
            "timestamp": stampFormatter.string(from: Date()),
            "type": "response_item",
            "payload": ["type": "message", "text": "about the turn_context"]
        ])
        func writeRollout(_ lines: [String]) throws -> String {
            let file = root.appendingPathComponent("\(UUID().uuidString).jsonl")
            try Data(lines.joined(separator: "\n").appending("\n").utf8)
                .write(to: file, options: .atomic)
            return file.path
        }

        let reader = CodexRolloutTurnAbortReader()

        let onRecord = try writeRollout([
            noise,
            try turnContext("turn-0"),
            noise,
            try turnContext("turn-1"),
            noise
        ])
        #expect(await reader.turnOnRecord(inRolloutAt: onRecord) == "turn-1")

        // Nothing to say is the refusal, and it is the only one this reading
        // ever has to make: a held prompt no record names simply stays held.
        let silent = try writeRollout([noise, noise])
        #expect(await reader.turnOnRecord(inRolloutAt: silent) == nil)

        // A build that stops writing the field answers nothing rather than
        // answering with the record it happens to have found.
        let unnamed = try writeRollout([try turnContext(nil)])
        #expect(await reader.turnOnRecord(inRolloutAt: unnamed) == nil)

        #expect(await reader.turnOnRecord(inRolloutAt: root.path + "/absent.jsonl") == nil)
    }

    /// The abort record, which is all a stopped Codex Turn ever reports.
    ///
    /// Pressing stop in Codex Desktop sends no hook of any kind, so this record
    /// is the only thing that can end the Turn — and it names it, which is what
    /// lets it be held to that one Turn rather than to whichever is open.
    @Test @MainActor
    func rolloutAbortReaderEndsOnlyTheTurnTheRecordNames() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )

        let stampFormatter = ISO8601DateFormatter()
        stampFormatter.formatOptions = [
            .withInternetDateTime,
            .withFractionalSeconds
        ]
        // Whole seconds, so a stamp survives the round trip through the
        // rollout's millisecond format and the dates below can be compared
        // rather than bracketed.
        let lastEventAt = Date(
            timeIntervalSince1970: Date().timeIntervalSince1970.rounded(.down)
        )
        func line(_ object: [String: Any]) throws -> String {
            let data = try JSONSerialization.data(withJSONObject: object)
            return String(decoding: data, as: UTF8.self)
        }
        /// The record Codex writes, verbatim in shape — including `reason`,
        /// which this reader deliberately never looks at.
        func abort(
            turn: String,
            offsetFromLastEvent: TimeInterval,
            reason: String = "interrupted"
        ) throws -> String {
            try line([
                "timestamp": stampFormatter.string(
                    from: lastEventAt.addingTimeInterval(offsetFromLastEvent)
                ),
                "type": "event_msg",
                "payload": [
                    "type": "turn_aborted",
                    "turn_id": turn,
                    "reason": reason,
                    "duration_ms": 4_466
                ]
            ])
        }
        /// The developer message Codex writes one line *before* the abort. It
        /// carries the word in its text and is not the record.
        let abortNarration = try line([
            "timestamp": stampFormatter.string(from: lastEventAt),
            "type": "response_item",
            "payload": [
                "type": "message",
                "role": "developer",
                "text": "<turn_aborted>The previous turn was interrupted.</turn_aborted>"
            ]
        ])
        func writeRollout(_ lines: [String]) throws -> String {
            let file = root.appendingPathComponent("\(UUID().uuidString).jsonl")
            try Data(lines.joined(separator: "\n").appending("\n").utf8)
                .write(to: file, options: .atomic)
            return file.path
        }

        let reader = CodexRolloutTurnAbortReader()
        func read(_ path: String, turn: String = "turn-1") async -> Date? {
            await reader.abortedAt(
                turnID: turn,
                inRolloutAt: path,
                after: lastEventAt
            )
        }

        let stopped = try writeRollout([
            abortNarration,
            try abort(turn: "turn-1", offsetFromLastEvent: 4)
        ])
        #expect(
            await read(stopped) == lastEventAt.addingTimeInterval(4)
        )

        // A reason a later Codex invents still ends the Turn. Requiring the
        // word `interrupted` would leave the row Running for ever, which is the
        // failure this reader exists to end.
        let unknownReason = try writeRollout([
            try abort(turn: "turn-1", offsetFromLastEvent: 4, reason: "replaced")
        ])
        #expect(
            await read(unknownReason) == lastEventAt.addingTimeInterval(4)
        )

        // **The reading that must not be made.** The record names the Turn
        // before this one, and ending the open Turn on it retires a Turn that
        // is still running.
        let previousTurn = try writeRollout([
            try abort(turn: "turn-0", offsetFromLastEvent: 4)
        ])
        #expect(await read(previousTurn) == nil)

        // Nor may a record older than the Turn's last event end it: this Turn
        // has moved since, so the record cannot be describing it.
        let stale = try writeRollout([
            try abort(turn: "turn-1", offsetFromLastEvent: -30)
        ])
        #expect(await read(stale) == nil)

        // The narration alone is not the record.
        let narrationOnly = try writeRollout([abortNarration])
        #expect(await read(narrationOnly) == nil)

        let unnamed = try writeRollout([try line([
            "timestamp": stampFormatter.string(
                from: lastEventAt.addingTimeInterval(4)
            ),
            "type": "event_msg",
            "payload": ["type": "turn_aborted", "reason": "interrupted"]
        ])])
        #expect(await read(unnamed) == nil)

        let running = try writeRollout([try line([
            "timestamp": stampFormatter.string(from: lastEventAt),
            "type": "event_msg",
            "payload": ["type": "token_count"]
        ])])
        #expect(await read(running) == nil)

        #expect(await read(root.appendingPathComponent("absent.jsonl").path) == nil)

        // The newest abort is the whole reading: one naming another Turn after
        // this Turn's own says this rollout has moved on, and an answer read
        // out of the older record would be about a Turn that cannot still be
        // open.
        let superseded = try writeRollout([
            try abort(turn: "turn-1", offsetFromLastEvent: 4),
            try abort(turn: "turn-2", offsetFromLastEvent: 9)
        ])
        #expect(await read(superseded) == nil)

        // A long turn's rollout is read from its tail, and the seek that gets
        // there lands mid-record.
        let padding = try line([
            "timestamp": stampFormatter.string(from: lastEventAt),
            "type": "response_item",
            "payload": [
                "type": "message",
                "text": String(repeating: "p", count: 8_192)
            ]
        ])
        let paddedLines = Array(repeating: padding, count: 64)
        let deepInAFile = try writeRollout(
            paddedLines + [try abort(turn: "turn-1", offsetFromLastEvent: 4)]
        )
        #expect(
            await read(deepInAFile) == lastEventAt.addingTimeInterval(4)
        )

        // And a record already pushed past the tail window is one this reader
        // declines to claim anything about. Measured on this machine, an abort
        // whose thread was left alone sits 249-940 bytes from the end, so the
        // window is sized for a refresh that is late rather than for one that
        // has been away for a whole turn.
        let pastTheWindow = try writeRollout(
            [try abort(turn: "turn-1", offsetFromLastEvent: 4)] + paddedLines
        )
        #expect(await read(pastTheWindow) == nil)

        // The answer is cached on the file's revision, so the ordinary refresh
        // costs one `lstat`. A rollout that grows is a new revision: the abort
        // the next record brings is found, not answered from the cache.
        let grew = try writeRollout([padding])
        #expect(await read(grew) == nil)
        let handle = try FileHandle(forWritingTo: URL(fileURLWithPath: grew))
        try handle.seekToEnd()
        try handle.write(
            contentsOf: Data(
                (try abort(turn: "turn-1", offsetFromLastEvent: 4) + "\n").utf8
            )
        )
        try handle.close()
        #expect(await read(grew) == lastEventAt.addingTimeInterval(4))
    }

    /// A map written outside the Turn's opening moments may not silence it,
    /// at either end.
    ///
    /// **Too old** is the sequence the user hits: switch the thread from
    /// `auto_review` to yourself, type the prompt, send. The switch reaches
    /// Desktop's memory at once and its file not at all while the typing lasts
    /// -- one trailing 500 ms debounce, shared by every persisted atom, and
    /// the composer draft is written on every keystroke (measured at 45.4
    /// seconds over 165 characters, Desktop `26.820.60940`, 2026-08-26). The
    /// map this app then reads still says `auto_review`, and pinning it
    /// silences every approval dialog the user is being shown for the whole
    /// Turn.
    ///
    /// **Too new** is the case ``TurnApprovalRoutingPin`` was built for, and
    /// refusing the stale reading must not reopen it: a reviewer switched
    /// deliberately five minutes in describes the thread, not the Turn in
    /// flight.
    ///
    /// Neither refusal pins, so the write Desktop makes at the start of the
    /// Turn still answers.
    @Test @MainActor
    func approvalRoutingRefusesAMapFromOutsideTheTurnsOpeningMoments() {
        var pin = TurnApprovalRoutingPin()
        let turnStart = Date(timeIntervalSince1970: 1_000)
        let turn = TurnApprovalRoutingPin.TurnIdentity(
            threadID: "thread-1",
            turnID: "turn-1"
        )

        // Desktop last wrote this file half a minute before the Turn, and it
        // still names the thread automatic. It cannot be shown to be current,
        // so it says nothing.
        let stale = desktopRouting(
            automatic: ["thread-1"],
            forTurnStartedAt: turnStart,
            writtenAfter: -30
        )
        let onTheStaleMap = pin.approvalsReachTheUser(
            forTurn: turn, startedAt: turnStart, in: stale
        )
        #expect(
            onTheStaleMap,
            "a map from before the Turn must not silence its approvals"
        )

        // And it did not pin: the write Desktop makes when the composer is
        // cleared lands moments later, and that one does answer.
        let atTheTurnsStart = desktopRouting(
            automatic: ["thread-1"], forTurnStartedAt: turnStart
        )
        let onTheTurnsOwnWrite = pin.approvalsReachTheUser(
            forTurn: turn, startedAt: turnStart, in: atTheTurnsStart
        )
        #expect(
            !onTheTurnsOwnWrite,
            "the refusal must not cost the Turn its real answer"
        )

        // The other end, on a Turn that never got an admissible reading: a map
        // written well into the Turn describes the thread now, not the Turn.
        var late = TurnApprovalRoutingPin()
        let afterASwitch = desktopRouting(
            automatic: ["thread-1"],
            forTurnStartedAt: turnStart,
            writtenAfter: 300
        )
        let onASwitchMidTurn = late.approvalsReachTheUser(
            forTurn: turn, startedAt: turnStart, in: afterASwitch
        )
        #expect(
            onASwitchMidTurn,
            "a switch made mid-turn must not silence the Turn in flight"
        )

        // The authority still outranks both refusals.
        late.recordRolloutReading(
            false,
            forTurn: turn,
            inRolloutReportedAt: turnStart
        )
        let onTheAuthority = late.approvalsReachTheUser(
            forTurn: turn, startedAt: turnStart, in: afterASwitch
        )
        #expect(!onTheAuthority)
    }

    /// The rollout answers once, and its answer outranks the map's.
    @Test @MainActor
    func approvalRoutingPinPrefersTheRolloutAndFallsBackToTheMap() {
        var pin = TurnApprovalRoutingPin()
        let turnStart = Date(timeIntervalSince1970: 1_000)
        let turn = TurnApprovalRoutingPin.TurnIdentity(
            threadID: "thread-1",
            turnID: "turn-1"
        )
        let mapSaysPerson = desktopRouting(
            automatic: [], forTurnStartedAt: turnStart
        )

        // The path this app holds was reported while the Turn was starting,
        // which is the ordinary case: `thread/read` is on a ten-second
        // interval and a rollout that has not rotated is named correctly by
        // every one of those readings.
        let pathReportedAt = turnStart.addingTimeInterval(-3)

        // A refresh before the rollout path is known still has to answer, and
        // the map is what it answers with.
        #expect(
            pin.awaitsRolloutReading(
                forTurn: turn,
                startedAt: turnStart,
                inRolloutReportedAt: pathReportedAt
            )
        )
        let beforeTheReading = pin.approvalsReachTheUser(
            forTurn: turn,
            startedAt: turnStart,
            in: mapSaysPerson
        )
        #expect(beforeTheReading)

        // The rollout then says what the Turn was actually handed, and that
        // replaces the map's answer rather than being ignored as "already
        // pinned".
        pin.recordRolloutReading(
            false,
            forTurn: turn,
            inRolloutReportedAt: pathReportedAt
        )
        let afterTheReading = pin.approvalsReachTheUser(
            forTurn: turn,
            startedAt: turnStart,
            in: mapSaysPerson
        )
        #expect(
            !pin.awaitsRolloutReading(
                forTurn: turn,
                startedAt: turnStart,
                inRolloutReportedAt: turnStart.addingTimeInterval(60)
            ),
            "an answered Turn is not asked again, however the path moves"
        )
        #expect(!afterTheReading)

        // A rollout that is the Turn's own and does not carry the record
        // closes the reading without claiming anything: the map goes on
        // answering, pinned for the Turn exactly as it was before this reading
        // existed.
        var unreadable = TurnApprovalRoutingPin()
        unreadable.recordRolloutReading(
            nil,
            forTurn: turn,
            inRolloutReportedAt: turnStart.addingTimeInterval(0.5)
        )
        #expect(
            !unreadable.awaitsRolloutReading(
                forTurn: turn,
                startedAt: turnStart,
                inRolloutReportedAt: turnStart.addingTimeInterval(10)
            ),
            "a file named after this Turn began will not gain what it lacks"
        )
        let codexReviews = desktopRouting(
            automatic: ["thread-1"], forTurnStartedAt: turnStart
        )
        let fromTheMap = unreadable.approvalsReachTheUser(
            forTurn: turn,
            startedAt: turnStart,
            in: codexReviews
        )
        let afterTheMapChanged = unreadable.approvalsReachTheUser(
            forTurn: turn,
            startedAt: turnStart,
            in: mapSaysPerson
        )
        #expect(!fromTheMap)
        #expect(!afterTheMapChanged)

        // And a forgotten Turn is a fresh question, reading included.
        unreadable.retain(turns: [])
        #expect(
            unreadable.awaitsRolloutReading(
                forTurn: turn,
                startedAt: turnStart,
                inRolloutReportedAt: pathReportedAt
            )
        )
    }

    /// A reading made in the wrong file is not an answer about this Turn.
    ///
    /// **The rollout a thread is written to moves.** Codex writes a Turn
    /// resumed after an interrupt into a new rollout for the same thread, and
    /// the path this app holds comes from a `thread/read` up to a metadata
    /// interval old. Measured 2026-08-31 on thread `01a058c7` (CLI
    /// `0.151.0-alpha.7.2`): interrupted at `…38.039`, new rollout at
    /// `…44.592`, the resumed Turn's `UserPromptSubmit` at `…46.263`, and this
    /// app's last `thread/read` at `…36.206` — eight seconds before the file
    /// it named stopped being the Turn's.
    ///
    /// Read once and recorded as final, that emptiness cost the Turn its whole
    /// life on the map, which had nothing admissible to say either.
    @Test @MainActor
    func aReadingOfTheRolloutTheTurnIsNoLongerInIsNotFinal() {
        var pin = TurnApprovalRoutingPin()
        let turnStart = Date(timeIntervalSince1970: 1_000)
        let turn = TurnApprovalRoutingPin.TurnIdentity(
            threadID: "thread-1",
            turnID: "turn-2"
        )

        // The path in hand was reported ten seconds before this Turn began,
        // which is before Codex rotated the rollout. The record is not in that
        // file and the reading comes back empty.
        let pathFromBeforeTheTurn = turnStart.addingTimeInterval(-10)
        #expect(
            pin.awaitsRolloutReading(
                forTurn: turn,
                startedAt: turnStart,
                inRolloutReportedAt: pathFromBeforeTheTurn
            )
        )
        pin.recordRolloutReading(
            nil,
            forTurn: turn,
            inRolloutReportedAt: pathFromBeforeTheTurn
        )

        // Nothing has changed yet, so nothing is re-read: one reading per
        // rollout the Turn could be in, not one per refresh.
        #expect(
            !pin.awaitsRolloutReading(
                forTurn: turn,
                startedAt: turnStart,
                inRolloutReportedAt: pathFromBeforeTheTurn
            ),
            "the same path must not be read again on every refresh"
        )

        // The next `thread/read` names the rollout this Turn is actually in,
        // and the question reopens.
        let pathFromInsideTheTurn = turnStart.addingTimeInterval(6.7)
        #expect(
            pin.awaitsRolloutReading(
                forTurn: turn,
                startedAt: turnStart,
                inRolloutReportedAt: pathFromInsideTheTurn
            ),
            "a newer path is a new file to look in"
        )
        pin.recordRolloutReading(
            false,
            forTurn: turn,
            inRolloutReportedAt: pathFromInsideTheTurn
        )
        let answered = pin.approvalsReachTheUser(
            forTurn: turn,
            startedAt: turnStart,
            in: desktopRouting(
                automatic: [],
                forTurnStartedAt: turnStart,
                writtenAfter: -30
            )
        )
        #expect(
            !answered,
            "the Turn's own record outranks a map that cannot be shown current"
        )
    }

    /// The reported bug, end to end.
    ///
    /// Measured 2026-08-24 on thread `01a03241`: started under `user`,
    /// switched to `auto_review` five minutes in, and went on opening approval
    /// dialogs the user answered by hand for five minutes after that — the
    /// `rm -rf` it was reported against among them. Reading the map at
    /// projection time left the row on *Running* for every one of them.
    @Test @MainActor
    func aReviewerChangedMidTurnDoesNotSilenceTheApprovalAlreadyBeingAsked() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )
        let stateFile = root.appendingPathComponent(".codex-global-state.json")
        /// Desktop rewrites this file whole, and *when* it did so is half of
        /// what the map says: the pin only takes an answer from a write made
        /// in a Turn's opening moments. So every write here is stamped onto
        /// the same timeline as the hook payloads below rather than left on
        /// the wall clock, which would put them all three seconds before the
        /// second Turn they are supposed to describe.
        func recordReviewer(
            _ reviewer: String,
            writtenAt: TimeInterval
        ) throws {
            try JSONSerialization.data(withJSONObject: [
                "electron-persisted-atom-state": [
                    "heartbeat-thread-permissions-by-id": [
                        "thread-1": ["approvalsReviewer": reviewer]
                    ]
                ]
            ]).write(to: stateFile, options: .atomic)
            try FileManager.default.setAttributes(
                [.modificationDate: Date(timeIntervalSince1970: writtenAt)],
                ofItemAtPath: stateFile.path
            )
        }

        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()
        let timestamp = Date().timeIntervalSince1970
        func deliver(_ event: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: event)
                .deliver(to: repository)
        }

        // The turn starts while the person is the reviewer. Sending clears
        // the composer, which is a persisted atom, so Desktop writes this file
        // about half a second into the Turn.
        try recordReviewer("user", writtenAt: timestamp + 0.5)
        try deliver([
            "received_at": timestamp,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ])

        let client = CodexAppServerStub(
            listedThreads: [
                .object([
                    "id": .string("thread-1"),
                    "ephemeral": .bool(false),
                    "threadSource": .string("user")
                ])
            ],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            approvalRouting: CodexDesktopApprovalRoutingRepository(
                stateFileURL: stateFile
            ),
            desktopProcessIdentifierProvider: { 4_242 }
        )
        #expect(await snapshotWithSessions(from: service).sessions.first?.status == .running)

        // Desktop records the switch, inside this Turn's own window rather
        // than safely outside it -- the pin has to hold on the answer it took,
        // not on the switch happening to arrive late.
        try recordReviewer("auto_review", writtenAt: timestamp + 1.5)
        try deliver([
            "received_at": timestamp + 1,
            "hook_event_name": "PreToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Bash",
            "tool_use_id": "exec-1"
        ])
        try deliver([
            "received_at": timestamp + 2,
            "hook_event_name": "PermissionRequest",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Bash"
        ])
        #expect(
            await service.fetchSnapshot().sessions.first?.status
                == .approvalNeeded
        )

        // The *next* turn is the one the switch applies to, and it asks the
        // map again rather than inheriting the answer its predecessor pinned.
        // Desktop writes the file at this Turn's start as it did at the last
        // one's, carrying the same reviewer it has held since the switch.
        //
        // After the first Turn's terminal, which is the only order a thread's
        // own Turns arrive in. On Codex the prompt is held either way until
        // the thread's own record names it (``HookTurnState/heldTurnStart``);
        // this thread is listed without a rollout, so the record is applied
        // here the way the sweep applies it, and the reviewer this test is
        // about stays the map's to answer.
        try deliver([
            "received_at": timestamp + 2.5,
            "hook_event_name": "Stop",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ])
        try deliver([
            "received_at": timestamp + 3,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-2"
        ])
        _ = await repository.drainDeliveredEvents()
        _ = await repository.adoptTurnsOnRecord([
            TurnOnRecord(threadID: "thread-1", turnID: "turn-2")
        ])
        try recordReviewer("auto_review", writtenAt: timestamp + 3.5)
        try deliver([
            "received_at": timestamp + 4,
            "hook_event_name": "PreToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-2",
            "tool_name": "Bash",
            "tool_use_id": "exec-2"
        ])
        try deliver([
            "received_at": timestamp + 5,
            "hook_event_name": "PermissionRequest",
            "session_id": "thread-1",
            "turn_id": "turn-2",
            "tool_name": "Bash"
        ])
        let afterNextTurn = await service.fetchSnapshot()
        await service.disconnect()
        #expect(afterNextTurn.sessions.first?.status == .running)
    }

    /// The second report, end to end.
    ///
    /// Reported 2026-08-25: *Approval needed* on rows where nobody was being
    /// asked, on sessions whose mode had been switched from manual to automatic
    /// partway through, and never on sessions started in automatic mode. That
    /// is a stale map exactly -- a session started in automatic mode has
    /// nothing for Desktop to persist, so its map entry cannot be behind. Here
    /// the map is left saying `user`, which is what it says for as long as
    /// Desktop takes to write the switch down, and the Turn's own
    /// `turn_context` says otherwise.
    @Test @MainActor
    func aTurnHandedToTheReviewerIsNotAnnouncedAsApprovalNeeded() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )

        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()
        let timestamp = Date().timeIntervalSince1970
        let turnStartedAt = Date(timeIntervalSince1970: timestamp)

        // Desktop's copy of the thread's setting, still carrying what the
        // session was started with.
        let stateFile = root.appendingPathComponent(".codex-global-state.json")
        try JSONSerialization.data(withJSONObject: [
            "electron-persisted-atom-state": [
                "heartbeat-thread-permissions-by-id": [
                    "thread-1": ["approvalsReviewer": "user"]
                ]
            ]
        ]).write(to: stateFile, options: .atomic)

        // The Turn's own record, written 65 ms before the hook that starts it.
        let stampFormatter = ISO8601DateFormatter()
        stampFormatter.formatOptions = [
            .withInternetDateTime,
            .withFractionalSeconds
        ]
        let rollout = root.appendingPathComponent("rollout-thread-1.jsonl")
        try Data((String(
            decoding: try JSONSerialization.data(withJSONObject: [
                "timestamp": stampFormatter.string(
                    from: turnStartedAt.addingTimeInterval(-0.065)
                ),
                "type": "turn_context",
                "payload": ["approvals_reviewer": "auto_review"]
            ]),
            as: UTF8.self
        ) + "\n").utf8).write(to: rollout, options: .atomic)

        func deliver(_ event: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: event)
                .deliver(to: repository)
        }
        try deliver([
            "received_at": timestamp,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ])
        // The permission pipeline runs for a reviewed call exactly as it does
        // for one a person is looking at -- measured 2026-08-25 on a
        // `--approve-for-me` run, `PreToolUse` and `PermissionRequest` 35 ms
        // apart with nobody to ask and `PostToolUse` 4.8 s later.
        try deliver([
            "received_at": timestamp + 1,
            "hook_event_name": "PreToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Bash",
            "tool_use_id": "exec-1"
        ])
        try deliver([
            "received_at": timestamp + 2,
            "hook_event_name": "PermissionRequest",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Bash"
        ])

        let client = CodexAppServerStub(
            listedThreads: [
                .object([
                    "id": .string("thread-1"),
                    "ephemeral": .bool(false),
                    "threadSource": .string("user"),
                    "path": .string(rollout.path)
                ])
            ],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            approvalRouting: CodexDesktopApprovalRoutingRepository(
                stateFileURL: stateFile
            ),
            desktopProcessIdentifierProvider: { 4_242 }
        )
        let snapshot = await snapshotWithSessions(from: service)
        await service.disconnect()
        #expect(snapshot.sessions.first?.status == .running)
    }

    /// The third report, end to end: the Turn that was resumed.
    ///
    /// Reported 2026-08-31 — *Approval needed* several times over on a thread
    /// that had been "Approve for me" from its first moment, on a Turn the
    /// user had started, stopped with a double Esc, edited and sent again.
    ///
    /// **Codex writes a resumed Turn into a rollout of its own.** Reconstructed
    /// from the user's own records (thread `01a058c7`, CLI
    /// `0.151.0-alpha.7.2`, Desktop `26.820.60940`): the Turn was interrupted
    /// at `17:08:38.039`, a *new* rollout for the same thread was opened at
    /// `…44.592`, its `turn_context` — `auto_review`, like every other one on
    /// that thread — landed at `…46.229`, and the resumed Turn's
    /// `UserPromptSubmit` 34 ms later at `…46.263`. This app's last
    /// `thread/read` had gone out at `…36.206`, so the path it held still named
    /// the file the interrupted Turn was written to, and the reviewer reading
    /// — made once, and once only — found that file's newest record belonged
    /// to the interrupted Turn. No answer was given, the map had been written
    /// too long before the Turn to be admissible either, and the fallback in
    /// the absence of evidence is that approvals reach the user. The three
    /// calls Codex's own guardian reviewed at `17:09:03`, `17:09:12` and
    /// `17:09:30` were each announced as a person being asked.
    @Test @MainActor
    func aTurnResumedAfterAnInterruptIsNotAnnouncedAsApprovalNeeded() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )

        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()
        let timestamp = Date().timeIntervalSince1970.rounded(.down)
        let stampFormatter = ISO8601DateFormatter()
        stampFormatter.formatOptions = [
            .withInternetDateTime,
            .withFractionalSeconds
        ]
        func line(_ object: [String: Any]) throws -> String {
            String(
                decoding: try JSONSerialization.data(withJSONObject: object),
                as: UTF8.self
            )
        }
        func write(_ lines: [String], to file: URL) throws {
            try Data(lines.joined(separator: "\n").appending("\n").utf8)
                .write(to: file, options: .atomic)
        }
        func turnContext(turnID: String, at offset: TimeInterval) throws -> String {
            try line([
                "timestamp": stampFormatter.string(
                    from: Date(timeIntervalSince1970: timestamp + offset)
                ),
                "type": "turn_context",
                "payload": [
                    "turn_id": turnID,
                    "approvals_reviewer": "auto_review"
                ]
            ])
        }

        // The thread has been reviewed by Codex from its first moment, so
        // every `turn_context` on it says so.
        let interruptedRollout = root.appendingPathComponent("rollout-1.jsonl")
        try write(
            [try turnContext(turnID: "turn-1", at: -0.065)],
            to: interruptedRollout
        )

        // Desktop's map agrees, and cannot say so: it was last written before
        // this Turn and is refused as a reading that may name a reviewer the
        // user has since moved away from. That is what the reported Turn had —
        // the fix has to come from the Turn's own record.
        let stateFile = root.appendingPathComponent(".codex-global-state.json")
        try JSONSerialization.data(withJSONObject: [
            "electron-persisted-atom-state": [
                "heartbeat-thread-permissions-by-id": [
                    "thread-1": ["approvalsReviewer": "auto_review"]
                ]
            ]
        ]).write(to: stateFile, options: .atomic)
        try FileManager.default.setAttributes(
            [.modificationDate: Date(timeIntervalSince1970: timestamp)],
            ofItemAtPath: stateFile.path
        )

        func deliver(_ event: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: event)
                .deliver(to: repository)
        }
        try deliver([
            "received_at": timestamp,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ])

        let client = CodexAppServerStub(
            listedThreads: [
                .object([
                    "id": .string("thread-1"),
                    "ephemeral": .bool(false),
                    "threadSource": .string("user"),
                    "path": .string(interruptedRollout.path)
                ])
            ],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            approvalRouting: CodexDesktopApprovalRoutingRepository(
                stateFileURL: stateFile
            ),
            desktopProcessIdentifierProvider: { 4_242 }
        )
        defer { Task { await service.disconnect() } }
        #expect(await snapshotWithSessions(from: service).sessions.first?.status == .running)

        // The double Esc. Codex sends no hook for it at all; the abort in the
        // rollout is the whole of the report (ADR 0011).
        try write(
            [
                try turnContext(turnID: "turn-1", at: -0.065),
                try line([
                    "timestamp": stampFormatter.string(
                        from: Date(timeIntervalSince1970: timestamp + 3)
                    ),
                    "type": "event_msg",
                    "payload": [
                        "type": "turn_aborted",
                        "turn_id": "turn-1",
                        "reason": "interrupted"
                    ]
                ])
            ],
            to: interruptedRollout
        )
        let ended = await holds {
            await service.fetchSnapshot().sessions.first?.status == .completed
        }
        #expect(ended, "the interrupted Turn never ended")

        // The user edits the prompt and sends it. Codex opens a new rollout
        // for the same thread, writes this Turn's record into it, and the App
        // Server reports the new path from that instant — while this app is
        // still holding the one it read before the rotation.
        let resumedRollout = root.appendingPathComponent("rollout-2.jsonl")
        try write([try turnContext(turnID: "turn-2", at: 8.9)], to: resumedRollout)
        await client.setThreadPath(resumedRollout.path, forThread: "thread-1")
        // **The new path does not arrive in time for the first projection, and
        // must not have to.** Asking for it is a background read over a
        // transport this app does not control, while the row is composed from
        // whatever is in hand — so the reviewer is looked for in the old file
        // first, and what the fix turns on is that coming up empty there is
        // not an answer about this Turn.
        await client.setThreadReadDelayNanoseconds(300_000_000)
        let readsBeforeTheResumedTurn = await client.completedThreadReadRequestCount()
        try deliver([
            "received_at": timestamp + 9,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-2"
        ])
        let onTheResumedTurn = await holds {
            await service.fetchSnapshot().sessions.first?.turnID == "turn-2"
        }
        #expect(onTheResumedTurn, "the resumed Turn never reached the row")

        // The Turn opening is what asks for the path again, and the reviewer
        // is settled from it long before anything is reviewed: the first call
        // Codex's guardian decided on the reported Turn came 17 seconds after
        // the prompt.
        let pathCaughtUp = await holds {
            _ = await service.fetchSnapshot()
            return await client.completedThreadReadRequestCount()
                > readsBeforeTheResumedTurn
        }
        #expect(pathCaughtUp, "the resumed Turn never had its own path read")
        _ = await service.fetchSnapshot()

        try deliver([
            "received_at": timestamp + 10,
            "hook_event_name": "PreToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-2",
            "tool_name": "Bash",
            "tool_use_id": "exec-1"
        ])
        try deliver([
            "received_at": timestamp + 11,
            "hook_event_name": "PermissionRequest",
            "session_id": "thread-1",
            "turn_id": "turn-2",
            "tool_name": "Bash"
        ])

        // Nobody is being asked anything: Codex's own reviewer is deciding this
        // call, exactly as it decided every call of the Turn before it. Read
        // once and without polling for the answer wanted -- the row has to be
        // right on the refresh that draws the request, not eventually.
        let settled = await service.fetchSnapshot().sessions.first
        #expect(settled?.turnID == "turn-2")
        #expect(settled?.status == .running)
    }

    /// A Turn the user stopped in Codex Desktop, end to end.
    ///
    /// **Codex sends nothing when a Turn is stopped** — no `Stop`, and not even
    /// the `PostToolUse` for the call that was still open. So the row said
    /// *Running* with its timer counting until the user resumed that exact
    /// thread or right-clicked the row away, and on a thread they simply left
    /// alone, for ever: no event would name that `turn_id` again, membership
    /// reconciliation kept the row because the thread is still listed, and this
    /// product has no activity reading like `claude agents --json` to fall back
    /// on. The abort Codex writes into the thread's own rollout is the only
    /// report there is (ADR 0011).
    @Test @MainActor
    func aStoppedCodexTurnCompletesOnTheAbortInItsRollout() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )

        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()

        // Whole seconds, so the abort's stamp survives the round trip through
        // the rollout's millisecond format and `finishedAt` can be compared.
        let timestamp = Date().timeIntervalSince1970.rounded(.down)
        let rollout = root.appendingPathComponent("rollout-thread-1.jsonl")
        let stampFormatter = ISO8601DateFormatter()
        stampFormatter.formatOptions = [
            .withInternetDateTime,
            .withFractionalSeconds
        ]
        func writeRollout(_ objects: [[String: Any]]) throws {
            let lines = try objects.map { object in
                String(
                    decoding: try JSONSerialization.data(withJSONObject: object),
                    as: UTF8.self
                )
            }
            try Data(lines.joined(separator: "\n").appending("\n").utf8)
                .write(to: rollout, options: .atomic)
        }
        // The Turn is running: its own record at the head, and nothing else the
        // reader could mistake for an end.
        try writeRollout([[
            "timestamp": stampFormatter.string(
                from: Date(timeIntervalSince1970: timestamp - 0.065)
            ),
            "type": "turn_context",
            "payload": ["turn_id": "turn-1", "approvals_reviewer": "user"]
        ]])

        func deliver(_ event: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: event)
                .deliver(to: repository)
        }
        try deliver([
            "received_at": timestamp,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "prompt": "Rewrite the panel contour."
        ])
        // The call the user stops in the middle of. Its `PostToolUse` never
        // arrives, which is the whole shape of the failure.
        try deliver([
            "received_at": timestamp + 1,
            "hook_event_name": "PreToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Bash",
            "tool_use_id": "exec-1"
        ])

        let client = CodexAppServerStub(
            listedThreads: [
                codexRootThread(
                    id: "thread-1",
                    name: "Panel contour",
                    path: rollout.path
                )
            ],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        let running = await snapshotWithSessions(from: service)
        #expect(running.sessions.first?.status == .running)

        // The user presses stop. This is everything Codex reports.
        try writeRollout([
            [
                "timestamp": stampFormatter.string(
                    from: Date(timeIntervalSince1970: timestamp - 0.065)
                ),
                "type": "turn_context",
                "payload": ["turn_id": "turn-1", "approvals_reviewer": "user"]
            ],
            [
                "timestamp": stampFormatter.string(
                    from: Date(timeIntervalSince1970: timestamp + 8)
                ),
                "type": "event_msg",
                "payload": [
                    "type": "turn_aborted",
                    "turn_id": "turn-1",
                    "reason": "interrupted",
                    "duration_ms": 7_000
                ]
            ]
        ])

        var stopped = await service.fetchSnapshot()
        let ended = await holds {
            stopped = await service.fetchSnapshot()
            return stopped.sessions.first?.status == .completed
        }
        let methods = await client.requestedMethods()
        await service.disconnect()

        #expect(ended, "a stopped Codex Turn went on reporting Running")
        // The Turn ends where the abort says it did, not where this app noticed.
        #expect(
            stopped.sessions.first?.finishedAt
                == Date(timeIntervalSince1970: timestamp + 8)
        )
        // And it keeps saying something. A stopped Turn has no last word,
        // because the event that carries one is the event Codex never sends.
        #expect(stopped.sessions.first?.preview == "Rewrite the panel contour.")
        // Nothing about this reading asks the App Server for Turn detail.
        #expect(!methods.contains("thread/turns/list"))
        for params in await client.recordedThreadReadParams() {
            #expect(params["includeTurns"]?.boolValue == false)
        }
    }

    /// A stopped Turn's subagents stop counting for it, and only then.
    ///
    /// **The row was still stuck at Running with a subagent in flight**, even
    /// once the abort had ended the Turn: `runningSubagentCount` outlives a
    /// Turn by design, and `MonitorAggregation.effectiveStatus` reads a
    /// Completed row with one as Running. Measured 2026-08-29 on CLI
    /// `0.151.0-alpha.7.1`, that is not a state the user can wait out: the stop
    /// kills the `collaborationwait_agent` the Turn was going to collect the
    /// subagent with -- its `PostToolUse` never arrives -- while the subagent
    /// itself runs on, so the row went on announcing work the stopped Turn
    /// could no longer receive, for as long as the orphan took.
    @Test @MainActor
    func aStoppedTurnsSubagentsStopCountingForIt() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )

        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()

        let timestamp = Date().timeIntervalSince1970.rounded(.down)
        let rollout = root.appendingPathComponent("rollout-thread-1.jsonl")
        let stamp = ISO8601DateFormatter()
        stamp.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        let turnContext: [String: Any] = [
            "timestamp": stamp.string(
                from: Date(timeIntervalSince1970: timestamp - 0.065)
            ),
            "type": "turn_context",
            "payload": ["turn_id": "turn-1", "approvals_reviewer": "user"]
        ]
        func writeRollout(_ objects: [[String: Any]]) throws {
            let lines = try objects.map {
                String(
                    decoding: try JSONSerialization.data(withJSONObject: $0),
                    as: UTF8.self
                )
            }
            try Data(lines.joined(separator: "\n").appending("\n").utf8)
                .write(to: rollout, options: .atomic)
        }
        try writeRollout([turnContext])

        func deliver(_ event: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: event)
                .deliver(to: repository)
        }
        // The measured shape, verbatim: the spawn closes, the wait does not,
        // and the subagent announces itself and starts working.
        try deliver([
            "received_at": timestamp, "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1", "turn_id": "turn-1",
            "prompt": "Spawn one subagent and wait for it."
        ])
        try deliver([
            "received_at": timestamp + 1, "hook_event_name": "PreToolUse",
            "session_id": "thread-1", "turn_id": "turn-1",
            "tool_name": "collaborationspawn_agent", "tool_use_id": "spawn-1"
        ])
        try deliver([
            "received_at": timestamp + 2, "hook_event_name": "PostToolUse",
            "session_id": "thread-1", "turn_id": "turn-1",
            "tool_name": "collaborationspawn_agent", "tool_use_id": "spawn-1"
        ])
        try deliver([
            "received_at": timestamp + 3, "hook_event_name": "PreToolUse",
            "session_id": "thread-1", "turn_id": "turn-1",
            "tool_name": "collaborationwait_agent", "tool_use_id": "wait-1"
        ])
        try deliver([
            "received_at": timestamp + 4, "hook_event_name": "SubagentStart",
            "session_id": "thread-1", "turn_id": "sub-turn", "agent_id": "agent-1"
        ])
        // And it is stopped at a dialogue of its own, which is the state that
        // outranks every other and must not survive the stop either.
        try deliver([
            "received_at": timestamp + 5, "hook_event_name": "PreToolUse",
            "session_id": "thread-1", "turn_id": "sub-turn", "agent_id": "agent-1",
            "tool_name": "Bash", "tool_use_id": "sub-call-1"
        ])
        try deliver([
            "received_at": timestamp + 6, "hook_event_name": "PermissionRequest",
            "session_id": "thread-1", "turn_id": "sub-turn", "agent_id": "agent-1",
            "tool_name": "Bash"
        ])

        let client = CodexAppServerStub(
            listedThreads: [
                codexRootThread(
                    id: "thread-1",
                    name: "Spawner",
                    path: rollout.path
                )
            ],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        let running = await snapshotWithSessions(from: service)
        #expect(running.sessions.first?.runningSubagentCount == 1)
        #expect(running.sessions.first?.subagentsAwaitingApprovalCount == 1)

        // The user presses stop.
        try writeRollout([turnContext, [
            "timestamp": stamp.string(
                from: Date(timeIntervalSince1970: timestamp + 8)
            ),
            "type": "event_msg",
            "payload": [
                "type": "turn_aborted", "turn_id": "turn-1",
                "reason": "interrupted"
            ]
        ]])

        var stopped = await service.fetchSnapshot()
        let ended = await holds {
            stopped = await service.fetchSnapshot()
            return stopped.sessions.first?.status == .completed
        }
        #expect(ended)
        let row = try #require(stopped.sessions.first)
        // The row the user was left with before this rule: Completed underneath
        // and Running to everything that reads "is this thread working".
        #expect(row.runningSubagentCount == 0)
        #expect(row.subagentsAwaitingApprovalCount == 0)
        #expect(MonitorAggregation.effectiveStatus(of: row) == .completed)

        // And the subagent's own stop, whenever it comes, names an agent this
        // thread no longer counts and changes nothing -- the rule the reducer
        // already applies to every agent it never counted.
        try deliver([
            "received_at": timestamp + 40, "hook_event_name": "SubagentStop",
            "session_id": "thread-1", "turn_id": "sub-turn", "agent_id": "agent-1"
        ])
        let after = await service.fetchSnapshot()
        await service.disconnect()
        #expect(after.sessions.first?.status == .completed)
        #expect(after.sessions.first?.runningSubagentCount == 0)
    }

    /// A Turn that ends on its own `Stop` keeps its subagents, which is the
    /// whole reason the count outlives a Turn.
    ///
    /// The counterpart to the test above, and the boundary it must not cross:
    /// only a **stop** orphans them. A `Stop` means the Turn finished and the
    /// thread will collect what its subagents produce, so a row that dropped
    /// the count there would read as finished while the thread works on.
    @Test @MainActor
    func aTurnThatEndsOnItsOwnStopKeepsItsSubagents() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let repository = HookEventRepository(paths: paths)
        let timestamp = Date().timeIntervalSince1970
        func deliver(_ event: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: event)
                .deliver(to: repository)
        }
        try deliver([
            "received_at": timestamp, "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1", "turn_id": "turn-1"
        ])
        try deliver([
            "received_at": timestamp + 1, "hook_event_name": "SubagentStart",
            "session_id": "thread-1", "turn_id": "sub-turn", "agent_id": "agent-1"
        ])
        try deliver([
            "received_at": timestamp + 2, "hook_event_name": "Stop",
            "session_id": "thread-1", "turn_id": "turn-1",
            "last_assistant_message": "Started one and left it running."
        ])
        let afterStop = await repository.drainDeliveredEvents()
        #expect(afterStop.turns.first?.sessionStatus == .completed)
        #expect(afterStop.turns.first?.runningSubagentIDs == ["agent-1"])

        // The identity-free reading may not orphan them either: it says nobody
        // is working on the turn, which is not the same sentence.
        let afterSessionStop = await repository.endTurnsForStoppedSessions(
            ["thread-1": Date(timeIntervalSince1970: timestamp + 3)]
        )
        #expect(afterSessionStop.turns.first?.runningSubagentIDs == ["agent-1"])

        // And an interrupt that does not claim to have orphaned them -- Claude
        // Code's, whose subagents run their own `SubagentStop` on an interrupt
        // -- leaves the count exactly where it was.
        let afterPlainInterrupt = await repository.endInterruptedTurns([
            TurnInterruption(
                threadID: "thread-1",
                turnID: "turn-1",
                endedAt: Date(timeIntervalSince1970: timestamp + 4)
            )
        ])
        #expect(afterPlainInterrupt.turns.first?.runningSubagentIDs == ["agent-1"])
    }

    /// The rollouts this service watches, and for exactly how long.
    ///
    /// The edge under the reading above. A quiet monitor watches nothing: only
    /// a Turn that is still going has an abort to wait for, and the moment one
    /// ends its rollout is dropped — otherwise every thread this app had ever
    /// seen would go on waking a refresh for each record appended to it.
    @Test @MainActor
    func onlyTheRolloutsOfRunningTurnsAreWatched() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )

        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()

        let rollout = root.appendingPathComponent("rollout-thread-1.jsonl")
        try Data("\n".utf8).write(to: rollout, options: .atomic)

        let timestamp = Date().timeIntervalSince1970
        func deliver(_ event: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: event)
                .deliver(to: repository)
        }
        try deliver([
            "received_at": timestamp,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ])

        let client = CodexAppServerStub(
            listedThreads: [
                codexRootThread(id: "thread-1", name: "Watched", path: rollout.path)
            ],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        let running = await snapshotWithSessions(from: service)
        #expect(running.sessions.first?.status == .running)
        #expect(await service.rolloutWatcher.watchedPaths == [rollout])

        try deliver([
            "received_at": timestamp + 5,
            "hook_event_name": "Stop",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "last_assistant_message": "Done."
        ])
        var finished = await service.fetchSnapshot()
        let ended = await holds {
            finished = await service.fetchSnapshot()
            return finished.sessions.first?.status == .completed
        }
        let watchedAfterStop = await service.rolloutWatcher.watchedPaths
        await service.disconnect()
        let watchedAfterDisconnect = await service.rolloutWatcher.watchedPaths

        #expect(ended)
        #expect(watchedAfterStop.isEmpty)
        #expect(watchedAfterDisconnect.isEmpty)
    }

    @Test @MainActor
    func liveStopCompletesWithoutAThreadDetailRead() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()
        let event = try JSONSerialization.data(withJSONObject: [
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "Stop",
            "session_id": "thread-stop",
            "turn_id": "turn-stop"
        ])
        event.deliver(to: repository)

        let client = CodexAppServerStub(
            listedThreads: [.object([
                "id": .string("thread-stop"),
                "ephemeral": .bool(false),
                "threadSource": .string("user"),
                "name": .string("Completed turn"),
                "updatedAt": .number(Date().timeIntervalSince1970)
            ])],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        let first = await snapshotWithSessions(from: service)
        await waitForThreadListRequests(
            client,
            atLeast: 1,
            completed: true
        )
        let second = await service.fetchSnapshot()
        let third = await service.fetchSnapshot()
        let methods = await client.requestedMethods()
        await service.disconnect()

        #expect(first.availability == .ready)
        #expect(first.sessions.first?.status == .completed)
        #expect(second.availability == .ready)
        #expect(second.sessions.first?.status == .completed)
        #expect(third.availability == .ready)
        #expect(third.sessions.first?.status == .completed)
        // The real rule is not "never call thread/read" — it is "never read Turn
        // detail". Metadata reads are allowed; rollout history is not.
        #expect(!methods.contains("thread/items/list"))
        #expect(!methods.contains("thread/turns/list"))
        for params in await client.recordedThreadReadParams() {
            #expect(params["includeTurns"]?.boolValue == false)
        }
    }

    @Test @MainActor
    func liveStopTransitionsDirectlyFromRunningToCompleted() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()
        let prompt = try JSONSerialization.data(withJSONObject: [
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-terminal",
            "turn_id": "turn-terminal"
        ])
        prompt.deliver(to: repository)

        let listedThread = JSONValue.object([
            "id": .string("thread-terminal"),
            "ephemeral": .bool(false),
            "threadSource": .string("user"),
            "updatedAt": .number(Date().timeIntervalSince1970),
            "status": .object([
                "type": .string("active"),
                "activeFlags": .array([])
            ]),
            "turns": .array([
                .object([
                    "id": .string("turn-terminal"),
                    "status": .string("inProgress")
                ])
            ])
        ])
        let client = CodexAppServerStub(
            listedThreads: [listedThread],
            loadedListResults: []
        )
        let unreadState = DesktopUnreadStateStub(
            unreadThreadIDs: ["thread-terminal"]
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            unreadState: unreadState,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        let initial = await snapshotWithSessions(from: service)
        #expect(initial.sessions.first?.status == .running)
        await waitForThreadListRequests(
            client,
            atLeast: 1,
            completed: true
        )

        let stop = try JSONSerialization.data(withJSONObject: [
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "Stop",
            "session_id": "thread-terminal",
            "turn_id": "turn-terminal"
        ])
        stop.deliver(to: repository)

        var observedStatuses: [SessionStatus] = []
        for _ in 0..<100 {
            let snapshot = await service.fetchSnapshot()
            if let status = snapshot.sessions.first?.status {
                observedStatuses.append(status)
            }
            if observedStatuses.last == .completed {
                break
            }
            try await Task.sleep(nanoseconds: 10_000_000)
        }
        await unreadState.setUnread([])
        let afterRead = await service.fetchSnapshot()
        await service.disconnect()

        #expect(observedStatuses.first == .completed)
        #expect(observedStatuses.last == .completed)
        #expect(afterRead.sessions.isEmpty)
        // Terminal status comes from the Hook reducer alone. The live-progress
        // read exists now and this stub refuses it, which is the point: the
        // turn still reached Completed with nothing fetched about it, and no
        // read was ever issued for a turn that had already ended.
        for params in await client.recordedTurnItemsParams() {
            #expect(params["turnId"]?.stringValue == "turn-terminal")
        }
        // Exactly one, not "at most one". The hedge was hiding a real duplicate
        // -- the refusal is recorded when the answer arrives, so every refresh
        // that ran while the read was in flight asked again, and this failed on
        // a loaded machine and nowhere else. See
        // `aTurnsProgressIsReadOnceWhileTheReadIsStillInFlight`.
        #expect(await client.requestCount(method: "thread/items/list") == 1)
        for params in await client.recordedThreadReadParams() {
            #expect(params["includeTurns"]?.boolValue == false)
        }
    }

    /// One question about one moment of one turn is asked once.
    ///
    /// The progress read is issued from inside a refresh and answered after an
    /// actor hop, and every `fetchSnapshot` that lands in that hop is
    /// re-entrant with it. Until the answer came back there was nothing in the
    /// service saying the question had been asked -- the held record is written
    /// on the response -- so each of those refreshes saw an unread stamp and
    /// queued the identical read again. On a quiet machine the hop is too short
    /// for anything to fit inside it, which is why this only ever showed up as
    /// `liveStopTransitionsDirectlyFromRunningToCompleted` failing on a loaded
    /// one. Here the answer is held open on purpose, so the window is the test's
    /// to choose rather than the machine's.
    @Test @MainActor
    func aTurnsProgressIsReadOnceWhileTheReadIsStillInFlight() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()

        deliverHook([
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-inflight",
            "turn_id": "turn-inflight",
            "prompt": "Pin the flake."
        ], to: repository)

        let listedThread = JSONValue.object([
            "id": .string("thread-inflight"),
            "ephemeral": .bool(false),
            "threadSource": .string("user"),
            "updatedAt": .number(Date().timeIntervalSince1970),
            "status": .object([
                "type": .string("active"),
                "activeFlags": .array([])
            ])
        ])
        let client = CodexAppServerStub(
            listedThreads: [listedThread],
            loadedListResults: [],
            supportsTurnItems: true,
            turnItemsByTurnID: [
                "turn-inflight": [
                    agentMessageEntry(turn: "turn-inflight", text: "Reading the reducer.")
                ]
            ]
        )
        // Long enough that the refreshes below all land inside the one read,
        // which is the whole point: they are the loaded machine.
        await client.setTurnItemsDelayNanoseconds(300_000_000)
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )
        defer { Task { await service.disconnect() } }

        _ = await snapshotWithSessions(from: service)
        let issued = await holds {
            await client.requestCount(method: "thread/items/list") >= 1
        }
        #expect(issued, "the running turn's progress was never read")

        // Every one of these is re-entrant with the read still in flight, and
        // none of them has anything new to ask about: the turn has produced no
        // event since the read was issued.
        for _ in 0..<10 {
            _ = await service.fetchSnapshot()
            try await Task.sleep(nanoseconds: 10_000_000)
        }
        #expect(await client.requestCount(method: "thread/items/list") == 1)

        // And once the answer is in, the same unchanged stamp is not re-read
        // either -- the held record covers it from here.
        let said = await holds {
            await service.fetchSnapshot().sessions.first?.preview
                == "Reading the reducer."
        }
        #expect(said, "the row never showed what the turn was saying")
        _ = await service.fetchSnapshot()
        #expect(await client.requestCount(method: "thread/items/list") == 1)
    }

    /// And the same for the metadata read beside it.
    ///
    /// `thread/read` writes its ``ThreadRecord`` on the answer, and the
    /// staleness check that decides whether to ask is against that record -- so
    /// a refresh re-entrant with the read found no record, called the thread
    /// stale, and queued it again. The queued question is dispatched the moment
    /// the read in flight ends, by which point the answer it was asking for is
    /// already in hand and good for the next ten seconds.
    ///
    /// The membership read is held open here as well, because that is the one
    /// thing that hid this: `thread/list` writes every listed thread's record
    /// in bulk, so on a fast list the record appears part-way through the
    /// single-thread read and the re-queue never happens. A slow list -- the
    /// case the paginated read exists to be -- leaves the window open.
    @Test @MainActor
    func aThreadsMetadataIsReadOnceWhileTheReadIsStillInFlight() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()

        deliverHook([
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-metadata",
            "turn_id": "turn-metadata",
            "prompt": "Close the other one."
        ], to: repository)

        let client = CodexAppServerStub(
            listedThreads: [
                codexRootThread(
                    id: "thread-metadata",
                    name: "Closing the metadata hole"
                )
            ],
            loadedListResults: [],
            threadListDelayNanoseconds: 600_000_000
        )
        await client.setThreadReadDelayNanoseconds(300_000_000)
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )
        defer { Task { await service.disconnect() } }

        _ = await snapshotWithSessions(from: service)
        let issued = await holds {
            await client.requestCount(method: "thread/read") >= 1
        }
        #expect(issued, "the hook's thread was never read")

        // Re-entrant with the read still out, asking about a thread whose
        // record the answer in flight is going to write.
        for _ in 0..<10 {
            _ = await service.fetchSnapshot()
            try await Task.sleep(nanoseconds: 10_000_000)
        }

        // Counted after the answer lands, not during the read: a question
        // queued mid-flight is not dispatched until the run in flight ends, so
        // counting while it is still out would miss the duplicate entirely.
        let answered = await holds {
            await client.completedThreadReadRequestCount() >= 1
        }
        #expect(answered, "the metadata read never answered")
        for _ in 0..<5 {
            _ = await service.fetchSnapshot()
            try await Task.sleep(nanoseconds: 10_000_000)
        }
        #expect(await client.requestCount(method: "thread/read") == 1)
        #expect(
            await service.fetchSnapshot().sessions.first?.title
                == "Closing the metadata hole"
        )
    }

    /// A build without `thread/read` is probed once, not once per thread.
    ///
    /// The answer "this build has no such method" arrives mid-run, and a
    /// thread queued behind the probe went out anyway: the capability was
    /// checked where reads are queued and where a run is started, but not at
    /// the moment the run dispatches the next batch -- which is the only place
    /// it can be checked *after* the refusal has been recorded.
    @Test @MainActor
    func aBuildWithoutThreadReadIsProbedOnceNotOncePerThread() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()

        deliverHook([
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-probe",
            "turn_id": "turn-probe"
        ], to: repository)

        let client = CodexAppServerStub(
            listedThreads: [
                codexRootThread(id: "thread-probe", name: "Probed"),
                codexRootThread(id: "thread-behind", name: "Queued behind it")
            ],
            loadedListResults: [],
            threadListDelayNanoseconds: 600_000_000,
            supportsThreadRead: false
        )
        await client.setThreadReadDelayNanoseconds(300_000_000)
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )
        defer { Task { await service.disconnect() } }

        _ = await snapshotWithSessions(from: service)
        let probed = await holds {
            await client.requestCount(method: "thread/read") >= 1
        }
        #expect(probed, "the build was never probed for thread/read")

        // A second thread starts while the probe is still out, so it is queued
        // by a refresh that has not been told yet that there is no method.
        deliverHook([
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-behind",
            "turn_id": "turn-behind"
        ], to: repository)
        for _ in 0..<15 {
            _ = await service.fetchSnapshot()
            try await Task.sleep(nanoseconds: 10_000_000)
        }

        #expect(await client.requestCount(method: "thread/read") == 1)
        // And the rows still get their titles, from the list that has them.
        let titled = await holds {
            await Set(service.fetchSnapshot().sessions.map(\.title))
                == ["Probed", "Queued behind it"]
        }
        #expect(titled, "the fallback stopped supplying titles")
    }

    /// The row's second line follows the turn, not the prompt that started it.
    ///
    /// No Codex hook carries assistant text before the turn ends -- checked
    /// against the schemas the CLI ships, `last_assistant_message` is on
    /// `stop.command.input` and `subagent-stop.command.input` and nowhere else
    /// -- so a Running row used to show the user's own prompt for the whole
    /// turn, which is the one thing about the turn that cannot change. It is
    /// read from the App Server against the turn the reducer owns instead.
    @Test @MainActor
    func aRunningCodexRowSaysWhatTheTurnIsSayingNow() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()

        deliverHook([
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-live",
            "turn_id": "turn-live",
            "prompt": "Fix the flaky test."
        ], to: repository)

        let listedThread = JSONValue.object([
            "id": .string("thread-live"),
            "ephemeral": .bool(false),
            "threadSource": .string("user"),
            "updatedAt": .number(Date().timeIntervalSince1970),
            "status": .object([
                "type": .string("active"),
                "activeFlags": .array([])
            ])
        ])
        let client = CodexAppServerStub(
            listedThreads: [listedThread],
            loadedListResults: [],
            supportsTurnItems: true,
            turnItemsByTurnID: [
                "turn-live": [
                    agentMessageEntry(turn: "turn-live", text: "Verified. The problem is in the reducer.")
                ]
            ]
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )
        defer { Task { await service.disconnect() } }

        _ = await service.fetchSnapshot()
        let saidFirst = await holds {
            await service.fetchSnapshot().sessions.first?.preview
                == "Verified. The problem is in the reducer."
        }
        #expect(saidFirst, "the row kept showing the prompt instead of the turn")

        // The step it moves on to. A tool call opening is what tells the app
        // there is something new to ask for; without it the row would sit on
        // the sentence above until the turn's status changed.
        await client.appendTurnItem(
            commandExecutionEntry(turn: "turn-live"),
            toTurn: "turn-live"
        )
        await client.appendTurnItem(
            agentMessageEntry(turn: "turn-live", text: "Working on the fix."),
            toTurn: "turn-live"
        )
        deliverHook([
            "hook_event_name": "PreToolUse",
            "session_id": "thread-live",
            "turn_id": "turn-live",
            "tool_name": "shell",
            "tool_use_id": "shell-1"
        ], to: repository)

        let movedOn = await holds {
            await service.fetchSnapshot().sessions.first?.preview
                == "Working on the fix."
        }
        #expect(movedOn, "the row reported the step before the one being worked on")

        // Scoped, newest-first, and bounded. All three matter: unscoped it
        // would answer with the previous turn's closing words, ascending it
        // would answer with the turn's opening ones, and unbounded it would
        // pull every command output the turn has produced.
        let requests = await client.recordedTurnItemsParams()
        #expect(!requests.isEmpty)
        for params in requests {
            #expect(params["threadId"]?.stringValue == "thread-live")
            #expect(params["turnId"]?.stringValue == "turn-live")
            #expect(params["sortDirection"]?.stringValue == "desc")
            #expect((params["limit"]?.intValue ?? 0) > 0)
            #expect((params["limit"]?.intValue ?? .max) <= 8)
        }
    }

    /// A finished turn keeps the answer its own `Stop` carried.
    ///
    /// The two sources say different things on purpose: the live read reports
    /// whatever the turn had most recently printed, and `last_assistant_message`
    /// is the turn's actual closing answer. A completed row shows the answer.
    @Test @MainActor
    func aFinishedCodexTurnShowsItsOwnClosingAnswer() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()

        deliverHook([
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-done",
            "turn_id": "turn-done",
            "prompt": "Fix the flaky test."
        ], to: repository)

        let listedThread = JSONValue.object([
            "id": .string("thread-done"),
            "ephemeral": .bool(false),
            "threadSource": .string("user"),
            "updatedAt": .number(Date().timeIntervalSince1970),
            "status": .object([
                "type": .string("active"),
                "activeFlags": .array([])
            ])
        ])
        let client = CodexAppServerStub(
            listedThreads: [listedThread],
            loadedListResults: [],
            supportsTurnItems: true,
            turnItemsByTurnID: [
                "turn-done": [
                    agentMessageEntry(turn: "turn-done", text: "Working on the fix.")
                ]
            ]
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )
        defer { Task { await service.disconnect() } }

        _ = await service.fetchSnapshot()
        #expect(
            await holds {
                await service.fetchSnapshot().sessions.first?.preview
                    == "Working on the fix."
            }
        )

        deliverHook([
            "hook_event_name": "Stop",
            "session_id": "thread-done",
            "turn_id": "turn-done",
            "last_assistant_message": "Fixed: the reducer dropped the second event."
        ], to: repository)

        let closed = await holds {
            let row = await service.fetchSnapshot().sessions.first
            return row?.status == .completed
                && row?.preview == "Fixed: the reducer dropped the second event."
        }
        #expect(closed)
    }

    /// A new turn never inherits the last one's words.
    ///
    /// The read is scoped to the turn the reducer owns rather than to the
    /// thread. Unscoped, a turn that has not said anything yet answers with the
    /// previous turn's closing words -- a row confidently describing work that
    /// is already over.
    @Test @MainActor
    func aFreshCodexTurnDoesNotInheritTheLastOnesWords() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()

        // The thread's own rollout, which is what gives the second turn its
        // row: a Codex prompt for a turn the thread is not on is held until
        // this record names it (``HookTurnState/heldTurnStart``), and Codex
        // writes the record before the hook.
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )
        let rollout = root.appendingPathComponent("rollout-thread-two.jsonl")
        func writeRollout(naming turnIDs: [String]) throws {
            let lines = try turnIDs.map { turnID in
                String(
                    decoding: try JSONSerialization.data(withJSONObject: [
                        "timestamp": "2026-09-08T00:00:00.000Z",
                        "type": "turn_context",
                        "payload": ["turn_id": turnID]
                    ]),
                    as: UTF8.self
                )
            }
            try Data(lines.joined(separator: "\n").appending("\n").utf8)
                .write(to: rollout, options: .atomic)
        }
        try writeRollout(naming: ["turn-first"])

        let listedThread = JSONValue.object([
            "id": .string("thread-two"),
            "ephemeral": .bool(false),
            "threadSource": .string("user"),
            "path": .string(rollout.path),
            "updatedAt": .number(Date().timeIntervalSince1970),
            "status": .object([
                "type": .string("active"),
                "activeFlags": .array([])
            ])
        ])
        let client = CodexAppServerStub(
            listedThreads: [listedThread],
            loadedListResults: [],
            supportsTurnItems: true,
            turnItemsByTurnID: [
                "turn-first": [
                    agentMessageEntry(turn: "turn-first", text: "All done with the first one.")
                ],
                "turn-second": []
            ]
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )
        defer { Task { await service.disconnect() } }

        let moment = Date().timeIntervalSince1970
        deliverHook([
            "received_at": moment,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-two",
            "turn_id": "turn-first",
            "prompt": "The first question."
        ], to: repository)
        _ = await service.fetchSnapshot()
        // The first turn also asked something without waiting for the answer,
        // which outranks that turn's own step while it runs and must not
        // outrank anything once the next turn owns the row.
        deliverHook([
            "received_at": moment + 0.5,
            "hook_event_name": "PreToolUse",
            "session_id": "thread-two",
            "turn_id": "turn-first",
            "tool_name": "request_user_input_async",
            "tool_use_id": "call-async-1",
            "tool_input": ["questions": [["title": "Which of the two shall I use?"]]]
        ], to: repository)
        _ = await service.fetchSnapshot()
        deliverHook([
            "received_at": moment + 1,
            "hook_event_name": "Stop",
            "session_id": "thread-two",
            "turn_id": "turn-first",
            "last_assistant_message": "All done with the first one."
        ], to: repository)
        _ = await service.fetchSnapshot()

        // The record first, then the hook, in Codex's own order.
        try writeRollout(naming: ["turn-first", "turn-second"])
        deliverHook([
            "received_at": moment + 2,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-two",
            "turn_id": "turn-second",
            "prompt": "The second question."
        ], to: repository)

        // The new turn has said nothing yet, so the row falls back to the
        // prompt it started from -- never to the answer above it, and never to
        // the question the turn above it asked.
        let started = await holds {
            await service.fetchSnapshot().sessions.first?.turnID == "turn-second"
        }
        #expect(started)
        for _ in 0..<5 {
            let row = await service.fetchSnapshot().sessions.first
            #expect(row?.preview == "The second question.")
            try await Task.sleep(nanoseconds: 20_000_000)
        }
    }

    /// One thread refusing the read does not take it away from the others.
    ///
    /// `thread/items/list` answers `-32601` for a thread whose `historyMode` is
    /// `legacy` while `paginated` threads on the same server answer normally
    /// (measured 2026-08-25, CLI `0.149.0-alpha.4.3`). Held server-wide, the
    /// one legacy thread a user still has open would have taken the live
    /// progress off every other row in the panel.
    @Test @MainActor
    func oneThreadRefusingTheProgressReadDoesNotSilenceTheOthers() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()

        for (thread, turn, prompt) in [
            ("thread-legacy", "turn-legacy", "The legacy question."),
            ("thread-modern", "turn-modern", "The modern question.")
        ] {
            deliverHook([
                "hook_event_name": "UserPromptSubmit",
                "session_id": thread,
                "turn_id": turn,
                "prompt": prompt
            ], to: repository)
        }

        let listedThreads = ["thread-legacy", "thread-modern"].map { id in
            JSONValue.object([
                "id": .string(id),
                "ephemeral": .bool(false),
                "threadSource": .string("user"),
                "updatedAt": .number(Date().timeIntervalSince1970),
                "status": .object([
                    "type": .string("active"),
                    "activeFlags": .array([])
                ])
            ])
        }
        let client = CodexAppServerStub(
            listedThreads: listedThreads,
            loadedListResults: [],
            supportsTurnItems: true,
            turnItemsByTurnID: [
                "turn-legacy": [
                    agentMessageEntry(turn: "turn-legacy", text: "Never readable.")
                ],
                "turn-modern": [
                    agentMessageEntry(turn: "turn-modern", text: "Working on the fix.")
                ]
            ],
            legacyHistoryThreadIDs: ["thread-legacy"]
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )
        defer { Task { await service.disconnect() } }

        _ = await service.fetchSnapshot()
        let split = await holds {
            let rows = await service.fetchSnapshot().sessions
            let legacy = rows.first { $0.threadID == "thread-legacy" }
            let modern = rows.first { $0.threadID == "thread-modern" }
            return legacy?.preview == "The legacy question."
                && modern?.preview == "Working on the fix."
        }
        #expect(split, "the refusing thread took the other row's line with it")

        // And the refusing thread is not asked again, however much it does.
        //
        // Settled first: a refresh that runs while the first read is still in
        // flight legitimately queues a second one, because nothing has been
        // recorded for the thread yet. What is pinned here is that the count
        // stops growing, not what it stopped at.
        func legacyRequestCount() async -> Int {
            await client.recordedTurnItemsParams()
                .filter { $0["threadId"]?.stringValue == "thread-legacy" }
                .count
        }
        var askedBefore = await legacyRequestCount()
        let settled = await holds {
            try? await Task.sleep(nanoseconds: 30_000_000)
            _ = await service.fetchSnapshot()
            let now = await legacyRequestCount()
            defer { askedBefore = now }
            return now == askedBefore && now >= 1
        }
        #expect(settled, "the refusing thread never stopped being asked")
        for index in 0..<4 {
            deliverHook([
                "hook_event_name": "PreToolUse",
                "session_id": "thread-legacy",
                "turn_id": "turn-legacy",
                "tool_name": "shell",
                "tool_use_id": "shell-\(index)"
            ], to: repository)
            _ = await service.fetchSnapshot()
        }
        let askedAfter = await legacyRequestCount()
        #expect(askedBefore == askedAfter)
    }

    /// A Codex that does not have the read is asked once per thread, then left
    /// alone.
    ///
    /// `thread/items/list` is experimental, so a build without it is an
    /// expected answer rather than a fault: the rows fall back to the prompt
    /// preview, which is exactly what they showed before this read existed.
    /// It arrives as the same `-32601` a legacy thread answers with, and is
    /// deliberately not told apart from it by message text -- so the cost of a
    /// Codex that has no such method is one refused call per thread rather than
    /// one per run.
    @Test @MainActor
    func aCodexWithoutTheItemsReadKeepsShowingThePrompt() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()

        deliverHook([
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-old",
            "turn_id": "turn-old",
            "prompt": "Fix the flaky test."
        ], to: repository)

        let listedThread = JSONValue.object([
            "id": .string("thread-old"),
            "ephemeral": .bool(false),
            "threadSource": .string("user"),
            "updatedAt": .number(Date().timeIntervalSince1970),
            "status": .object([
                "type": .string("active"),
                "activeFlags": .array([])
            ])
        ])
        let client = CodexAppServerStub(
            listedThreads: [listedThread],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )
        defer { Task { await service.disconnect() } }

        _ = await service.fetchSnapshot()
        #expect(
            await holds {
                await client.requestCount(method: "thread/items/list") >= 1
            }
        )
        for index in 0..<6 {
            deliverHook([
                "hook_event_name": "PreToolUse",
                "session_id": "thread-old",
                "turn_id": "turn-old",
                "tool_name": "shell",
                "tool_use_id": "shell-\(index)"
            ], to: repository)
            let row = await service.fetchSnapshot().sessions.first
            #expect(row?.preview == "Fix the flaky test.")
        }
        // Refused once, then never asked again for the rest of the run.
        #expect(await client.requestCount(method: "thread/items/list") == 1)
    }

    @Test
    func newestAgentMessageReadsThePageTheServerActuallyReturns() {
        // Newest first, so the first match wins and everything else is skipped
        // rather than described -- the row reports what the agent said it is
        // doing, and a tool name is not a sentence.
        let page = JSONValue.object([
            "data": .array([
                commandExecutionEntry(turn: "t"),
                .object([
                    "turnId": .string("t"),
                    "item": .object([
                        "type": .string("reasoning"),
                        "id": .string("rs-1"),
                        "summary": .array([])
                    ])
                ]),
                agentMessageEntry(turn: "t", text: "  Working   on\n the fix.  "),
                agentMessageEntry(turn: "t", text: "An older thing it said.")
            ])
        ])
        #expect(
            CodexSnapshotParser.newestAgentMessage(in: page) == "Working on the fix."
        )
        #expect(CodexSnapshotParser.newestAgentMessage(in: .object(["data": .array([])])) == nil)
        #expect(CodexSnapshotParser.newestAgentMessage(in: .object([:])) == nil)
        // An empty message is not something the row can show.
        #expect(
            CodexSnapshotParser.newestAgentMessage(
                in: .object(["data": .array([agentMessageEntry(turn: "t", text: "   ")])])
            ) == nil
        )
    }

