    /// The walk is bounded, so a reused pid cannot turn it into a loop.
    @Test @MainActor
    func theHostWalkIsBounded() async {
        let resolver = ProcessAncestryHostResolver(
            parent: { $0 == 2 ? 3 : 2 },
            executablePath: { _ in "/bin/sh" },
            bundle: { _ in nil }
        )
        #expect(await resolver.host(ofProcess: 7) == nil)
    }

    /// A helper is attributed to the application that ships it.
    @Test @MainActor
    func theEnclosingBundleIsTheOutermostOne() {
        let enclosing = ProcessAncestryHostResolver.enclosingApplicationBundlePath
        #expect(
            enclosing("/Applications/Claude.app/Contents/Helpers/disclaimer")
                == "/Applications/Claude.app"
        )
        #expect(
            enclosing(
                "/Applications/Claude.app/Contents/Frameworks/Claude Helper.app"
                    + "/Contents/MacOS/Claude Helper"
            ) == "/Applications/Claude.app"
        )
        #expect(
            enclosing("/Applications/iTerm.app/Contents/MacOS/iTermServer-3.5.14")
                == "/Applications/iTerm.app"
        )
        #expect(enclosing("/Users/someone/.local/share/claude/versions/2.1.237") == nil)
        #expect(enclosing("/bin/zsh") == nil)
        // A directory that merely ends in the four characters is not a bundle.
        #expect(enclosing("/tmp/.app/thing") == nil)
    }

    /// Only the hosts that publish a terminal device get a script.
    ///
    /// Everything else takes the documented degrade rather than a script that
    /// would have to match on a title or a working directory to find anything.
    @Test @MainActor
    func onlyHostsThatPublishATerminalDeviceAreScripted() {
        let script = AppleEventsTerminalTabFocuser.script
        #expect(script("com.apple.Terminal", "/dev/ttys001")?.contains("tty of theTab") == true)
        #expect(
            script("com.googlecode.iterm2", "/dev/ttys001")?.contains("tty of theSession")
                == true
        )
        for unscripted in [
            "com.mitchellh.ghostty",
            "net.kovidgoyal.kitty",
            "com.github.wez.wezterm",
            "org.alacritty",
            "com.microsoft.VSCode"
        ] {
            #expect(script(unscripted, "/dev/ttys001") == nil)
        }
        // The device reaches the script through two layers of C, so it is
        // escaped rather than trusted to keep its shape.
        #expect(
            AppleEventsTerminalTabFocuser.appleScriptLiteral(#"/dev/"od\d"#)
                == #""/dev/\"od\\d""#
        )
    }

    /// The first click asks for Automation once and does not wait for the answer.
    ///
    /// Letting the system prompt come up inside the click would freeze
    /// navigation for as long as it sits unanswered -- the store allows one
    /// navigation in flight -- so consent is requested behind the click and the
    /// click degrades to raising the terminal. A burst of clicks asks once.
    @Test @MainActor
    func anUndecidedHostIsAskedOnceAndTheClickDoesNotWait() async {
        let asked = CountingBox()
        let ran = CountingBox()
        let focuser = AppleEventsTerminalTabFocuser(
            timeout: 60,
            permission: { _ in .undecided },
            requestConsent: { _ in asked.increment() },
            execute: { _ in
                ran.increment()
                return true
            }
        )
        let terminal = HostApplication(
            bundleIdentifier: "com.apple.Terminal",
            displayName: "Terminal",
            processIdentifier: 877
        )

        for _ in 0 ..< 3 {
            #expect(
                await focuser.focusTab(withTerminalDevice: "/dev/ttys001", in: terminal)
                    == .unavailable
            )
        }

        #expect(asked.value == 1)
        #expect(ran.value == 0)
    }

    /// A refusal never errors, never runs a script and is never asked again.
    ///
    /// Once TCC holds a denial the permission call answers it without
    /// prompting, so the only thing left to prove is that this app does not
    /// turn that answer into an error, a second prompt or a failed click.
    @Test @MainActor
    func arefusedHostDegradesSilentlyAndIsNeverAskedAgain() async {
        let asked = CountingBox()
        let ran = CountingBox()
        let focuser = AppleEventsTerminalTabFocuser(
            timeout: 60,
            permission: { _ in .refused },
            requestConsent: { _ in asked.increment() },
            execute: { _ in
                ran.increment()
                return true
            }
        )
        let terminal = HostApplication(
            bundleIdentifier: "com.apple.Terminal",
            displayName: "Terminal",
            processIdentifier: 877
        )

        for _ in 0 ..< 3 {
            #expect(
                await focuser.focusTab(withTerminalDevice: "/dev/ttys001", in: terminal)
                    == .unavailable
            )
        }
        #expect(asked.value == 0)
        #expect(ran.value == 0)

        // And the row still opens: the click raises the terminal and says so.
        let activator = HostActivatorSpy()
        let navigator = ClaudeCodeNavigator(
            sessions: ClaudeCodeSessionLocatorStub(["cc": 60_817]),
            hosts: Self.terminalTree(
                bundleIdentifier: "com.apple.Terminal",
                displayName: "Terminal"
            ),
            activator: activator,
            tabs: focuser,
            controllingTerminalPath: { _ in "/dev/ttys001" }
        )
        let outcome = try? await navigator.open(
            makeSession(agent: .claudeCode, threadID: "cc")
        )
        #expect(outcome == .raisedApplication(host: "Terminal"))
    }

    /// A terminal that never answers does not hold navigation open.
    ///
    /// The store allows one navigation at a time, so a script that never
    /// returns would not merely lose this click -- it would disable the row
    /// click for the rest of the run.
    ///
    /// **The deadline is fired by hand rather than waited for.** Timing the
    /// click instead asserts a proxy no loaded machine has to respect: the
    /// wall-clock form of this test -- a 0.05 s deadline, a real 5 s sleep and
    /// a 2 s budget -- failed twice in ten suite runs on 2026-08-30 at 2.7 s
    /// and 2.9 s, with builds running alongside and the deadline itself
    /// working correctly every time. What the invariant actually is, is an
    /// ordering: the click answers **while the script is still inside
    /// `execute`**, which is released only after the answer is in hand. So a
    /// 60-second deadline is scheduled and then dropped on the spot, and this
    /// test consults no clock at all.
    @Test @MainActor
    func aWedgedTerminalGivesTheClickBack() async {
        let wedged = DispatchSemaphore(value: 0)
        let scheduled = IntervalBox()
        let focuser = AppleEventsTerminalTabFocuser(
            timeout: 60,
            permission: { _ in .granted },
            requestConsent: { _ in },
            execute: { _ in
                // Wedged until the assertions below have run. The bound is a
                // valve rather than a budget: it is there so a focuser that
                // stopped racing its deadline fails this test instead of
                // hanging the suite, and a passing run never approaches it.
                _ = wedged.wait(timeout: .now() + 30)
                return true
            },
            scheduleDeadline: { interval, fire in
                scheduled.record(interval)
                fire()
            }
        )

        let answer = await focuser.focusTab(
            withTerminalDevice: "/dev/ttys001",
            in: HostApplication(
                bundleIdentifier: "com.apple.Terminal",
                displayName: "Terminal",
                processIdentifier: 877
            )
        )

        #expect(answer == .unavailable)
        // Against the deadline the focuser was built with, not a shorter one
        // the test could have got away with by waiting for it.
        #expect(scheduled.value == 60)
        wedged.signal()
    }

    // MARK: - Raising a host that is on another desktop

    /// A host whose windows are all on another desktop is hidden before it is
    /// activated, and that order is half the fix.
    ///
    /// Activation on its own hands the application the menu bar and leaves
    /// every window where it was (measured 2026-08-22 for `activate()`,
    /// `activate(options: .activateAllWindows)`, an `activate` Apple Event and
    /// `NSWorkspace.openApplication`, with the Mission Control preference both
    /// unset and on). Coming back from hidden is what makes the application
    /// order its own windows front, and the window server follows the front
    /// window to its Space. The other half is ``ForegroundClaiming``: without
    /// the foreground the same two calls are simply declined.
    @Test @MainActor
    func aHostOnAnotherDesktopIsHiddenSoTheClickChangesDesktop() async {
        let application = FakeRaisableApplication()
        let foreground = ForegroundSpy()
        // Not here, not here, and then the desktop has changed.
        let occupancy = OccupancyStub(answering: [false, false, true])
        let activator = AppKitHostApplicationActivator(
            occupancy: occupancy,
            applications: { _ in [application] },
            foreground: foreground,
            settle: {}
        )

        let raised = await activator.activate(Self.ghosttyHost())

        #expect(raised)
        #expect(application.calls == [.hide, .activate])
        #expect(foreground.calls == [.claim])
    }

    /// The foreground is taken before the host is touched, and given back only
    /// when the raise failed.
    ///
    /// The order is the point: an activation sent while this app is still on
    /// its way to the foreground is declined exactly like one sent from the
    /// background, so `claim` has to be answered before `hide` goes out.
    @Test @MainActor
    func theForegroundIsTakenBeforeTheHostIsTouched() async {
        let foreground = ForegroundSpy(claimsImmediately: false)
        let application = FakeRaisableApplication()
        let activator = AppKitHostApplicationActivator(
            occupancy: OccupancyStub(answering: [false, false, true]),
            applications: { _ in [application] },
            foreground: foreground,
            // The foreground arrives on the first pause and not before, so
            // what the host has been asked by then is the whole assertion.
            settle: { await MainActor.run { foreground.arrive(hostCalls: application.calls) } }
        )

        let raised = await activator.activate(Self.ghosttyHost())

        #expect(raised)
        #expect(foreground.hostCallsAtArrival == [])
        #expect(application.calls == [.hide, .activate])
    }

    /// A host that already has a window in front of the user is never hidden,
    /// and the foreground is never taken for it.
    ///
    /// There is no desktop to change, so hiding it would buy nothing and cost
    /// the user a blink of every window that application has open — and this
    /// app taking the foreground first would cost a step that this path is
    /// measured not to need.
    @Test @MainActor
    func aHostAlreadyInFrontOfTheUserIsNeverHidden() async {
        let application = FakeRaisableApplication()
        let foreground = ForegroundSpy()
        let activator = AppKitHostApplicationActivator(
            occupancy: OccupancyStub(true),
            applications: { _ in [application] },
            foreground: foreground,
            settle: {}
        )

        let raised = await activator.activate(Self.ghosttyHost())

        #expect(raised)
        #expect(application.calls == [.activate])
        #expect(foreground.calls.isEmpty)
    }

    /// A raise the window server never honours is reported as the failure it
    /// is, rather than as the raise `activate` claimed.
    ///
    /// This is the defect the whole sequence exists for. Measured 2026-08-30
    /// inside the running app against Ghostty windowed on a desktop that was
    /// not showing: `activate` answered `true`, the host came back from hidden
    /// and the desktop never changed — and because the answer was believed, the
    /// user was told the host had been raised. The window server's own yes/no
    /// is the only thing here that knows better, so it is asked afterwards and
    /// the click stands or falls on it.
    @Test @MainActor
    func aRaiseTheWindowServerRefusesIsNotReportedAsSuccess() async {
        let application = FakeRaisableApplication(activationArrives: false)
        let foreground = ForegroundSpy()
        let activator = AppKitHostApplicationActivator(
            occupancy: OccupancyStub(false),
            applications: { _ in [application] },
            foreground: foreground,
            settle: {}
        )

        let raised = await activator.activate(Self.ghosttyHost())

        #expect(!raised)
        // The host is put back, and this app does not sit in the foreground
        // with nothing to show for it.
        #expect(application.calls == [.hide, .activate, .unhide])
        #expect(!application.isHidden)
        #expect(foreground.calls == [.claim, .relinquish])
    }

    /// The window server is asked once per pause, and stops being asked the
    /// moment it says yes.
    ///
    /// A raise that lands must not pay the ceiling that exists for the ones
    /// that never will.
    @Test @MainActor
    func theWindowServerStopsBeingAskedAtTheFirstYes() async {
        let occupancy = OccupancyStub(answering: [false, false, false, true])
        let activator = AppKitHostApplicationActivator(
            occupancy: occupancy,
            applications: { _ in [FakeRaisableApplication()] },
            foreground: ForegroundSpy(),
            settle: {}
        )

        let raised = await activator.activate(Self.ghosttyHost())

        #expect(raised)
        // One to decide whether to hide, then three more until it says yes —
        // and not a single question after that.
        #expect(occupancy.asked == 4)
    }

    /// An application the user hid themselves is not hidden again, and a click
    /// that fails does not unhide it on their behalf.
    ///
    /// Activating a hidden application unhides it, which is the same step that
    /// carries the desktop — so nothing is lost by leaving it hidden here. What
    /// would be lost by unhiding it is the user's own decision.
    @Test @MainActor
    func aHostTheUserHidThemselvesIsLeftAsTheyLeftIt() async {
        let application = FakeRaisableApplication(
            isHidden: true,
            activationArrives: false
        )
        let activator = AppKitHostApplicationActivator(
            occupancy: OccupancyStub(false),
            applications: { _ in [application] },
            foreground: ForegroundSpy(),
            settle: {}
        )

        let raised = await activator.activate(Self.ghosttyHost())

        #expect(!raised)
        #expect(application.calls == [.activate])
        #expect(application.isHidden)
    }

    /// Only a window the user could actually see answers "the host is here".
    ///
    /// The on-screen list already excludes windows that are closed, minimised
    /// or never ordered in, so what is left to rule out is a status item
    /// (layer 3 — Claude Desktop and Ghostty each keep one) and a fully
    /// transparent window. Reading either as the host being in front of the
    /// user would leave the click on the wrong desktop, which is the defect.
    @Test
    func onlyAWindowTheUserCanSeeCountsAsTheHostBeingHere() {
        func reporter(_ windows: [[String: Any]]?) -> WindowServerOccupancyReporter {
            WindowServerOccupancyReporter(windows: { windows })
        }
        func window(
            pid: Int32,
            layer: Int = 0,
            alpha: Double = 1
        ) -> [String: Any] {
            [
                kCGWindowOwnerPID as String: pid,
                kCGWindowLayer as String: layer,
                kCGWindowAlpha as String: alpha
            ]
        }

        #expect(
            reporter([window(pid: 665)])
                .hasWindowOnActiveSpace(processIdentifier: 665)
        )
        // Somebody else's window on this desktop is not this host being here.
        #expect(
            !reporter([window(pid: 24_014)])
                .hasWindowOnActiveSpace(processIdentifier: 665)
        )
        #expect(
            !reporter([window(pid: 665, layer: 3)])
                .hasWindowOnActiveSpace(processIdentifier: 665)
        )
        #expect(
            !reporter([window(pid: 665, alpha: 0)])
                .hasWindowOnActiveSpace(processIdentifier: 665)
        )
        // A list that could not be read answers "not here", which sends the
        // click down the route that works either way.
        #expect(!reporter(nil).hasWindowOnActiveSpace(processIdentifier: 665))
    }

    /// The host a Ghostty-hosted row resolves to, as the ancestry answers it.
    private static func ghosttyHost() -> HostApplication {
        HostApplication(
            bundleIdentifier: "com.mitchellh.ghostty",
            displayName: "Ghostty",
            processIdentifier: 665
        )
    }

    /// The tree measured on this machine on 2026-08-19 for a desktop-hosted
    /// session: `claude` inside its own bundle, a helper of Claude Desktop's,
    /// then Claude Desktop.
    private static func measuredDesktopTree() -> ProcessAncestryHostResolver {
        ProcessAncestryHostResolver(
            parent: {
                [46_868: Int32(46_867), 46_867: Int32(24_014), 24_014: Int32(1)][$0]
            },
            executablePath: {
                [
                    46_868: "/Users/someone/Library/Application Support/Claude"
                        + "/claude-code/2.1.234/claude.app/Contents/MacOS/claude",
                    46_867: "/Applications/Claude.app/Contents/Helpers/disclaimer",
                    24_014: "/Applications/Claude.app/Contents/MacOS/Claude"
                ][$0]
            },
            bundle: {
                [
                    "/Users/someone/Library/Application Support/Claude"
                        + "/claude-code/2.1.234/claude.app": ApplicationBundle(
                            identifier: "com.anthropic.claude-code",
                            displayName: "Claude Code"
