}

/// An application that is written down rather than running.
@MainActor
private final class FakeRaisableApplication: RaisableApplication {
    enum Call: Equatable { case hide, unhide, activate }

    let processIdentifier: Int32
    private(set) var isHidden: Bool
    private(set) var calls: [Call] = []
    /// Whether the activation lands. A real one unhides the application as it
    /// comes forward; a refused one leaves it exactly where it was, and answers
    /// `true` all the same — which is why nothing reads the answer any more.
    private let activationArrives: Bool

    init(
        processIdentifier: Int32 = 665,
        isHidden: Bool = false,
        activationArrives: Bool = true
    ) {
        self.processIdentifier = processIdentifier
        self.isHidden = isHidden
        self.activationArrives = activationArrives
    }

    func hide() -> Bool {
        calls.append(.hide)
        isHidden = true
        // False even when it hides, as every host measured on 2026-08-22
        // answered.
        return false
    }

    func unhide() -> Bool {
        calls.append(.unhide)
        isHidden = false
        return true
    }

    func activate(options: NSApplication.ActivationOptions) -> Bool {
        calls.append(.activate)
        if activationArrives { isHidden = false }
        // `true` either way, exactly as the real one answers a refusal.
        return true
    }
}

/// The window server's one yes/no, written down rather than asked.
///
/// It counts the questions as well as answering them: "stops asking at the
/// first yes" is an invariant about how many times it is consulted, and there
/// is nowhere else to see that.
private final class OccupancyStub: ActiveSpaceOccupancyReporting, @unchecked Sendable {
    private let answers: [Bool]
    private let lock = NSLock()
    private var index = 0

    /// A host that is, or is not, where the user is looking — and stays that
    /// way however often it is asked.
    init(_ answer: Bool) { self.answers = [answer] }

    /// One answer per question, the last one repeating: `[false, false, true]`
    /// is a host that was not here, was still not here, and then arrived.
    init(answering answers: [Bool]) { self.answers = answers }

    /// How many times the window server was consulted.
    var asked: Int {
        lock.lock(); defer { lock.unlock() }
        return index
    }

    func hasWindowOnActiveSpace(processIdentifier: Int32) -> Bool {
        lock.lock(); defer { lock.unlock() }
        let answer = answers[min(index, answers.count - 1)]
        index += 1
        return answer
    }
}

/// This app's own foreground, written down.
@MainActor
private final class ForegroundSpy: ForegroundClaiming {
    enum Call: Equatable { case claim, relinquish }

    private(set) var calls: [Call] = []
    private(set) var isClaimed = false
    /// Whether taking the foreground is answered at once, or only when
    /// ``arrive(hostCalls:)`` is called — so a test can pin that nothing is
    /// asked of the host until it has been.
    private let claimsImmediately: Bool
    /// What the host had been asked by the time the foreground arrived.
    private(set) var hostCallsAtArrival: [FakeRaisableApplication.Call]?

    init(claimsImmediately: Bool = true) {
        self.claimsImmediately = claimsImmediately
    }

    func claim() {
        calls.append(.claim)
        if claimsImmediately { isClaimed = true }
    }

    func relinquish() { calls.append(.relinquish) }

    /// The foreground arriving, at the moment the test chooses.
    func arrive(hostCalls: [FakeRaisableApplication.Call]) {
        guard !isClaimed else { return }
        isClaimed = true
        hostCallsAtArrival = hostCalls
    }
}

@MainActor
private final class TerminalTabFocuserSpy: TerminalTabFocusing {
    private let answer: TerminalTabFocus
    private(set) var requested: [(device: String, host: String)] = []

    init(answer: TerminalTabFocus) {
        self.answer = answer
    }

    func focusTab(
        withTerminalDevice device: String,
        in application: HostApplication
    ) async -> TerminalTabFocus {
        requested.append((device, application.bundleIdentifier))
        return answer
    }
}

/// The interval a scheduling closure was handed, read back from the test.
private final class IntervalBox: @unchecked Sendable {
    private let lock = NSLock()
    private var interval: TimeInterval?

    func record(_ value: TimeInterval) {
        lock.lock()
        interval = value
        lock.unlock()
    }

    var value: TimeInterval? {
        lock.lock()
        defer { lock.unlock() }
        return interval
    }
}

/// Counts calls made from whichever thread the work landed on.
private final class CountingBox: @unchecked Sendable {
    private let lock = NSLock()
    private var count = 0

    func increment() {
        lock.lock()
        count += 1
        lock.unlock()
    }

    var value: Int {
        lock.lock()
        defer { lock.unlock() }
        return count
    }
}

@MainActor
private final class AgentNavigatorStub: AgentNavigating {
    private let error: (any Error)?
    private let outcome: NavigationOutcome
    private(set) var requestedThreadIDs: [String] = []
    private(set) var requestedAgents: [AgentKind] = []

    init(
        error: (any Error)? = nil,
        outcome: NavigationOutcome = .openedThread(host: "Codex Desktop")
    ) {
        self.error = error
        self.outcome = outcome
    }

    @discardableResult
    func open(_ session: MonitoredSession) async throws -> NavigationOutcome {
        requestedThreadIDs.append(session.threadID)
        requestedAgents.append(session.agent)
        if let error {
            throw error
        }
        return outcome
    }
}

extension NotchlineTests {
    /// A Completed row the user has not read still asks to be looked at.
    ///
    /// Only the user reading it can hide it, and that arrives on the watcher as
    /// a file change -- a hint, not a guarantee. Reporting nothing for such a
    /// row left the disappearance resting entirely on that one edge, with no
    /// bound when it landed late: traced on the live app at eight seconds of
    /// silence between the row being listed and the user reading it.
    ///
    /// The deadline must be measured forward from `now`, not from the terminal
    /// boundary. The latter sits permanently in the past, which the store
    /// clamps to its one-second floor and no refresh can move.
    @Test
    func terminalGateBooksARecheckWhileARowIsStillUnread() {
        var gate = TerminalUnreadMembershipGate(
            settlingInterval: 2,
            unreadRecheckInterval: 1
        )
        let start = Date(timeIntervalSince1970: 1_000)
        let unread = desktopReading(unread: ["thread"], after: start)

        let displayedAtOnce = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: unread, now: start
        )
        #expect(displayedAtOnce)

        let later = start.addingTimeInterval(600)
        let stillDisplayed = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: unread, now: later
        )
        #expect(stillDisplayed, "an unread terminal row stays listed")

        let deadline = gate.nextDeadline(now: later)
        #expect(
            deadline == later.addingTimeInterval(1),
            "an unread row must book a re-check, not go unwatched: got \(String(describing: deadline?.timeIntervalSince(later)))"
        )
        #expect(
            deadline.map { $0 > later } == true,
            "a deadline already in the past is the busy loop this replaced"
        )
    }

    /// The floor moves with each look, so it can never go stale.
    ///
    /// This is the property that separates the re-check from the deadline it
    /// replaced: the refresh at the reported instant re-evaluates the row and
    /// books the next look, rather than re-reporting an instant nothing can
    /// clear.
    @Test
    func terminalGateRecheckMovesForwardOnEveryLook() {
        var gate = TerminalUnreadMembershipGate(
            settlingInterval: 2,
            unreadRecheckInterval: 1
        )
        let start = Date(timeIntervalSince1970: 1_000)
        let unread = desktopReading(unread: ["thread"], after: start)

        _ = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: unread, now: start
        )
        let first = gate.nextDeadline(now: start)

        let woken = start.addingTimeInterval(1)
        _ = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: unread, now: woken
        )
        let second = gate.nextDeadline(now: woken)

        #expect(first == start.addingTimeInterval(1))
        #expect(second == woken.addingTimeInterval(1))
        #expect(
            second.map { $0 > woken } == true,
            "the re-check must stay ahead of the refresh that served it"
        )
    }

    /// Reading the row still hides it on the very next look, not on a window.
    ///
    /// The re-check is a floor under the watcher, not a delay added to it: once
    /// Desktop reports the thread read, the row goes on that evaluation.
    @Test
    func terminalGateHidesOnTheFirstLookAfterTheUserReadsIt() {
        var gate = TerminalUnreadMembershipGate(
            settlingInterval: 2,
            unreadRecheckInterval: 1
        )
        let start = Date(timeIntervalSince1970: 1_000)
        let unread = desktopReading(unread: ["thread"], after: start)
        let read = desktopReading(unread: [], after: start)

        _ = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: unread, now: start
        )

        // Long past the settling window, so nothing but the unread evidence
        // itself can be doing the hiding here.
        let readAt = start.addingTimeInterval(600)
        let displayed = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: read, now: readAt
        )
        #expect(!displayed, "a row observed unread hides the moment it reads as read")
        #expect(
            gate.nextDeadline(now: readAt) == nil,
            "a hidden row asks for nothing"
        )
    }

    /// The window that *is* real still gets reported, or the row never leaves.
    @Test
    func terminalGateStillSchedulesTheWindowItCanActuallyClear() {
        var gate = TerminalUnreadMembershipGate(settlingInterval: 2)
        let start = Date(timeIntervalSince1970: 1_000)
        // Authoritative, and Desktop does not consider it unread: the row is
        // inside its settling window and waiting really will hide it.
        let read = desktopReading(unread: [], after: start)

        let displayed = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: read, now: start
        )
        #expect(displayed, "a just-finished turn is not hidden instantly")
        #expect(gate.nextDeadline(now: start) == start.addingTimeInterval(2))

        // Once the window passes, the row hides and stops asking to be woken.
        let hidden = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: read,
            now: start.addingTimeInterval(2.1)
        )
        #expect(!hidden)
        #expect(gate.nextDeadline(now: start.addingTimeInterval(2.1)) == nil)
    }

    /// Silence from before the Turn is not evidence that anybody read it.
    ///
    /// The row leaves on a thread's *absence* from Desktop's
    /// unread set, and that absence only means "read" if the reading was taken
    /// late enough to have heard about the Turn. Desktop's file is a
    /// projection of dots it holds in memory, written through a trailing
    /// 500 ms debounce with no maximum wait that every persisted atom it owns
    /// shares -- and the composer draft is written on every keystroke. So a
    /// Turn that finished while the user typed in *another* thread had its dot
    /// up in Desktop's sidebar within milliseconds and stayed out of the file
    /// for the whole burst: measured at 45.4 seconds, 165 characters, one
    /// single write at the end of it.
    ///
    /// The file parsed the whole time, so it was authoritative; it did not
    /// name the thread, so the settling window retired the row; and hiding is
    /// final, so the id arriving afterwards brought nothing back. The user
    /// watched a row they had never read leave the notch.
    @Test
    func terminalGateWillNotRetireATurnAgainstAReadingOlderThanIt() {
        var gate = TerminalUnreadMembershipGate(
            settlingInterval: 2,
            unreadRecheckInterval: 1
        )
        let boundary = Date(timeIntervalSince1970: 1_000)
        // Authoritative -- the file parsed -- and last written half a minute
        // before this Turn ended, which is what a starved debounce leaves
        // behind. It cannot have recorded the Turn either way.
        let stale = DesktopUnreadStateSnapshot(
            unreadThreadIDs: [],
            source: .current,
            currentAsOf: boundary.addingTimeInterval(-30)
        )

        let listed = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: boundary,
            terminalBoundaryAt: boundary, unreadState: stale, now: boundary
        )
        #expect(listed)

        // Long past the settling window, which is the point: what used to
        // retire the row here was time, against a reading that never spoke.
        let hidden = !gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: boundary,
            terminalBoundaryAt: boundary, unreadState: stale,
            now: boundary.addingTimeInterval(600)
        )
        #expect(!hidden, "a row nobody has read must not leave on old silence")

        // The user stops typing, Desktop's debounce finally fires, and the
        // write still does not name the thread -- because they read it inside
        // the burst and the id was added and cleared without ever reaching
        // disk. *Now* the silence is about this Turn, and the row goes.
        let written = DesktopUnreadStateSnapshot(
            unreadThreadIDs: [],
            source: .current,
            currentAsOf: boundary.addingTimeInterval(45)
        )
        let hiddenNow = !gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: boundary,
            terminalBoundaryAt: boundary, unreadState: written,
            now: boundary.addingTimeInterval(600)
        )
        #expect(hiddenNow, "a reading that does reach the Turn still retires it")
    }

    /// A row waiting on a reading that has not been written yet waits on the
    /// *file*, and books the same forward-measured re-check as an unreadable
    /// one.
    ///
    /// Not the settling deadline: that instant is in the past and no refresh
    /// can move it, which is the busy loop wearing a deadline's clothes. And
    /// not nothing either -- Desktop's write is what clears this, and it lands
    /// whether or not anybody is at the machine, so a dark screen is no reason
    /// to stop watching for it.
    @Test
    func terminalGateBooksARecheckWhileTheReadingPredatesTheTurn() {
        var gate = TerminalUnreadMembershipGate(
            settlingInterval: 2,
            unreadRecheckInterval: 1
        )
        let boundary = Date(timeIntervalSince1970: 1_000)
        let stale = DesktopUnreadStateSnapshot(
            unreadThreadIDs: [],
            source: .current,
            currentAsOf: boundary.addingTimeInterval(-30)
        )

        let now = boundary.addingTimeInterval(600)
        let displayed = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: boundary,
            terminalBoundaryAt: boundary, unreadState: stale, now: now
        )
        #expect(displayed)
        #expect(
            gate.nextDeadline(now: now) == now.addingTimeInterval(1),
            "it waits on the next write, so the re-check is measured from now"
        )
        #expect(
            gate.nextDeadline(now: now, screenIsAvailable: false)
                == now.addingTimeInterval(1),
            "this row waits on the file, not on the user"
        )
    }

    /// Hiding is a decision, not a live readout.
    ///
    /// The gate used to un-hide a row the moment it read as unread again, which
    /// made every listed row a running report of whatever the sources happened
    /// to be saying. They are files another application writes when it likes,
    /// so a moment where they disagree is ordinary -- and each one put a
    /// retired row back on the notch for as long as it lasted (CC-024). Within
    /// one finished Turn there is no way to become unread again, so refusing
    /// costs nothing.
    @Test
    func terminalGateDoesNotBringBackARowItHasAlreadyHidden() {
        var gate = TerminalUnreadMembershipGate(
            settlingInterval: 2,
            unreadRecheckInterval: 1
        )
        let boundary = Date(timeIntervalSince1970: 1_000)
        let unread = desktopReading(unread: ["thread"], after: boundary)
        let read = desktopReading(unread: [], after: boundary)

        let listed = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: boundary,
            terminalBoundaryAt: boundary, unreadState: unread, now: boundary
        )
        #expect(listed)

        let hidden = !gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: boundary,
            terminalBoundaryAt: boundary, unreadState: read,
            now: boundary.addingTimeInterval(0.1)
        )
        #expect(hidden)

        // The sources disagree for a moment and the same Turn reads as unread
        // again. That is the flash, and it must not happen.
        let flashed = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: boundary,
            terminalBoundaryAt: boundary, unreadState: unread,
            now: boundary.addingTimeInterval(0.2)
        )
        #expect(!flashed, "a hidden row stays hidden for the Turn it was hidden for")
        #expect(
            gate.nextDeadline(now: boundary.addingTimeInterval(0.2)) == nil,
            "and it goes on asking for nothing"
        )

        // A newer Turn is the one thing that brings it back. Normally the
        // running status between them drops the entry outright; this is the
        // case where no refresh saw that happen.
        let again = boundary.addingTimeInterval(10)
        let relisted = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: again,
            terminalBoundaryAt: again, unreadState: unread, now: again
        )
        #expect(relisted, "a Turn nobody has read is a Turn to show")
    }

    /// An unreadable state cannot hide anything, but it can become readable.
    ///
    /// Waiting alone does not hide this row either, so it takes the same
    /// forward-measured re-check as an unread one rather than nothing at all.
    @Test
    func terminalGateBooksARecheckWhileTheUnreadStateIsUnreadable() {
        var gate = TerminalUnreadMembershipGate(
            settlingInterval: 2,
            unreadRecheckInterval: 1
        )
        let start = Date(timeIntervalSince1970: 1_000)
        let unreadable = desktopReading(
            unread: [], source: .lastKnownGood, after: start
        )

        let now = start.addingTimeInterval(600)
        let displayed = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: unreadable, now: now
        )
        #expect(displayed, "an unreadable state must never hide a row")
        #expect(gate.nextDeadline(now: now) == now.addingTimeInterval(1))
    }

    /// A row that never renders must never ask to be woken for.
    ///
    /// This used to be a row that *stopped* rendering: a Hook-tracked thread
    /// parsed fine while its metadata was absent and parsed to nothing once the
    /// metadata revealed a sub-agent, so the first pass drew a row and created
    /// a gate entry that no later pass evaluated. `retain` kept it alive
    /// because it was keyed on every Hook state rather than on the sessions
    /// actually evaluated, and frozen inside its settling window it reported a
    /// deadline that went stale and stayed stale -- which the store clamps to
    /// its one-second floor.
    ///
    /// Eligibility fails closed now, so the first pass draws nothing and the
    /// entry is never created: the defect is unreachable rather than handled.
    /// Both halves are still worth pinning -- that a thread Codex will not
    /// vouch for renders no row on any pass, and that the pass which decided so
    /// leaves no deadline behind it.
    @Test @MainActor
    func aSessionThatStopsRenderingStopsSchedulingWakeUps() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let installer = CodexHookRegistrar(paths: paths)
        let clock = TestClock()
        let repository = HookEventRepository(
            paths: paths,
            clock: clock
        )
        try await installer.install()
        // Hook timestamps have to sit on the test clock's timeline, or the
        // settling window is measured against a boundary years away.
        let base = clock.now().timeIntervalSince1970
        for event in [
            [
                "received_at": base,
                "hook_event_name": "UserPromptSubmit",
                "session_id": "thread-sub",
                "turn_id": "turn-1"
            ],
            [
                "received_at": base + 1,
                "hook_event_name": "Stop",
                "session_id": "thread-sub",
                "turn_id": "turn-1"
            ]
        ] {
            try JSONSerialization.data(withJSONObject: event).deliver(to: repository)
        }

        // Every read says the same thing: this thread is a sub-agent, so no
        // pass renders a row for it.
        let client = CodexAppServerStub(
            listedThreads: [
                .object([
                    "id": .string("thread-sub"),
                    "ephemeral": .bool(false),
                    "threadSource": .string("user"),
                    "agentRole": .string("reviewer"),
                    "name": .string("Sub-agent work")
                ])
            ],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            unreadState: DesktopUnreadStateStub(unreadThreadIDs: []),
            clock: clock,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        // First pass: no metadata yet, and a Turn whose thread the App Server
        // has not vouched for is not a row.
        let first = await service.fetchSnapshot()
        #expect(first.sessions.isEmpty, "no row before metadata lands")
        await waitForThreadListRequests(client, atLeast: 1, completed: true)

        // Second pass, past the settling window but well inside every other
        // window, so the only deadline that could be stale is the gate's.
        await clock.advance(by: 10)
        let second = await service.fetchSnapshot()
        #expect(second.sessions.isEmpty, "a sub-agent thread renders no row")

        let deadline = await service.nextRefreshDeadline()
        await service.disconnect()

        let staleBy = deadline.map { Int(clock.now().timeIntervalSince($0)) } ?? 0
        #expect(
            deadline == nil || deadline! >= clock.now(),
            "a row nobody renders left a deadline \(staleBy)s in the past"
        )
    }

    /// A suppressed disconnect has to schedule its own re-examination.
    ///
    /// The grace period only bounds the wait if something looks again when it
    /// expires. The store slept on the service's deadlines, which know nothing
    /// about this gate, so a real disconnect could sit unpublished until an
    /// unrelated wake-up or the 60s heartbeat -- against a documented budget
    /// that counts the grace as 3s.
    @Test
    func connectionGateSchedulesItsOwnGraceExpiry() {
        var gate = ConnectionStabilityGate(gracePeriod: 3)
        let t0 = Date(timeIntervalSince1970: 1_000)

        #expect(gate.nextPublishDeadline == nil, "nothing suppressed yet")

        let publishedImmediately = gate.shouldPublish(
            candidate: .disconnected, current: .ready, observedAt: t0
        )
        #expect(!publishedImmediately, "a blip is suppressed")
        #expect(
            gate.nextPublishDeadline == t0.addingTimeInterval(3),
            "the suppression must schedule the moment it expires"
        )

        let publishedAtExpiry = gate.shouldPublish(
            candidate: .disconnected, current: .ready,
            observedAt: t0.addingTimeInterval(3)
        )
        #expect(publishedAtExpiry)

        // Publishing clears it, so the deadline cannot be re-reported forever.
        let afterPublish = gate.shouldPublish(
            candidate: .disconnected, current: .disconnected,
            observedAt: t0.addingTimeInterval(4)
        )
        #expect(afterPublish)
        #expect(gate.nextPublishDeadline == nil)
    }

    /// And a recovery inside the grace clears it too.
    @Test
    func connectionGateStopsSchedulingWhenTheBlipRecovers() {
        var gate = ConnectionStabilityGate(gracePeriod: 3)
        let t0 = Date(timeIntervalSince1970: 1_000)
        _ = gate.shouldPublish(candidate: .disconnected, current: .ready, observedAt: t0)
        #expect(gate.nextPublishDeadline != nil)

        let recovered = gate.shouldPublish(
            candidate: .ready, current: .ready,
            observedAt: t0.addingTimeInterval(1)
        )
        #expect(recovered)
        #expect(gate.nextPublishDeadline == nil, "a recovery must cancel the wake-up")
    }
}

extension Data {
    /// Hands this encoded payload to the store the way the transport does.
    ///
    /// The queue is gone, so a test that used to write this into a directory
    /// hands it over instead. `received_at` is read back out and used as the
    /// arrival stamp: the transport stamps arrival now, and the ordering rules
    /// these tests pin need to choose the instant.
    func deliver(to repository: HookEventRepository) {
        let object = (try? JSONSerialization.jsonObject(with: self)) as? [String: Any]
        let stamp = (object?["received_at"] as? Double)
            .map(Date.init(timeIntervalSince1970:)) ?? Date()
        repository.deliver(self, at: stamp)
    }
}

/// Records what the transport handed over, without reducing any of it.
///
/// The listener's whole job is now "one connection, one payload, in arrival
/// order", so a transport test asserts against what arrived rather than against
/// a directory the store no longer keeps.
private final class RecordedHookDelivery: @unchecked Sendable {
    private let lock = NSLock()
    private var bodies: [Data] = []

    /// What every connection this recorder is handed becomes.
    ///
    /// `.close` by default, which is what every lifecycle event is; a test that
    /// wants to see a connection held sets ``holds`` and then answers it.
    var holds = false
    private var heldDescriptors: [Int32] = []

    var deliver: @Sendable (Data, Date, Int32) -> AgentHookListener.Disposition {
        { [self] body, _, descriptor in
            lock.lock()
            bodies.append(body)
            let held = holds
            if held { heldDescriptors.append(descriptor) }
            lock.unlock()
            return held ? .held : .close
        }
    }

    /// Writes one answer onto the connection most recently held, the way
    /// ``HookReplyRegistry`` does, and closes it.
    @discardableResult
    func answerHeld(with body: Data) -> Bool {
        lock.lock()
        let descriptor = heldDescriptors.popLast()
        lock.unlock()
        guard let descriptor else { return false }
        defer { close(descriptor) }
        return body.withUnsafeBytes { raw in
            guard let base = raw.baseAddress else { return true }
            return write(descriptor, base, raw.count) == raw.count
        }
    }

    var payloads: [[String: Any]] {
        lock.lock()
        let received = bodies
        lock.unlock()
        return received.compactMap {
            (try? JSONSerialization.jsonObject(with: $0)) as? [String: Any]
        }
    }

    var count: Int {
        lock.lock()
        defer { lock.unlock() }
        return bodies.count
    }

    var sessions: [String] {
        payloads.compactMap { $0["session_id"] as? String }
    }
}

// MARK: - Deadlines nothing can clear

/// Three routes by which a finished row booked a one-second re-check for a
/// question no refresh reachable from that state could ever answer. They are
/// one bug wearing three coats: `nextRefreshDeadline()` may only report an
/// instant a refresh can actually advance, and each of these reported one it
/// could not.
///
/// - CR-Fable-001: the Codex gate is only ever pruned on the live-hook branch,
///   so losing Desktop freezes its entries and re-issues `now + 1s` forever.
/// - CR-Fable-018: the re-check runs through a sleeping display and a locked
///   screen, where every route that could retire the row is knowably shut.
/// - CR-Fable-036: a `tmux` or `ssh` session has a controlling terminal but no
///   host that can ever hold the front, so its verdict is permanently false.
extension NotchlineTests {
    /// A row waiting on the user books nothing while there is no screen to read
    /// it on.
    ///
    /// The row is right to stay listed -- nobody has read it -- but the sample
    /// that would ask again is not a sample of anything: every route to "read"
    /// requires the display awake and the session unlocked, so the answer is
    /// known before any work is done. Left ungated this was a wake-up a second,
    /// all night, on battery.
    @Test
    func terminalGateBooksNothingForARowWaitingOnAUserWithNoScreen() {
        var gate = TerminalUnreadMembershipGate(
            settlingInterval: 2,
            unreadRecheckInterval: 1
        )
        let start = Date(timeIntervalSince1970: 1_000)
        let unread = desktopReading(unread: ["thread"], after: start)

        let now = start.addingTimeInterval(600)
        let displayed = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: unread, now: now
        )
        #expect(displayed, "a locked screen must not retire anything")
        #expect(
            gate.nextDeadline(now: now, screenIsAvailable: false) == nil,
            "a re-check nothing can answer is a busy loop with a deadline's face"
        )
        // And the moment there is a screen again, it asks as it always did.
        #expect(
            gate.nextDeadline(now: now, screenIsAvailable: true)
                == now.addingTimeInterval(1)
        )
    }

    /// A row waiting on a *file* still books its re-check through a locked
    /// screen.
    ///
    /// The two halves of "waiting cannot hide this" are not the same wait, and
    /// collapsing them would be the mirror of the bug. An unreadable unread
    /// state becomes legible when the other application rewrites it, which
    /// happens whether or not anybody is at this machine.
    @Test
    func terminalGateStillWatchesAnUnreadableStateThroughALockedScreen() {
        var gate = TerminalUnreadMembershipGate(
            settlingInterval: 2,
            unreadRecheckInterval: 1
        )
        let start = Date(timeIntervalSince1970: 1_000)
        let unreadable = desktopReading(
            unread: [], source: .lastKnownGood, after: start
        )

        let now = start.addingTimeInterval(600)
        _ = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: unreadable, now: now
        )
        #expect(
            gate.nextDeadline(now: now, screenIsAvailable: false)
                == now.addingTimeInterval(1),
            "this row waits on the file, not on the user"
        )
    }

    /// And a row waiting on *time* still clears on time.
    ///
    /// The settling window is the one deadline here that a refresh advances by
    /// itself. Deferring it for a dark screen would leave the row on the notch
    /// until somebody came back to a machine that had already finished with it.
    @Test
    func terminalGateStillClearsItsSettlingWindowThroughALockedScreen() {
        var gate = TerminalUnreadMembershipGate(settlingInterval: 2)
        let start = Date(timeIntervalSince1970: 1_000)
        let read = desktopReading(unread: [], after: start)

        _ = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: read, now: start
        )
        #expect(
            gate.nextDeadline(now: start, screenIsAvailable: false)
                == start.addingTimeInterval(2)
        )
    }
}

extension NotchlineTests {
    /// A session under a multiplexer has a terminal and no host.
    ///
    /// Both chains below end at `launchd` and neither has the front, so the
    /// reading that only asks "is the host in front" cannot tell them apart --
    /// which is how a `tmux` session's permanent "no" was read as an ordinary
    /// "not yet". What separates them is what the chain passes *through*: an
    /// `.app` bundle for the emulator, a daemonised server for the multiplexer.
    @Test
    func aTerminalWhoseAncestryHasNoApplicationCanNeverBeInFront() async throws {
        // claude -> zsh -> tmux server -> launchd, and claude -> zsh -> login
        // -> Ghostty -> launchd. Nothing here is the frontmost process.
        let ancestry: [Int32: Int32] = [
            100: 200, 200: 300, 300: 1,
            400: 500, 500: 600, 600: 700, 700: 1
        ]
        let executables: [Int32: String] = [
            200: "/bin/zsh",
            300: "/opt/homebrew/bin/tmux",
            500: "/bin/zsh",
            600: "/usr/bin/login",
            700: "/Applications/Ghostty.app/Contents/MacOS/ghostty"
        ]
        let reader = ControllingTerminalGestureReader(
            controllingTerminalPath: { _ in "/dev/ttys009" },
            lastAccess: { _ in Date(timeIntervalSince1970: 500) },
            parentProcessIdentifier: { ancestry[$0] },
            executablePath: { executables[$0] },
            frontmostProcessIdentifier: { 9_999 },
            screenIsAvailable: { true }
        )

        let multiplexed = try #require(await reader.reading(forProcessIdentifier: 100))
        #expect(!multiplexed.hostIsInFrontOfTheUser)
        #expect(
            !multiplexed.hostCanEverBeInFrontOfTheUser,
            """
            nothing in this chain is an application, so no gesture at it can \
            ever coincide with its host holding the front
            """
        )

        let hosted = try #require(await reader.reading(forProcessIdentifier: 400))
        #expect(!hosted.hostIsInFrontOfTheUser, "another application is in front")
        #expect(
            hosted.hostCanEverBeInFrontOfTheUser,
            "a terminal on another display is a question worth asking again"
        )
    }

    /// The application being in front is still answered, and still needs a
    /// screen.
    ///
    /// The walk now runs even when the front cannot count, because "can this
    /// host ever be in front" has to be answered either way. This is the guard
    /// that stops that restructuring from quietly retiring rows behind a locked
    /// screen.
    @Test
    func aTerminalInFrontOfALockedScreenIsNotInFrontOfAnybody() async throws {
        let ancestry: [Int32: Int32] = [100: 200, 200: 300, 300: 1]
        let executables: [Int32: String] = [
            200: "/bin/zsh",
            300: "/Applications/Ghostty.app/Contents/MacOS/ghostty"
        ]
        func reader(screenIsAvailable: Bool) -> ControllingTerminalGestureReader {
            ControllingTerminalGestureReader(
                controllingTerminalPath: { _ in "/dev/ttys009" },
                lastAccess: { _ in Date(timeIntervalSince1970: 500) },
                parentProcessIdentifier: { ancestry[$0] },
                executablePath: { executables[$0] },
                frontmostProcessIdentifier: { 300 },
                screenIsAvailable: { screenIsAvailable }
            )
        }

        let lit = try #require(
            await reader(screenIsAvailable: true).reading(forProcessIdentifier: 100)
        )
        #expect(lit.hostIsInFrontOfTheUser)

        let dark = try #require(
            await reader(screenIsAvailable: false).reading(forProcessIdentifier: 100)
        )
        #expect(!dark.hostIsInFrontOfTheUser, "a locked screen shows nobody anything")
        #expect(
            dark.hostCanEverBeInFrontOfTheUser,
            "the host still exists; it is the screen that is off"
        )
    }
}

extension NotchlineTests {
    /// A `tmux` or `ssh` session's finished row stays, and books nothing.
    ///
    /// Both halves matter and the second is the one that was wrong. The row is
    /// correct to stay listed: nothing can say whether it has been read, so it
    /// leaves the way a terminal row always did — on the next submission, when
    /// the session goes away, or when the user removes it. But it used to enter
    /// the unread gate on the strength of *having a device*, where its verdict
    /// was false on every look, and that booked a full two-product refresh once
    /// a second for the life of the session. `ssh` is a first-class way to run
    /// this tool, so that was an ordinary evening, not an edge.
    @Test @MainActor
    func aSessionUnderAMultiplexerBooksNoRecheckForItsFinishedRow() async throws {
        let harness = try ClaudeCodeHarness()
        defer { harness.tearDown() }
        try harness.registerHooks()
        let cwd = "/Users/someone/Projects/thing"

        try harness.queue(event: "UserPromptSubmit", session: "cli", turn: "p-1", at: 100)
        try harness.queue(event: "Stop", session: "cli", turn: "p-1", at: 101)
        harness.live = [harness.session(id: "cli", cwd: cwd, pid: 4_242)]

        // A real device, read before the Turn ended, under a host that runs to
        // `launchd` without passing through an application.
        harness.setTerminalGesture(
            Date(timeIntervalSince1970: 100),
            forPID: 4_242,
            hostIsInFront: false,
            hostCanEverBeInFront: false
        )

        let snapshot = await harness.service.fetchSnapshot()
        #expect(snapshot.sessions.count == 1, "the row is right to stay listed")
        let deadline = await harness.service.nextRefreshDeadline()
        #expect(
            (deadline?.timeIntervalSinceNow ?? .infinity) > 2,
            "a question with no possible answer must book no re-check"
        )

        // The same session in a terminal that *could* come to the front is the
        // case the gate exists for, and still asks.
        harness.setTerminalGesture(
            Date(timeIntervalSince1970: 100),
            forPID: 4_242,
            hostIsInFront: false,
            hostCanEverBeInFront: true
        )
        _ = await harness.service.fetchSnapshot()
        let asking = await harness.service.nextRefreshDeadline()
        #expect((asking?.timeIntervalSinceNow ?? .infinity) <= 1.1)
    }

    /// A row the user removed keeps its place in the list and books nothing.
    ///
    /// Both halves are the point. The row stays in what Claude Code reports,
    /// because the removal is the store's record to keep and a Turn that
    /// stopped being listed is how the store learns a Turn has ended
    /// (CR-Fable-004) -- but it leaves the unread gate, because the only
    /// question that gate asks has already been answered by the user in the one
    /// way that outranks every source. Left in, it booked the terminal-gesture
    /// read and the three-state front check once a second, for a row the panel
    /// had stopped drawing (CR-Fable-003).
    @Test @MainActor
    func aRowTheUserRemovedLeavesTheGateWithoutLeavingTheList() async throws {
        let harness = try ClaudeCodeHarness()
        defer { harness.tearDown() }
        try harness.registerHooks()
        let cwd = "/Users/someone/Projects/thing"

        try harness.queue(event: "UserPromptSubmit", session: "cli", turn: "p-1", at: 100)
        try harness.queue(event: "Stop", session: "cli", turn: "p-1", at: 101)
        harness.live = [harness.session(id: "cli", cwd: cwd, pid: 4_242)]
        // Last at its terminal before the Turn ended, so the row is unread and
        // waiting on the user: exactly the row that books the re-check.
        harness.lastTerminalGestureByPID = [4_242: Date(timeIntervalSince1970: 100)]

        let unread = await harness.service.fetchSnapshot()
        let row = try #require(unread.sessions.first)
        let asking = await harness.service.nextRefreshDeadline()
        #expect((asking?.timeIntervalSinceNow ?? .infinity) <= 1.1)

        let afterRemoval = await harness.service
            .fetchSnapshot(dismissedRowIDs: [row.id])
        #expect(
            afterRemoval.sessions.map(\.id) == [row.id],
            "the Turn has not gone anywhere, so the product still reports it"
        )
        let quiet = await harness.service.nextRefreshDeadline()
        #expect(
            (quiet?.timeIntervalSinceNow ?? .infinity) > 2,
            """
            nothing can change what the user has already decided, so nothing \
            should wake for it
            """
        )

        // And the row it was keeping company still asks. One removal must not
        // quieten the rows the user is still waiting on.
        try harness.queue(event: "UserPromptSubmit", session: "two", turn: "p-2", at: 100)
        try harness.queue(event: "Stop", session: "two", turn: "p-2", at: 101)
        harness.live = [
            harness.session(id: "cli", cwd: cwd, pid: 4_242),
            harness.session(id: "two", cwd: cwd, pid: 4_243)
        ]
        harness.lastTerminalGestureByPID = [
            4_242: Date(timeIntervalSince1970: 100),
            4_243: Date(timeIntervalSince1970: 100)
        ]
        _ = await harness.service.fetchSnapshot(dismissedRowIDs: [row.id])
        let stillAsking = await harness.service.nextRefreshDeadline()
        #expect((stillAsking?.timeIntervalSinceNow ?? .infinity) <= 1.1)
    }

    /// A locked screen stops the re-check, and coming back restarts it.
    ///
    /// The row is not abandoned — it stays listed, because nobody has read it —
    /// but nothing wakes for it until there is a screen it could be read on.
    /// The second half is what makes the first safe: without an edge for the
    /// display waking, the row would sit until the heartbeat at exactly the
    /// moment the user is most likely to be looking at the notch.
    @Test @MainActor
    func aLockedScreenStopsTheRecheckAndComingBackRestartsIt() async throws {
        let harness = try ClaudeCodeHarness()
        defer { harness.tearDown() }
        try harness.registerHooks()
        let cwd = "/Users/someone/Projects/thing"

        try harness.queue(event: "UserPromptSubmit", session: "cli", turn: "p-1", at: 100)
        try harness.queue(event: "Stop", session: "cli", turn: "p-1", at: 101)
        harness.live = [harness.session(id: "cli", cwd: cwd, pid: 4_242)]
        // At its terminal before the Turn ended, so the row is unread and
        // waiting on the user coming back.
        harness.lastTerminalGestureByPID = [4_242: Date(timeIntervalSince1970: 100)]

        let lit = await harness.service.fetchSnapshot()
        #expect(lit.sessions.count == 1)
        let asking = await harness.service.nextRefreshDeadline()
        #expect((asking?.timeIntervalSinceNow ?? .infinity) <= 1.1)

        harness.screenIsAvailable = false
        let dark = await harness.service.fetchSnapshot()
        #expect(dark.sessions.count == 1, "a locked screen retires nothing")
        let quiet = await harness.service.nextRefreshDeadline()
        #expect(
            (quiet?.timeIntervalSinceNow ?? .infinity) > 2,
            """
            nothing can retire this row until there is a screen, so nothing \
            should wake for it
            """
        )

        // The display comes back on. The edge is what re-arms the row; the
        // deadline is what bounds how late it can leave after that.
        let triggers = harness.service.stateChangeEvents
        let observer = Task {
            for await _ in triggers { return true }
            return false
        }
        harness.announceScreenAvailable()
        let signalled = await withTaskGroup(of: Bool.self) { group in
            group.addTask { await observer.value }
            group.addTask {
                try? await Task.sleep(nanoseconds: 3_000_000_000)
                return false
            }
            let result = await group.next() ?? false
            group.cancelAll()
            return result
        }
        observer.cancel()
        #expect(signalled, "the screen coming back has to wake the loop")

        _ = await harness.service.fetchSnapshot()
        let askingAgain = await harness.service.nextRefreshDeadline()
        #expect((askingAgain?.timeIntervalSinceNow ?? .infinity) <= 1.1)
    }
}

private final class MutableDesktopProcessIdentifier: @unchecked Sendable {
    private let lock = NSLock()
    private var stored: pid_t?

    init(_ value: pid_t?) { stored = value }

    var value: pid_t? {
        get { lock.lock(); defer { lock.unlock() }; return stored }
        set { lock.lock(); stored = newValue; lock.unlock() }
    }
}

extension NotchlineTests {
    /// Losing Desktop must not leave the Codex gate frozen at 1 Hz.
    ///
    /// The gate's entries are only ever hidden or pruned inside
    /// `sessions(from:)`, which only the live-hook branch reaches. Every other
    /// branch — no hook observation, setup required, and each error — used to
    /// return without touching it, so an entry for an unread row froze in place
    /// and went on re-issuing a deadline one second forward from now, forever.
    /// The store's stuck-deadline filter cannot catch that: it suppresses a
    /// *repeated identical* overdue instant, and this one moves on every call.
    ///
    /// The user's version of it: finish a turn, do not read it, quit Codex
    /// Desktop. Nothing is on screen, and the app wakes once a second for the
    /// rest of the day.
    @Test @MainActor
    func losingHookObservationPrunesTheCodexUnreadGate() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()
        for event in ["UserPromptSubmit", "Stop"] {
            try JSONSerialization.data(withJSONObject: [
                "received_at": Date().timeIntervalSince1970,
                "hook_event_name": event,
                "session_id": "thread-frozen",
                "turn_id": "turn-frozen"
            ]).deliver(to: repository)
        }

        let client = CodexAppServerStub(
            listedThreads: [.object([
                "id": .string("thread-frozen"),
                "ephemeral": .bool(false),
                "threadSource": .string("user"),
                "updatedAt": .number(Date().timeIntervalSince1970),
                "name": .string("Frozen")
            ])],
            loadedListResults: []
        )
        // Desktop still reports the finished thread unread, which is what puts
        // it in the gate and keeps it there.
        let unreadState = DesktopUnreadStateStub(
            unreadThreadIDs: ["thread-frozen"]
        )
        let desktop = MutableDesktopProcessIdentifier(4_242)
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            unreadState: unreadState,
            desktopProcessIdentifierProvider: { desktop.value }
        )
        defer { Task { await service.disconnect() } }

        var listed = false
        for _ in 0 ..< 100 {
            let snapshot = await service.fetchSnapshot()
            if snapshot.sessions.first?.status == .completed {
                listed = true
                break
            }
            try await Task.sleep(nanoseconds: 10_000_000)
        }
        #expect(listed, "an unread finished row is listed")
        let asking = await service.nextRefreshDeadline()
        #expect(
            (asking?.timeIntervalSinceNow ?? .infinity) <= 1.1,
            "while it is on screen, the row asks to be looked at again"
        )

        // The user quits Codex Desktop. Hook observation is lost, this branch
        // publishes no rows at all, and the entry the gate is holding can never
        // be evaluated again.
        desktop.value = nil
        let quiet = await service.fetchSnapshot()
        #expect(quiet.sessions.isEmpty, "nothing is on screen any more")
        let deadline = await service.nextRefreshDeadline()
        #expect(
            (deadline?.timeIntervalSinceNow ?? .infinity) > 1.5,
            """
            a branch that cannot evaluate a row must not book a re-check for \
            one: this is the 1 Hz that ran with an empty notch
            """
        )
    }

    /// The no-hook branch confirms the transport. It does not read the history.
    ///
    /// CR-Fable-023. `thread/list` does two jobs and this branch needs only the
    /// cheaper one: sessions cannot be produced without a live Hook — the
    /// branch's defining condition, and a deliberate product rule (PRD §3) — so
    /// the membership set the sweep rebuilt was read by nobody. The user's
    /// version of it: keep the integration installed, work in Claude Code, and
    /// leave Codex Desktop shut. The App Server was asked to paginate every
    /// unarchived thread the user owns, every thirty seconds, around the clock,
    /// to answer "does this transport answer a read".
    @Test @MainActor
    func withNoHookObservationTheTransportIsConfirmedWithoutReadingTheHistory() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        try await installer.install()
        let clock = TestClock()
        let timing = MonitorTiming.standard
        // A history worth not reading.
        let client = CodexAppServerStub(
            listedThreads: (0 ..< 40).map { index in
                .object([
                    "id": .string("thread-\(index)"),
                    "ephemeral": .bool(false),
                    "threadSource": .string("user"),
                    "name": .string("History \(index)")
                ])
            },
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: HookEventRepository(
                paths: paths,
                clock: clock,
                timing: timing
            ),
            hookRegistrar: installer,
            clock: clock,
            timing: timing,
            desktopProcessIdentifierProvider: { nil }
        )
        defer { Task { await service.disconnect() } }

        let ready = await service.fetchSnapshot()
        #expect(ready.availability == .ready, "the transport still answers")
        #expect(ready.sessions.isEmpty)
        #expect(ready.presence == .closed)

        // Ten membership windows of a day with Desktop shut.
        for _ in 0 ..< 10 {
            await clock.advance(by: timing.threadListRefreshInterval + 1)
            _ = await service.fetchSnapshot()
        }

        let requests = await client.recordedThreadListParams()
        #expect(!requests.isEmpty, "the transport is still confirmed by a read")
        #expect(
            requests.allSatisfy { $0["limit"]?.intValue == 1 },
            """
            a branch that produces no rows asked for the whole history \
            \(requests.map { $0["limit"]?.intValue ?? -1 })
            """
        )
        #expect(
            requests.allSatisfy { $0["cursor"] == nil },
            "one page is the whole of what confirming a read needs"
        )
    }

    /// A membership set nobody reads is not woken for.
    ///
    /// The other half of CR-Fable-023, and the half that would have turned the
    /// first into a busy loop. `nextRefreshDeadline()` may only report an
    /// instant that the refresh it wakes can actually move; the membership
    /// deadline was armed from a read stamp alone, and the only code that
    /// re-reads membership is in the live-Hook branch. So with Desktop gone the
    /// store woke on an instant no refresh could clear, found it still in the
    /// past, and fell through to the refresh floor — 1 Hz with an empty notch,
    /// the same shape as CR-Fable-050 one branch further up.
    @Test @MainActor
    func aMembershipSetWithNoLiveTurnBehindItIsNotWokenFor() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let clock = TestClock()
        let timing = MonitorTiming.standard
        let repository = HookEventRepository(
            paths: paths,
            clock: clock,
            timing: timing
        )
        try await installer.install()
        try JSONSerialization.data(withJSONObject: [
            "received_at": clock.now().timeIntervalSince1970,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-live",
            "turn_id": "turn-live"
        ]).deliver(to: repository)

        let client = CodexAppServerStub(
            listedThreads: [.object([
                "id": .string("thread-live"),
                "ephemeral": .bool(false),
                "threadSource": .string("user"),
                "name": .string("Live")
            ])],
            loadedListResults: []
        )
        let desktop = MutableDesktopProcessIdentifier(4_242)
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            clock: clock,
            timing: timing,
            desktopProcessIdentifierProvider: { desktop.value }
        )
        defer { Task { await service.disconnect() } }

        // A live Turn, so the sweep runs and leaves a read stamp behind it.
        let running = await snapshotWithSessions(from: service)
        #expect(running.sessions.first?.status == .running)
        await waitForThreadListRequests(client, atLeast: 1, completed: true)
        let sweeps = await client.requestCount(method: "thread/list")

        // The user quits Codex Desktop. The Turn is retired with the process
        // that vouched for it, and nothing is left that reads a membership set.
        desktop.value = nil
        let quiet = await service.fetchSnapshot()
        #expect(quiet.sessions.isEmpty)

        await clock.advance(by: timing.threadListRefreshInterval + 1)
        _ = await service.fetchSnapshot()
        await clock.settle()

        let requests = await client.recordedThreadListParams()
        #expect(
            requests.dropFirst(sweeps).allSatisfy { $0["limit"]?.intValue == 1 },
            "the membership window came due for a set nothing reads"
        )
        let deadline = await service.nextRefreshDeadline()
        let stale = deadline.map { Int(clock.now().timeIntervalSince($0)) } ?? 0
        #expect(
            deadline == nil || deadline! >= clock.now(),
            "a set nobody reads left a deadline \(stale)s in the past"
        )
    }

    /// A read parked by a backoff goes when its consumer goes.
    ///
    /// Same rule as CR-Fable-023 seen from the retry side. A membership read
    /// that failed keeps its request outstanding and publishes its cool-off as
    /// a wake-up, and only the live-Hook branch picks such a request back up.
    /// Losing Desktop between the failure and the retry therefore left a marker
    /// with nobody to clear it: the store woke at it, ran a refresh that could
    /// not reach the scheduler, and span at the floor.
    @Test @MainActor
    func aParkedReadIsDroppedWhenNothingCanRunItAgain() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let clock = TestClock()
        let timing = MonitorTiming.standard
        let repository = HookEventRepository(
            paths: paths,
            clock: clock,
            timing: timing
        )
        try await installer.install()
        try JSONSerialization.data(withJSONObject: [
            "received_at": clock.now().timeIntervalSince1970,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-parked",
            "turn_id": "turn-parked"
        ]).deliver(to: repository)

        let client = CodexAppServerStub(
            listedThreads: [.object([
                "id": .string("thread-parked"),
                "ephemeral": .bool(false),
                "threadSource": .string("user"),
                "name": .string("Parked")
            ])],
            loadedListResults: [],
            threadListError: .timeout(method: "thread/list")
        )
        let desktop = MutableDesktopProcessIdentifier(4_242)
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            clock: clock,
            timing: timing,
            desktopProcessIdentifierProvider: { desktop.value }
        )
        defer { Task { await service.disconnect() } }

        // The membership read fails, so its request stays outstanding behind a
        // cool-off that only the live-Hook branch can spend.
        _ = await service.fetchSnapshot()
        await waitForThreadListRequests(client, atLeast: 1)
        await clock.settle()
        let parked = await service.nextRefreshDeadline()
        #expect(
            parked != nil,
            "a parked retry is what the store wakes for while it can run it"
        )

        // The user quits Codex Desktop before the cool-off expires.
        desktop.value = nil
        await client.setThreadListError(nil)
        _ = await service.fetchSnapshot()
        await clock.advance(by: timing.requestRetryInterval + 1)
        _ = await service.fetchSnapshot()
        await clock.settle()

        let deadline = await service.nextRefreshDeadline()
        let stale = deadline.map { Int(clock.now().timeIntervalSince($0)) } ?? 0
        #expect(
            deadline == nil || deadline! >= clock.now(),
            "a retry nothing can run left a deadline \(stale)s in the past"
        )
    }

    /// Removing a Codex row takes it out of the unread gate, and leaves it in
    /// the list.
    ///
    /// The Codex half of CR-Fable-003. An unread finished row books a re-check
    /// a second, and every one of them is a full snapshot -- the main-actor
    /// `NSRunningApplication` round trip included. A row the user has waved
    /// away is not waiting on being read by anybody, so it must book none of
    /// them; it stays listed because Codex is still holding that Turn, and a
    /// product that stopped listing it would be telling the store the Turn had
    /// ended.
    @Test @MainActor
    func removingACodexRowTakesItOutOfTheUnreadGate() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()
        for event in ["UserPromptSubmit", "Stop"] {
            try JSONSerialization.data(withJSONObject: [
                "received_at": Date().timeIntervalSince1970,
                "hook_event_name": event,
                "session_id": "thread-unread",
                "turn_id": "turn-unread"
            ]).deliver(to: repository)
        }

        let client = CodexAppServerStub(
            listedThreads: [.object([
                "id": .string("thread-unread"),
                "ephemeral": .bool(false),
                "threadSource": .string("user"),
                "updatedAt": .number(Date().timeIntervalSince1970),
                "name": .string("Unread")
            ])],
            loadedListResults: []
        )
        let unreadState = DesktopUnreadStateStub(
            unreadThreadIDs: ["thread-unread"]
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            unreadState: unreadState,
            desktopProcessIdentifierProvider: { 4_242 }
        )
        defer { Task { await service.disconnect() } }

        var row: MonitoredSession?
        for _ in 0 ..< 100 {
            let snapshot = await service.fetchSnapshot()
            if let listed = snapshot.sessions.first, listed.status == .completed {
                row = listed
                break
            }
            try await Task.sleep(nanoseconds: 10_000_000)
        }
        let unread = try #require(row, "an unread finished row is listed")
        let asking = await service.nextRefreshDeadline()
        #expect(
            (asking?.timeIntervalSinceNow ?? .infinity) <= 1.1,
            "while it is on screen, the row asks to be looked at again"
        )

        // The user right-clicks it away. Desktop is still running and still
        // reports the thread unread; nothing about the Turn has changed.
        let afterRemoval = await service.fetchSnapshot(dismissedRowIDs: [unread.id])
        #expect(
            afterRemoval.sessions.map(\.id) == [unread.id],
            "the Turn is still Codex's, so the product still reports it"
        )
        let quiet = await service.nextRefreshDeadline()
        #expect(
            (quiet?.timeIntervalSinceNow ?? .infinity) > 1.5,
            """
            a row nobody can see must not book a snapshot a second to ask \
            whether it has been read
            """
        )
    }
    /// A Turn dies with the Desktop process that produced it.
    ///
    /// CR-Fable-007. The pid gate bound `hasCurrentHookObservation` -- whether
    /// to publish -- and never the Turns it vouched for, so a Desktop that
    /// crashed mid-turn left its Running Turn sitting in the reducer. The row
    /// went away while Desktop was closed, and the first hook event from the
    /// relaunched process brought it back: that event rebound the observation
    /// to the new pid, and everything the reducer still held published with it.
    /// Nothing could then remove it -- the thread is still listed, no hook will
    /// ever name that `turn_id` again, and Codex has no activity-status read to
    /// end it with -- so it stood as a Running row with a timer counting from
    /// before the crash until the user dismissed it by hand.
    ///
    /// Both threads stay listed and unarchived throughout, which is what makes
    /// this a test of the pid binding rather than of membership reconciliation.
    @Test @MainActor
    func aCrashedDesktopTakesItsRunningTurnWithIt() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()
        try JSONSerialization.data(withJSONObject: [
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-crashed",
            "turn_id": "turn-crashed"
        ]).deliver(to: repository)

        func listed(_ id: String, _ name: String) -> JSONValue {
            .object([
                "id": .string(id),
                "ephemeral": .bool(false),
                "threadSource": .string("user"),
                "updatedAt": .number(Date().timeIntervalSince1970),
                "name": .string(name)
            ])
        }
        let client = CodexAppServerStub(
            listedThreads: [
                listed("thread-crashed", "Interrupted"),
                listed("thread-after", "Afterwards")
            ],
            loadedListResults: []
        )
        let desktop = MutableDesktopProcessIdentifier(4_242)
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { desktop.value }
        )
        defer { Task { await service.disconnect() } }

        var running = false
        for _ in 0 ..< 100 {
            let snapshot = await service.fetchSnapshot()
            if snapshot.sessions.first?.status == .running {
                running = true
                break
            }
            try await Task.sleep(nanoseconds: 10_000_000)
        }
        #expect(running, "the turn Desktop is running is on the notch")

        // Codex Desktop crashes mid-turn. No `Stop` is sent, and none ever will
        // be: the process that owed it is gone.
        desktop.value = nil
        let closed = await service.fetchSnapshot()
        #expect(closed.sessions.isEmpty)
        #expect(closed.presence == .closed)

        // Desktop is relaunched under a new pid and the user types in some
        // other thread. One hook event is all it took.
        desktop.value = 9_001
        try JSONSerialization.data(withJSONObject: [
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-after",
            "turn_id": "turn-after"
        ]).deliver(to: repository)

        var relaunched: [MonitoredSession] = []
        for _ in 0 ..< 100 {
            let snapshot = await service.fetchSnapshot()
            if !snapshot.sessions.isEmpty {
                relaunched = snapshot.sessions
                break
            }
            try await Task.sleep(nanoseconds: 10_000_000)
        }
        #expect(
            relaunched.map(\.threadID) == ["thread-after"],
            """
            the new process answers for its own Turn and for nothing its \
            predecessor left behind
            """
        )
    }
}

// MARK: - A turn that has ended on a thread that has not

/// Four rules read `SessionStatus` to answer a question it does not answer:
/// *is anything still running on this thread?* For every row but one the two
/// agree. The exception is a row whose own turn has finished while a subagent
/// it spawned is still working — and that row is the only place the surface has
/// to say so, which is exactly what those rules were erasing.
///
/// Both products reach it. Codex spawns through `spawn_agent`; Claude Code's
/// `Agent` tool call returns as soon as the subagent is launched, so its turn
/// can reach `Stop` with the work it started still in flight.
extension NotchlineTests {
    /// The collapsed surface says `Running`, and says how many.
    ///
    /// Three shapes in one test, because what makes this readable is the
    /// difference between them:
    ///
    /// - no subagents and a turn being timed — the elapsed value alone, exactly
    ///   as before this change;
    /// - subagents and a turn being timed — the count in front of the elapsed
    ///   value;
    /// - subagents and every turn finished — the count on its own, with no
    ///   clock left to read.
    ///
    /// The last one is the whole point. It is `Running` with nothing being
    /// timed, which is true: no *turn* is running. `longestRunningSessionStart`
    /// filters on `keepsTiming` and finds nothing, and that is the correct
    /// answer rather than a hole to be filled.
    @Test @MainActor
    func aFinishedTurnWithASubagentStillRunningSummarisesAsRunning() async throws {
        let clock = TestClock()
        let store = makeIdleStore(clock: clock)
        let startedAt = clock.now().addingTimeInterval(-30)

        store.applyForTesting(
            makeSessionSnapshot([
                makeSession(status: .running, startedAt: startedAt)
            ]),
            observedAt: clock.now()
        )
        await clock.settle()
        #expect(store.status == .running)
        #expect(store.compactTrailingReading == CompactTrailingReading(timerText: "0:30"))
        #expect(store.aggregateSubagentCount == 0)

        store.applyForTesting(
            makeSessionSnapshot([
                makeSession(
                    status: .running,
                    startedAt: startedAt,
                    runningSubagentCount: 1
                )
            ]),
            observedAt: clock.now()
        )
        await clock.settle()
        // The collapsed surface counts subagents in its leading wing now, as
        // one aggregate numeral -- unlike a row's own trailing slot, it does
        // not wait for a row's turn to stop timing before counting them.
        #expect(store.compactTrailingReading == CompactTrailingReading(timerText: "0:30"))
        #expect(store.aggregateSubagentCount == 1)
        #expect(store.aggregateSubagentCount == 1)

        // The main agent's `Stop` lands. The row is Completed and the clock has
        // stopped -- both correct -- and the thread is still working.
        store.applyForTesting(
            makeSessionSnapshot([
                makeSession(
                    status: .completed,
                    startedAt: startedAt,
                    runningSubagentCount: 2
                )
            ]),
            observedAt: clock.now()
        )
        await clock.settle()
        #expect(store.status == .running, "the thread is still working")
        #expect(store.compactTimerText == nil, "no turn is being timed")
        #expect(store.compactTimerStart == nil)
        #expect(store.aggregateSubagentCount == 2)
        #expect(
            store.compactTrailingReading == .empty
        )
        #expect(store.aggregateSubagentCount == 2)
        // The row itself is untouched: `effectiveStatus` must not reach it.
        #expect(store.sessions.first?.status == .completed)
        #expect(store.elapsedText(for: try #require(store.sessions.first)) == nil)

        // The last subagent finishes. Everything falls back to what a finished
        // row has always looked like.
        store.applyForTesting(
            makeSessionSnapshot([
                makeSession(status: .completed, startedAt: startedAt)
            ]),
            observedAt: clock.now()
        )
        await clock.settle()
        #expect(store.status == .completed)
        #expect(store.compactTrailingReading == .empty)
        #expect(store.aggregateSubagentCount == 0)
    }

    /// The count is a total across the list, like the summary beside it.
    ///
    /// One collapsed surface speaks for every row, the same way one timer
    /// reports the longest-running turn rather than a turn of its own. And the
    /// slot is still the one place this is said: hiding the wings takes the
    /// count with it, because that preference is the user asking for the notch
    /// itself and nothing beside it.
    @Test @MainActor
    func theCollapsedCountTotalsEveryRowAndObeysTheHiddenWings() async throws {
        let clock = TestClock()
        let store = makeIdleStore(clock: clock)

        store.applyForTesting(
            makeSessionSnapshot([
                makeSession(
                    threadID: "one",
                    status: .completed,
                    startedAt: clock.now().addingTimeInterval(-60),
                    runningSubagentCount: 2
                ),
                makeSession(
                    threadID: "two",
                    status: .completed,
                    startedAt: clock.now().addingTimeInterval(-30),
                    runningSubagentCount: 1
                )
            ]),
            observedAt: clock.now()
        )
        await clock.settle()
        #expect(store.compactRunningSubagentCount == 3)
        // Three rows of one product, summed into one numeral.
        #expect(store.aggregateSubagentCount == 3)
        #expect(store.compactTrailingReading == .empty)

        // **And the numerals are ungated by `Hide the wings`.** That preference
        // decides whether the wing is drawn; it never decides what the numerals
        // count (`compact-view-v2.md` §9). The spoken badge total still answers
        // to it, because it speaks for marks that are on the surface.
        store.hidesCompactWings = true
        #expect(store.givesUpCompactWings, "the display can honour it")
        #expect(store.aggregateSubagentCount == 3)
        #expect(store.aggregateSessionCount == 2)
        #expect(store.compactRunningSubagentCount == 0)
    }


    /// A row saying work is still in flight sorts with the working ones.
    ///
    /// `PRD.md` §6.2 makes the summary and the list one rule, so both read the
    /// derived answer. Sorted by `SessionStatus` alone, the only row carrying
    /// the evidence that anything is still running sorts last -- and with three
    /// live turns beside it, last means outside the three-row viewport.
    @Test @MainActor
    func aFinishedRowWithASubagentSortsWithTheRunningOnes() {
        let now = Date(timeIntervalSince1970: 1_000_000)
        let working = makeSession(
            threadID: "working",
            status: .completed,
            startedAt: now.addingTimeInterval(-50),
            runningSubagentCount: 1
        )
        let sessions = [
            makeSession(
                threadID: "read",
                status: .completed,
                startedAt: now.addingTimeInterval(-10)
            ),
            makeSession(
                threadID: "old",
                status: .running,
                startedAt: now.addingTimeInterval(-300)
            ),
            working,
            makeSession(
                threadID: "recent",
                status: .running,
                startedAt: now.addingTimeInterval(-100)
            )
        ]

        let order = sessions.sorted(by: MonitorAggregation.rowOrder).map(\.threadID)
        // In the running band, and ordered inside it by recency like every
        // other row there. The genuinely finished row is still last.
        #expect(order == ["working", "recent", "old", "read"])
        // Rewritten rather than dropped when the viewport stopped counting
        // rows (`AGENTS.md` §5.2). The claim was never about a count: it is
        // that this row is *drawn*, and with nothing retired the viewport
        // holds `sessionViewportCap / sessionRowHeight` of them.
        let drawnRowCount = Int(
            PanelMetrics.sessionViewportHeight(liveRowCount: order.count)
                / PanelMetrics.sessionRowHeight
        )
        #expect(
            order.prefix(drawnRowCount).contains("working"),
            "the one row that knows work is still running stays in the viewport"
        )
    }

    /// The derived status is decided by the count, not by which product wrote
    /// it.
    ///
    /// This test used to assert the opposite half — that Claude Code never
    /// reports a subagent boundary, so `effectiveStatus` was the identity for
    /// every row it produced. Its own comment named the thing that would break
    /// it ("a later Claude Code reading that filled it in would silently change
    /// the summary, the order and the read gate at once"), and that reading now
    /// exists. What it always meant to pin is the rule underneath: a row with
    /// no subagent is untouched whoever produced it, and a row with one is
    /// treated the same way whoever produced it. Pinning the product instead
    /// would fail the moment either of them changed, which is exactly what
    /// happened.
    @Test @MainActor
    func theDerivedStatusReadsTheCountAndNotTheProduct() {
        for agent in [AgentKind.codex, .claudeCode] {
            let finished = makeSession(
                agent: agent,
                threadID: "quiet",
                status: .completed,
                startedAt: nil
            )
            #expect(finished.runningSubagentCount == 0)
            #expect(MonitorAggregation.effectiveStatus(of: finished) == .completed)
            #expect(
                MonitorAggregation.status(
                    agents: [makeSessionSnapshot([finished])],
                    sessions: [finished]
                ) == .completed
            )

            let working = makeSession(
                agent: agent,
                threadID: "working",
                status: .completed,
                startedAt: nil,
                runningSubagentCount: 1
            )
            #expect(MonitorAggregation.effectiveStatus(of: working) == .running)
            #expect(
                MonitorAggregation.status(
                    agents: [makeSessionSnapshot([working])],
                    sessions: [working]
                ) == .running
            )
            // And it sorts with the running ones rather than sinking to the
            // end of the list, on both products.
            #expect(MonitorAggregation.rowOrder(working, finished))
        }
    }

    /// The row can still be taken off the list by hand.
    ///
    /// Deliberate, and the reason is worth stating: removal means "I have seen
    /// this row", and the user's judgement outranks everything this app knows.
    /// It is also the only manual way out if a `SubagentStop` is ever lost and
    /// the count sticks -- the failure mode this design accepts in exchange for
    /// never saying `Completed` while work is still running.
    @Test @MainActor
    func aFinishedRowWithASubagentIsStillDismissable() async throws {
        let clock = TestClock()
        let store = makeIdleStore(clock: clock)
        store.applyForTesting(
            makeSessionSnapshot([
                makeSession(
                    status: .completed,
                    startedAt: clock.now().addingTimeInterval(-60),
                    runningSubagentCount: 1
                )
            ]),
            observedAt: clock.now()
        )
        await clock.settle()
        #expect(store.status == .running)

        let working = try #require(store.sessions.first)
        #expect(store.dismiss(working))
        #expect(store.sessions.isEmpty)
        #expect(store.compactTrailingReading == .empty)
    }

    /// A subagent boundary stamps its own instant and never the turn's.
    ///
    /// Two stamps, because they bound two different things. `lastEventAt` is
    /// the reducer's only defence against a subagent's chatter fending off
    /// membership reconciliation, so nothing a subagent does may move it.
    /// `lastSubagentBoundaryAt` exists so the finished row's settling window
    /// can start when the last subagent stopped rather than at a `Stop` that
    /// was 91 seconds earlier on the 2026-08-22 measurement.
    @Test @MainActor
    func aSubagentBoundaryStampsItsOwnInstantAndNotTheTurns() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let repository = HookEventRepository(paths: paths)
        let epoch = Date(timeIntervalSince1970: 1_000)
        func send(_ body: [String: Any], at offset: TimeInterval) async {
            repository.deliver(
                try! JSONSerialization.data(withJSONObject: body),
                at: epoch.addingTimeInterval(offset)
            )
            _ = await repository.drainDeliveredEvents()
        }

        await send([
            "hook_event_name": "UserPromptSubmit", "session_id": "s", "turn_id": "t"
        ], at: 1)
        await send([
            "hook_event_name": "SubagentStart", "session_id": "s",
            "turn_id": "sub", "agent_id": "a1"
        ], at: 2)
        await send([
            "hook_event_name": "Stop", "session_id": "s", "turn_id": "t"
        ], at: 3)

        var turn = try #require(await repository.observedState().turns.first)
        #expect(turn.lastEventAt == epoch.addingTimeInterval(3))
        #expect(turn.lastSubagentBoundaryAt == epoch.addingTimeInterval(2))
        // Still the turn's own instant: the subagent started before the turn
        // ended, so it has nothing later to say.
        #expect(turn.terminalBoundaryAt == epoch.addingTimeInterval(3))

        // 91 seconds later, as measured.
        await send([
            "hook_event_name": "SubagentStop", "session_id": "s",
            "turn_id": "sub", "agent_id": "a1"
        ], at: 94)

        turn = try #require(await repository.observedState().turns.first)
        #expect(
            turn.lastEventAt == epoch.addingTimeInterval(3),
            "a subagent must never fend off membership reconciliation"
        )
        #expect(turn.terminalBoundaryAt == epoch.addingTimeInterval(94))

        // Both are facts about the thread, so both survive the turn boundary
        // that the turn they were recorded on does not.
        await send([
            "hook_event_name": "UserPromptSubmit", "session_id": "s", "turn_id": "t2"
        ], at: 95)
        // Held until the thread's own record names it, as every Codex prompt
        // for a turn the thread is not on is (``HookTurnState/heldTurnStart``).
        _ = await repository.adoptTurnsOnRecord([
            TurnOnRecord(threadID: "s", turnID: "t2")
        ])
        turn = try #require(await repository.observedState().turns.first)
        #expect(turn.turnID == "t2")
        #expect(turn.lastSubagentBoundaryAt == epoch.addingTimeInterval(94))
    }

    /// Desktop reporting the thread read cannot erase the only row that knows
    /// work is still running.
    ///
    /// The membership gate hides a finished row once Desktop has persisted it
    /// as read and a settling interval has passed. Both halves of this change
    /// are needed to survive that, and the test fails without either: the gate
    /// has to be asked the derived question, *and* the window that follows the
    /// last subagent has to be measured from that subagent rather than from a
    /// main-agent `Stop` that may be minutes old.
    ///
    /// Every event is stamped in the past so the settling window has already
    /// expired at the first look — the state this is about is a thread the user
    /// is reading in Desktop right now, which is also the thread most likely to
    /// have just spawned something.
    @Test @MainActor
    func aReadThreadWithASubagentStillRunningKeepsItsRow() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()

        // The window this is about is two seconds wide and the assertions
        // below wait on a socket, so the clock has to be the test's: on the
        // system clock the second wait raced that window, and a slow machine
        // read the row after it had closed rather than inside it. Every
        // timestamp in this test -- the payload stamps, the thread's
        // `updatedAt` and the service's own `now` -- comes off this one
        // instant, so the arithmetic the gate does is fixed before the first
        // `fetchSnapshot`.
        let clock = TestClock()
        let now = clock.now()
        func deliver(_ body: [String: Any], secondsAgo: TimeInterval) throws {
            var payload = body
            payload["received_at"] = now.addingTimeInterval(-secondsAgo)
                .timeIntervalSince1970
            try JSONSerialization.data(withJSONObject: payload).deliver(to: repository)
        }

        try deliver([
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-working", "turn_id": "turn-working"
        ], secondsAgo: 120)
        try deliver([
            "hook_event_name": "SubagentStart",
            "session_id": "thread-working", "turn_id": "sub", "agent_id": "a1"
        ], secondsAgo: 118)
        try deliver([
            "hook_event_name": "Stop",
            "session_id": "thread-working", "turn_id": "turn-working"
        ], secondsAgo: 60)

        let client = CodexAppServerStub(
            listedThreads: [.object([
                "id": .string("thread-working"),
                "ephemeral": .bool(false),
                "threadSource": .string("user"),
                "updatedAt": .number(now.timeIntervalSince1970),
                "name": .string("Working")
            ])],
            loadedListResults: []
        )
        // Desktop is authoritative and reports the thread as read: the user is
        // looking at it. Nothing here is waiting on them.
        let unreadState = DesktopUnreadStateStub(unreadThreadIDs: [])
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            unreadState: unreadState,
            clock: clock,
            desktopProcessIdentifierProvider: { 4_242 }
        )
        defer { Task { await service.disconnect() } }

        var listed: MonitoredSession?
        for _ in 0 ..< 100 {
            let snapshot = await service.fetchSnapshot()
            if let row = snapshot.sessions.first {
                listed = row
                break
            }
            try await Task.sleep(nanoseconds: 10_000_000)
        }
        let working = try #require(
            listed,
            "a read thread with a subagent still running keeps its row"
        )
        #expect(working.status == .completed)
        #expect(working.runningSubagentCount == 1)
        #expect(MonitorAggregation.effectiveStatus(of: working) == .running)

        // The last subagent finishes now. The row becomes terminal at this
        // instant, not at the `Stop` a minute ago, so its settling window is
        // still open and the row is still listed.
        try deliver([
            "hook_event_name": "SubagentStop",
            "session_id": "thread-working", "turn_id": "sub", "agent_id": "a1"
        ], secondsAgo: 0)

        var settling: [MonitoredSession] = []
        for _ in 0 ..< 100 {
            let snapshot = await service.fetchSnapshot()
            if snapshot.sessions.first?.runningSubagentCount == 0 {
                settling = snapshot.sessions
                break
            }
            try await Task.sleep(nanoseconds: 10_000_000)
        }
        #expect(
            settling.map(\.threadID) == ["thread-working"],
            """
            the window starts when the last subagent stopped: measured from \
            the main agent's `Stop`, this row would already be gone
            """
        )
    }

    /// The trailing reading widens either collapsed form, by exactly what it
    /// draws, and both give every point back.
    ///
    /// **One rule for two forms, which is the change.** The notched bar has
    /// hung its reading off the cut-out since it stopped reserving; the pill
    /// held a `00:00:00` slot open instead, so an elapsed value moved it only
    /// when a badge beside one outgrew that slot. Neither reserves now: a timer
    /// arriving, a digit arriving, a badge arriving and a badge's own count
    /// growing each widen the surface, and each hands the width back when it
    /// goes. The one thing that still cannot move either of them is *counting*
    /// -- the same reading measures the same width whatever state it is read
    /// in.
    @Test @MainActor
    func theTrailingReadingWidensBothCollapsedForms() {
        func middle(_ trailing: CompactTrailingReading) -> CGFloat {
            PanelMetrics.pillMiddleWidth(trailing: trailing)
        }
        func wing(_ trailing: CompactTrailingReading) -> CGFloat {
            PanelMetrics.compactTrailingWidth(trailing: trailing)
        }

        let short = CompactTrailingReading(timerText: "1:23")
        let long = CompactTrailingReading(timerText: "1:23:45")

        // An empty reading costs either form nothing at all, and every reading
        // costs both of them something — the notched bar its wing, the pill its
        // middle.
        #expect(wing(.empty) == 0)
        for reading in [short, long] {
            #expect(middle(reading) < middle(.empty))
            #expect(wing(reading) > wing(.empty))
        }

        // A digit takes the same amount from both, because both are billed for
        // the drawn reading and for nothing else.
        let oneDigit = PanelMetrics.drawnCompactReadingWidth("1:23:45")
            - PanelMetrics.drawnCompactReadingWidth("1:23")
        #expect(oneDigit > 0)
        #expect(middle(short) - middle(long) == oneDigit)
        #expect(wing(long) - wing(short) == oneDigit)
    }
}

// MARK: - The same thing on Claude Code

/// The exception above is not a Codex-only shape, and the reason it looked like
/// one was that this product had never been asked.
///
/// Measured 2026-08-23 against CLI 2.1.241, one `-p` run whose prompt asked for
/// an `Agent` call that was not to be waited on. The order is the whole finding:
///
/// ```text
/// UserPromptSubmit  prompt_id=5fd7…
/// PreToolUse        prompt_id=5fd7…  tool=Agent   tool_use_id=toolu_01Un…
/// PostToolUse       prompt_id=5fd7…  tool=Agent   tool_use_id=toolu_01Un…
/// SubagentStart     prompt_id=5fd7…  agent_id=ae14…  agent_type=general-purpose
/// Stop              prompt_id=5fd7…  background_tasks=[{id: ae14…, type: subagent, status: running}]
/// PreToolUse        prompt_id=5fd7…  agent_id=ae14…  tool=Bash
/// PostToolUse       prompt_id=5fd7…  agent_id=ae14…  tool=Bash
/// SubagentStop      prompt_id=5fd7…  agent_id=ae14…
/// ```
///
/// The `Agent` call closes immediately, the turn reaches its `Stop` naming the
/// subagent as still running, and the subagent goes on making tool calls
/// afterwards. Without the two boundaries the row would say Completed for all
/// of it.
extension NotchlineTests {
    /// The row finishes, and says the thread has not.
    ///
    /// Every event here carries the parent's `session_id` **and** the parent's
    /// `prompt_id`, which is the difference from Codex: nothing a subagent
    /// sends can look like a new turn, so the turn id must come out unchanged.
    /// What still has to be true is everything else — the boundaries land, the
    /// subagent's own tool calls are consumed without touching the turn, and
    /// the count clears only when that subagent stops.
    @Test @MainActor
    func aClaudeCodeSubagentOutlivingItsTurnLeavesTheRowFinishedAndStillWorking()
        async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let repository = HookEventRepository(
            paths: paths,
            vocabulary: ClaudeCodeHookVocabulary()
        )
        let thread = "586df4ed-e1db-4405-bfd4-e9977957b132"
        let prompt = "5fd735f7-7fbb-4c25-9b2b-5861fa0e1305"
        let agent = "ae14e0ee8b5e04772"

        func deliver(_ body: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: body).deliver(to: repository)
        }

        try deliver([
            "received_at": 100.0, "hook_event_name": "UserPromptSubmit",
            "session_id": thread, "prompt_id": prompt
        ])
        try deliver([
            "received_at": 101.0, "hook_event_name": "PreToolUse",
            "session_id": thread, "prompt_id": prompt,
            "tool_name": "Agent", "tool_use_id": "toolu_01Un"
        ])
        try deliver([
            "received_at": 102.0, "hook_event_name": "PostToolUse",
            "session_id": thread, "prompt_id": prompt,
            "tool_name": "Agent", "tool_use_id": "toolu_01Un"
        ])
        try deliver([
            "received_at": 103.0, "hook_event_name": "SubagentStart",
            "session_id": thread, "prompt_id": prompt,
            "agent_id": agent, "agent_type": "general-purpose"
        ])
        try deliver([
            "received_at": 104.0, "hook_event_name": "Stop",
            "session_id": thread, "prompt_id": prompt
        ])

        var turn = try #require(await repository.drainDeliveredEvents().turns.first)
        // The turn the user started, and no other. A subagent cannot take it
        // over here, and this asserts the premise rather than assuming it.
        #expect(turn.turnID == prompt)
        #expect(turn.status == .completed)
        #expect(turn.runningSubagentIDs == [agent])
        #expect(turn.lastEventAt == Date(timeIntervalSince1970: 104))

        // The subagent's own work, arriving after the parent's terminal and
        // stamped with the parent's identity. Consumed and dropped: it is not
        // the row's turn doing anything, and it must not move the stamp that
        // bounds membership reconciliation.
        try deliver([
            "received_at": 110.0, "hook_event_name": "PreToolUse",
            "session_id": thread, "prompt_id": prompt, "agent_id": agent,
            "tool_name": "Bash", "tool_use_id": "toolu_01UN"
        ])
        try deliver([
            "received_at": 111.0, "hook_event_name": "PostToolUse",
            "session_id": thread, "prompt_id": prompt, "agent_id": agent,
            "tool_name": "Bash", "tool_use_id": "toolu_01UN"
        ])
        turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.status == .completed)
        #expect(turn.runningSubagentIDs == [agent])
        #expect(
            turn.lastEventAt == Date(timeIntervalSince1970: 104),
            "a subagent's chatter must not fend off membership reconciliation"
        )
        // Dropped in pairs, so the trust probe behind
        // `undeliveredPreToolUseDiagnostic` never sees a close without an open.
        #expect(await repository.drainDeliveredEvents().diagnostic == nil)

        // The row draws it, on this product exactly as on the other.
        let session = MonitoredSession(
            agent: .claudeCode,
            threadID: turn.threadID,
            turnID: turn.turnID,
            projectName: "notchline",
            title: "Untitled",
            preview: nil,
            status: turn.status,
            startedAt: turn.startedAt,
            runningSubagentCount: turn.runningSubagentIDs.count
        )
        #expect(session.showsSubagentBadge)
        #expect(session.subagentBadge == SubagentBadge(count: 1))
        #expect(MonitorAggregation.effectiveStatus(of: session) == .running)

        try deliver([
            "received_at": 112.0, "hook_event_name": "SubagentStop",
            "session_id": thread, "prompt_id": prompt, "agent_id": agent,
            "agent_type": "general-purpose",
            "last_assistant_message": "Here is the full contents of note.txt"
        ])
        turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.runningSubagentIDs.isEmpty)
        #expect(turn.status == .completed)
        // `SubagentStop` carries the same `last_assistant_message` field `Stop`
        // does, and it is the *subagent's* closing words. The row reports its
        // own turn, so nothing here reaches the preview.
        #expect(turn.assistantPreview == nil)
        // The window a finished row settles in starts here, not at the `Stop`
        // eight seconds ago.
        #expect(turn.lastEventAt == Date(timeIntervalSince1970: 104))
        #expect(turn.terminalBoundaryAt == Date(timeIntervalSince1970: 112))
    }

    /// A session Claude Desktop reports as read keeps its row while a subagent
    /// is still working — and leaves once that subagent stops.
    ///
    /// The read gate is where this costs the most if it is missed: the moment
    /// the user opens the session, `lastFocusedAt` moves past the turn's `Stop`
    /// and the row is retired — and the person most likely to be looking at a
    /// session is the one who just watched it launch something. Through the
    /// real service, because the rule is the orchestrator's and not the gate's.
    ///
    /// **The tail of this test used to assert the opposite, and that assertion
    /// was the defect.** It read: "the row is terminal from this instant, so
    /// the focus recorded before it can no longer speak for the answer" — which
    /// dates the user's reading against ``HookTurnState/terminalBoundaryAt``.
    /// Reading is done to a Turn's *answer*, and the answer landed at the
    /// Turn's own `Stop`; a focus after that is a genuine read of it, and a
    /// subagent stopping later cannot make it unread again. Under the old rule
    /// the user read the row, the subagent finished, and the row came back
    /// reported unread and stayed until Claude Desktop happened to display that
    /// session a second time. Reported on both products; the Codex half is the
    /// same comparison against the unread file's `modificationDate`.
    ///
    /// What the subagent's boundary still buys is the settling window — the row
    /// is not snatched away in the instant its badge clears — and that is
    /// unobservable here, because this harness stamps its events in 1970 and
    /// the service reads a real clock.
    @Test @MainActor
    func aReadClaudeCodeSessionWithASubagentStillRunningKeepsItsRow() async throws {
        let harness = try ClaudeCodeHarness()
        defer { harness.tearDown() }
        try harness.registerHooks()
        let cwd = "/Users/someone/Projects/thing"

        try harness.queue(event: "UserPromptSubmit", session: "s-1", turn: "p-1", at: 100)
        try harness.queue(
            event: "SubagentStart", session: "s-1", turn: "p-1", at: 101,
            agentID: "a-1"
        )
        try harness.queue(event: "Stop", session: "s-1", turn: "p-1", at: 102)
        harness.live = [harness.session(id: "s-1", cwd: cwd)]

        // Nothing has spoken for this session yet, so the row is outside the
        // gate entirely. The reading below is what puts it in one.
        let unknown = await harness.service.fetchSnapshot()
        #expect(unknown.sessions.count == 1)

        // Desktop last had it on screen before the turn ended: unread, and
        // kept for that reason alone.
        try harness.writeDesktopRecord(
            session: "s-1", lastFocusedAt: 100, desktopID: "d-1"
        )
        #expect(await harness.service.fetchSnapshot().sessions.count == 1)

        // The user opens it. For a row with nothing left running this is the
        // end of it -- `aFinishedRowLeavesWhenClaudeDesktopSaysItWasRead` is
        // exactly this sequence and the row is gone by here. It survives only
        // because the thread is still working.
        try harness.writeDesktopRecord(
            session: "s-1", lastFocusedAt: 103, desktopID: "d-1"
        )
        let read = await harness.service.fetchSnapshot()
        let kept = try #require(
            read.sessions.first,
            "a read session with a subagent still running keeps its row"
        )
        #expect(kept.status == .completed)
        #expect(kept.runningSubagentCount == 1)
        #expect(MonitorAggregation.effectiveStatus(of: kept) == .running)

        // The subagent finishes. The thread has stopped working, and the focus
        // at 103 -- after the turn's own `Stop` at 102 -- already said the user
        // read the answer. That reading stands: nothing a subagent did
        // afterwards can turn a read Turn back into an unread one.
        try harness.queue(
            event: "SubagentStop", session: "s-1", turn: "p-1", at: 104,
            agentID: "a-1"
        )
        #expect(
            await harness.service.fetchSnapshot().sessions.isEmpty,
            """
            a Turn read after its own `Stop` stays read when its subagent \
            stops later
            """
        )
    }

    /// And an *unread* Turn is still kept when its subagent stops.
    ///
    /// The other half of the rule above, and the one that must not be lost in
    /// fixing it: the focus here lands before the turn's `Stop`, so it never
    /// showed the user this answer, and the row stays for somebody to read.
    @Test @MainActor
    func anUnreadClaudeCodeSessionSurvivesItsSubagentStopping() async throws {
        let harness = try ClaudeCodeHarness()
        defer { harness.tearDown() }
        try harness.registerHooks()

        try harness.queue(event: "UserPromptSubmit", session: "s-1", turn: "p-1", at: 100)
        try harness.queue(
            event: "SubagentStart", session: "s-1", turn: "p-1", at: 101,
            agentID: "a-1"
        )
        try harness.queue(event: "Stop", session: "s-1", turn: "p-1", at: 102)
        harness.live = [
            harness.session(id: "s-1", cwd: "/Users/someone/Projects/thing")
        ]
        // On screen before the turn finished, and not since.
        try harness.writeDesktopRecord(
            session: "s-1", lastFocusedAt: 101, desktopID: "d-1"
        )
        #expect(await harness.service.fetchSnapshot().sessions.count == 1)

        try harness.queue(
            event: "SubagentStop", session: "s-1", turn: "p-1", at: 104,
            agentID: "a-1"
        )
        #expect(
            await harness.service.fetchSnapshot().sessions.map(\.threadID)
                == ["s-1"],
            "nobody has read this answer, so the row waits for somebody to"
        )

        // And it leaves on the reading that does speak for the turn.
        try harness.writeDesktopRecord(
            session: "s-1", lastFocusedAt: 105, desktopID: "d-1"
        )
        #expect(await harness.service.fetchSnapshot().sessions.isEmpty)
    }

    /// A subagent's displayed text is not the row's text.
    ///
    /// `MessageDisplay` is folded into the session's preview before the reducer
    /// is reached, which is the one path a subagent's event can take to the user
    /// without passing the `agent_id` gate. Two `-p` probes produced the event
    /// for the main thread only — but `-p` displays no subagent text at all,
    /// and the field is on the base schema every Claude Code hook input
    /// extends, so the fold is held to the same rule the reducer is.
    @Test @MainActor
    func aSubagentsDisplayedTextIsNotTheRowsPreview() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let repository = HookEventRepository(
            paths: paths,
            vocabulary: ClaudeCodeHookVocabulary()
        )
        func display(_ text: String, agentID: String?) throws {
            var body: [String: Any] = [
                "received_at": 100.0,
                "hook_event_name": ClaudeCodeHookVocabulary.messageDisplayEventName,
                "session_id": "s", "prompt_id": "p",
                "message_id": agentID ?? "main", "delta": text
            ]
            if let agentID { body["agent_id"] = agentID }
            try JSONSerialization.data(withJSONObject: body).deliver(to: repository)
        }

        try display("Reading note.txt for you.", agentID: nil)
        #expect(
            repository.preview(forSession: "s", inTurn: "p") == "Reading note.txt for you."
        )

        try display("Here is the full contents of note.txt", agentID: "a-1")
        #expect(
            repository.preview(forSession: "s", inTurn: "p") == "Reading note.txt for you.",
            "the row reports its own turn, not what a subagent is saying"
        )
    }
}

// MARK: - A subagent's own approval

/// The state this product exists to report, arriving from a subagent.
///
/// Measured on both products on 2026-08-23 and written up in
/// `docs/technical-explorations/subagent-row-consistency/` §6.1 and §6.3. The
/// events these tests replay are the measured ones, not invented shapes: a
/// `PreToolUse` carrying a `tool_use_id`, then a `PermissionRequest` carrying
/// `tool_name` and no id at all, both stamped with the subagent's `agent_id`.
extension NotchlineTests {
    /// Where a subagent's approval lands, and what it changes.
    ///
    /// The parent's `Stop` really did arrive first — measured at +4.21 s with
    /// the dialog at +4.75 s — so this is a Completed row whose thread is
    /// stopped waiting for the person. The row keeps saying Completed, and the
    /// answer to "does anything here need me" changes.
    @Test @MainActor
    func aSubagentsApprovalReachesTheRowItBelongsTo() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let repository = HookEventRepository(
            paths: paths,
            vocabulary: ClaudeCodeHookVocabulary()
        )
        let thread = "586df4ed-e1db-4405-bfd4-e9977957b132"
        let prompt = "5fd735f7-7fbb-4c25-9b2b-5861fa0e1305"
        let agent = "a28a63c7"

        func deliver(_ body: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: body).deliver(to: repository)
        }

        try deliver([
            "received_at": 100.0, "hook_event_name": "UserPromptSubmit",
            "session_id": thread, "prompt_id": prompt
        ])
        try deliver([
            "received_at": 102.0, "hook_event_name": "PreToolUse",
            "session_id": thread, "prompt_id": prompt,
            "tool_name": "Agent", "tool_use_id": "toolu_0182"
        ])
        try deliver([
            "received_at": 103.0, "hook_event_name": "SubagentStart",
            "session_id": thread, "prompt_id": prompt,
            "agent_id": agent, "agent_type": "general-purpose"
        ])
        try deliver([
            "received_at": 104.0, "hook_event_name": "Stop",
            "session_id": thread, "prompt_id": prompt
        ])
        var turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.status == .completed)
        #expect(turn.subagentsAwaitingApproval == false)

        // The dialog opens: the subagent announces a call, and 20 ms later the
        // approval that carries no id of its own.
        try deliver([
            "received_at": 105.0, "hook_event_name": "PreToolUse",
            "session_id": thread, "prompt_id": prompt, "agent_id": agent,
            "tool_name": "Bash", "tool_use_id": "toolu_015Z"
        ])
        try deliver([
            "received_at": 105.02, "hook_event_name": "PermissionRequest",
            "session_id": thread, "prompt_id": prompt, "agent_id": agent,
            "tool_name": "Bash"
        ])
        turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.subagentsAwaitingApproval)
        // The row's own turn is untouched, all four ways.
        #expect(turn.turnID == prompt)
        #expect(turn.status == .completed)
        #expect(turn.pendingApproval == nil)
        #expect(
            turn.lastEventAt == Date(timeIntervalSince1970: 104),
            "a subagent's dialog must not fend off membership reconciliation"
        )

        let waiting = MonitoredSession(
            agent: .claudeCode,
            threadID: turn.threadID,
            turnID: turn.turnID,
            projectName: "notchline",
            title: "Untitled",
            preview: nil,
            status: turn.status,
            startedAt: turn.startedAt,
            runningSubagentCount: turn.runningSubagentIDs.count,
            subagentsAwaitingApprovalCount: turn.subagentsAwaitingApprovalCount
        )
        #expect(waiting.status == .completed, "the row still reports its own turn")
        #expect(waiting.showsSubagentBadge)
        // The one subagent it has is the one stopped on the prompt, so the
        // badge still reads `1` and its ground flips rather than splitting.
        #expect(waiting.subagentBadge == SubagentBadge(count: 1, wantsAttention: true))
        #expect(waiting.subagentsAwaitingApprovalCount == 1)
        #expect(MonitorAggregation.effectiveStatus(of: waiting) == .approvalNeeded)

        // Approved. `PostToolUse` names the same call and the same agent, which
        // is the only exact close either product offers.
        try deliver([
            "received_at": 112.0, "hook_event_name": "PostToolUse",
            "session_id": thread, "prompt_id": prompt, "agent_id": agent,
            "tool_name": "Bash", "tool_use_id": "toolu_015Z"
        ])
        turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.subagentsAwaitingApproval == false)
        #expect(turn.runningSubagentIDs == [agent], "it is still working")
        // Opens and closes stayed in step, so the trust probe stays quiet.
        #expect(await repository.drainDeliveredEvents().diagnostic == nil)
    }

    /// Being asked outranks being busy, and being asked a question outranks
    /// being asked for approval.
    @Test @MainActor
    func aSubagentsApprovalOutranksTheRunningItAlsoIs() {
        let finishedButAsking = makeSession(
            threadID: "asking",
            status: .completed,
            startedAt: Date(timeIntervalSince1970: 100),
            runningSubagentCount: 2,
            subagentsAwaitingApproval: true
        )
        #expect(
            MonitorAggregation.effectiveStatus(of: finishedButAsking) == .approvalNeeded,
            "two subagents are working and one of them is stopped on a dialog"
        )

        // A running turn with a blocked subagent is the shape the first pass at
        // this missed: it is not a Completed-row phenomenon. Measured with the
        // dialog at +4.02 s and the parent's `Stop` at +4.17 s.
        let runningAndAsking = makeSession(
            threadID: "running",
            status: .running,
            startedAt: Date(timeIntervalSince1970: 100),
            runningSubagentCount: 1,
            subagentsAwaitingApproval: true
        )
        #expect(MonitorAggregation.effectiveStatus(of: runningAndAsking) == .approvalNeeded)

        // The turn's own question wins. A refused approval is never closed by
        // either product, so the wait that follows it is the more current fact.
        let askedAQuestion = makeSession(
            threadID: "input",
            status: .inputNeeded,
            startedAt: Date(timeIntervalSince1970: 100),
            runningSubagentCount: 1,
            subagentsAwaitingApproval: true
        )
        #expect(MonitorAggregation.effectiveStatus(of: askedAQuestion) == .inputNeeded)

        let running = makeSession(
            threadID: "plain",
            status: .running,
            startedAt: Date(timeIntervalSince1970: 200)
        )
        #expect(
            MonitorAggregation.rowOrder(finishedButAsking, running),
            "a finished row with a blocked subagent sorts above a running one"
        )
    }

    /// Two streams, two slots, and neither can reach the other.
    ///
    /// This is the whole reason these events were thrown away before: with one
    /// slot on the turn, the subagent's `PreToolUse` would displace the main
    /// agent's open call and the subagent's `PostToolUse` would close the main
    /// agent's approval — on Codex, where a denial is silent, leaving a row
    /// that says Running while a human is still being asked.
    @Test @MainActor
    func aSubagentsApprovalNeverTouchesTheTurnsOwnSlots() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let repository = HookEventRepository(paths: paths)
        let thread = "01a03064-fd1b-70f3-9133-527d067719c8"
        let turnID = "01a03064-fd1c-70f3-9133-527d067719c8"
        let agent = "01a03065-0ff5-7442-acd8-e5ea27d83054"

        func deliver(_ body: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: body).deliver(to: repository)
        }

        try deliver([
            "received_at": 100.0, "hook_event_name": "UserPromptSubmit",
            "session_id": thread, "turn_id": turnID
        ])
        // The main agent is itself being asked about a call of its own.
        try deliver([
            "received_at": 101.0, "hook_event_name": "PreToolUse",
            "session_id": thread, "turn_id": turnID,
            "tool_name": "Bash", "tool_use_id": "call-main"
        ])
        try deliver([
            "received_at": 101.03, "hook_event_name": "PermissionRequest",
            "session_id": thread, "turn_id": turnID, "tool_name": "Bash"
        ])
        var turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.status == .approvalNeeded)
        #expect(turn.pendingApproval?.toolUseID == "call-main")

        // A subagent's whole cycle runs past it, carrying its own `turn_id` —
        // which on this product is not the row's, and must not become it.
        try deliver([
            "received_at": 102.0, "hook_event_name": "SubagentStart",
            "session_id": thread, "turn_id": "01a03065-100a", "agent_id": agent,
            "agent_type": "default"
        ])
        try deliver([
            "received_at": 103.0, "hook_event_name": "PreToolUse",
            "session_id": thread, "turn_id": "01a03065-100a", "agent_id": agent,
            "tool_name": "Bash", "tool_use_id": "exec-sub"
        ])
        try deliver([
            "received_at": 104.0, "hook_event_name": "PostToolUse",
            "session_id": thread, "turn_id": "01a03065-100a", "agent_id": agent,
            "tool_name": "Bash", "tool_use_id": "exec-sub"
        ])
        turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.turnID == turnID, "the subagent's turn id was never adopted")
        #expect(
            turn.pendingApproval?.toolUseID == "call-main",
            "a subagent finishing a call is not the human answering the row's dialog"
        )
        #expect(turn.openToolUse?.id == "call-main")
        #expect(turn.status == .approvalNeeded)
        #expect(turn.lastEventAt == Date(timeIntervalSince1970: 101.03))

        // And the row's own answer still closes the row's own wait.
        try deliver([
            "received_at": 105.0, "hook_event_name": "PostToolUse",
            "session_id": thread, "turn_id": turnID,
            "tool_name": "Bash", "tool_use_id": "call-main"
        ])
        turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.pendingApproval == nil)
        #expect(turn.status == .running)
    }

    /// A refusal closes nothing, so the subagent carrying on has to.
    ///
    /// Neither product sends anything when a human says no: Codex measured
    /// 2026-08-15 (67 seconds of silence), Claude Code measured 2026-08-23,
    /// where `PermissionDenied` turns out to fire only for the auto-mode
    /// classifier. What does arrive is the subagent's next call, and in the
    /// measured Codex stream a subagent really does open more than one.
    @Test @MainActor
    func aRefusedSubagentCallStopsSayingApprovalNeeded() async throws {
        for vocabulary in [
            AnyHookVocabularyCase.codex, .claudeCode
        ] {
            let paths = makeTemporaryHookPaths()
            defer {
                try? FileManager.default.removeItem(
                    at: paths.supportDirectory.deletingLastPathComponent()
                )
            }
            let repository = HookEventRepository(
                paths: paths,
                vocabulary: vocabulary.vocabulary
            )
            let thread = "thread-1"
            let turnID = "turn-1"
            let agent = "agent-1"
            let key = vocabulary.turnKey

            func deliver(_ body: [String: Any]) throws {
                try JSONSerialization.data(withJSONObject: body).deliver(to: repository)
            }

            try deliver([
                "received_at": 100.0, "hook_event_name": "UserPromptSubmit",
                "session_id": thread, key: turnID
            ])
            try deliver([
                "received_at": 101.0, "hook_event_name": "SubagentStart",
                "session_id": thread, key: turnID, "agent_id": agent,
                "agent_type": "general-purpose"
            ])
            try deliver([
                "received_at": 102.0, "hook_event_name": "PreToolUse",
                "session_id": thread, key: turnID, "agent_id": agent,
                "tool_name": "Bash", "tool_use_id": "call-1"
            ])
            try deliver([
                "received_at": 102.03, "hook_event_name": "PermissionRequest",
                "session_id": thread, key: turnID, "agent_id": agent,
                "tool_name": "Bash"
            ])
            var turn = try #require(await repository.drainDeliveredEvents().turns.first)
            #expect(
                turn.subagentsAwaitingApproval,
                "\(vocabulary.name): the dialog is open"
            )

            // The human says no. Nothing at all arrives for `call-1` — ever.
            // The subagent tries something else instead, and that is the proof
            // it is no longer blocked.
            try deliver([
                "received_at": 140.0, "hook_event_name": "PreToolUse",
                "session_id": thread, key: turnID, "agent_id": agent,
                "tool_name": "Bash", "tool_use_id": "call-2"
            ])
            turn = try #require(await repository.drainDeliveredEvents().turns.first)
            #expect(
                turn.subagentsAwaitingApproval == false,
                "\(vocabulary.name): the human answered, whatever they answered"
            )
            #expect(turn.runningSubagentIDs == [agent])
        }
    }

    /// Whatever else happens, a subagent stopping ends everything it was
